    private CompiledArchitectureGate() {}

    public static void main(String[] arguments) {
        int code = run(arguments, System.out, System.err);
        if (code != 0) System.exit(code);
    }

    public static int run(String[] arguments, PrintStream out, PrintStream err) {
        try {
            Arguments parsed = Arguments.parse(arguments);
            List<Violation> violations = new ArrayList<>();
            for (VariantArguments variant : parsed.variants) {
                VariantAudit audit = loadVariant(variant, violations);
                if (audit != null) inspectVariant(audit, violations, parsed.writeBaseline, out);
            }
            violations.sort(Comparator.naturalOrder());
            if (!violations.isEmpty()) {
                err.printf(Locale.ROOT, "compiled architecture gate failed: %d violation(s)%n", violations.size());
                for (Violation violation : violations) err.println(violation);
                return 1;
            }
            out.printf(
                    Locale.ROOT,
                    "compiled architecture gate passed: %d variant(s)%n",
                    parsed.variants.size());
            return 0;
        } catch (GateException exception) {
            err.println("compiled architecture gate failed: " + exception.getMessage());
            return 1;
        } catch (RuntimeException exception) {
            err.println("compiled architecture gate failed: internal-error:" + exception.getClass().getSimpleName());
            return 1;
        }
    }

    private static VariantAudit loadVariant(
            VariantArguments variant, List<Violation> violations) throws GateException {
        List<Path> projectArtifacts = readManifest(variant.projectManifest, variant.name, "PROJECT");
        List<Path> allArtifacts = readManifest(variant.allManifest, variant.name, "ALL");
        ArtifactLoader loader = new ArtifactLoader(variant.name, violations);
        Map<String, ClassRecord> project = loader.load(projectArtifacts, Subject.PROJECT);
        Map<String, ClassRecord> all = loader.load(allArtifacts, Subject.ALL);
        if (project.isEmpty()) {
            throw new GateException("variant=" + variant.name + " PROJECT manifest contains no classes");
        }
        Map<String, ClassRecord> hierarchy = new LinkedHashMap<>(all);
        for (ClassRecord record : project.values()) {
            ClassRecord allRecord = all.get(record.info.name);
            if (allRecord == null) {
                violations.add(
                        new Violation(
                                variant.name,
                                record.info.name,
                                "PROJECT_NOT_IN_ALL",
                                "PROJECT binary is missing from ALL hierarchy"));
            } else if (!MessageDigest.isEqual(record.digest, allRecord.digest)) {
                violations.add(
                        new Violation(
                                variant.name,
                                record.info.name,
                                "PROJECT_ALL_MISMATCH",
                                "PROJECT and ALL binary bytes differ"));
            }
        }
        mergeRecords(hierarchy, project, variant.name, "ALL+PROJECT", violations);
        return new VariantAudit(variant.name, project, hierarchy);
    }

    private static List<Path> readManifest(Path manifest, String variant, String subject)
            throws GateException {
        if (!manifest.isAbsolute() || !Files.isRegularFile(manifest)) {
            throw new GateException(
                    "variant=" + variant + " " + subject + " manifest is not an absolute regular file");
        }
        byte[] bytes;
        try {
            bytes = Files.readAllBytes(manifest);
        } catch (IOException exception) {
            throw new GateException("variant=" + variant + " cannot read " + subject + " manifest");
        }
        String contents;
        try {
            contents =
                    StandardCharsets.UTF_8
                            .newDecoder()
                            .onMalformedInput(CodingErrorAction.REPORT)
                            .onUnmappableCharacter(CodingErrorAction.REPORT)
                            .decode(java.nio.ByteBuffer.wrap(bytes))
                            .toString();
        } catch (CharacterCodingException exception) {
            throw new GateException("variant=" + variant + " " + subject + " manifest is not UTF-8");
        }
        if (contents.isEmpty()) {
            throw new GateException("variant=" + variant + " " + subject + " manifest is empty");
        }
        String[] entries = contents.split("\u0000", -1);
        int limit = entries.length;
        if (entries[entries.length - 1].isEmpty()) limit--;
        if (limit == 0) {
            throw new GateException("variant=" + variant + " " + subject + " manifest is empty");
        }
        List<Path> result = new ArrayList<>(limit);
        Set<Path> seen = new HashSet<>();
        for (int index = 0; index < limit; index++) {
            String raw = entries[index];
            if (raw.isEmpty() || raw.indexOf('\n') >= 0 || raw.indexOf('\r') >= 0) {
                throw new GateException(
                        "variant=" + variant + " " + subject + " manifest has invalid entry " + index);
            }
            Path path;
            try {
                path = Paths.get(raw).normalize();
            } catch (RuntimeException exception) {
                throw new GateException(
                        "variant=" + variant + " " + subject + " manifest has invalid path " + index);
            }
            if (!path.isAbsolute()) {
                throw new GateException(
                        "variant=" + variant + " " + subject + " manifest entry is not absolute " + index);
            }
            if (!seen.add(path)) {
                throw new GateException(
                        "variant=" + variant + " " + subject + " manifest repeats an artifact");
            }
            result.add(path);
        }
        return List.copyOf(result);
    }

    private static void mergeRecords(
            Map<String, ClassRecord> destination,
            Map<String, ClassRecord> incoming,
            String variant,
            String subject,
            List<Violation> violations) {
        for (ClassRecord record : incoming.values()) {
            ClassRecord previous = destination.putIfAbsent(record.info.name, record);
            if (previous != null && !MessageDigest.isEqual(previous.digest, record.digest)) {
                violations.add(
                        new Violation(
                                variant,
                                record.info.name,
                                "DUPLICATE_BINARY",
                                subject + " defines one binary with different bytes"));
            }
        }
    }

