    private static void inspectCmp006LifecycleShape(
            VariantAudit audit, ClassInfo subject, List<Violation> violations) {
        Map<String, String> fields = subject.declaredFields.stream()
                .filter(field -> field.name.equals("screenOffReceiver")
                        || field.name.equals("screenOffReceiverRegistered")
                        || field.name.equals("voiceRestartBlockedByLifecycle"))
                .collect(java.util.stream.Collectors.toMap(
                        field -> field.name, field -> field.descriptor));
        boolean exactFields = fields.equals(Map.of(
                        "screenOffReceiver", "Landroid/content/BroadcastReceiver;",
                        "screenOffReceiverRegistered", "Z",
                        "voiceRestartBlockedByLifecycle", "Z"))
                && subject.declaredFields.stream()
                        .filter(field -> fields.containsKey(field.name))
                        .allMatch(field -> (field.access & Opcodes.ACC_PRIVATE) != 0
                                && (field.name.equals("screenOffReceiver")
                                        ? (field.access & Opcodes.ACC_FINAL) != 0
                                        : (field.access & Opcodes.ACC_FINAL) == 0));

        Map<String, Integer> requiredMethods = Map.of(
                "cancelVoiceForLifecycle()V", Opcodes.ACC_PRIVATE,
                "createScreenOffReceiver(Ljava/lang/Runnable;)Landroid/content/BroadcastReceiver;",
                        Opcodes.ACC_STATIC,
                "cancelControllerForLifecycle(L" + VOICE_CONTROLLER + ";)V",
                        Opcodes.ACC_STATIC,
                "lifecycleRestartBlocked(ZZZ)Z", Opcodes.ACC_STATIC,
                "registerScreenOffReceiver()V", Opcodes.ACC_PRIVATE,
                "unregisterScreenOffReceiver()V", Opcodes.ACC_PRIVATE);
        boolean exactMethods = requiredMethods.entrySet().stream().allMatch(required ->
                subject.declaredMethods.stream().anyMatch(method ->
                        (method.name + method.descriptor).equals(required.getKey())
                                && (method.access & required.getValue()) == required.getValue()
                                && (required.getValue() == Opcodes.ACC_STATIC
                                        ? (method.access
                                                        & (Opcodes.ACC_PUBLIC
                                                                | Opcodes.ACC_PROTECTED
                                                                | Opcodes.ACC_PRIVATE))
                                                == 0
                                        : (method.access & Opcodes.ACC_STATIC) == 0)));
        boolean noDeferredFinalization = subject.declaredMethods.stream().noneMatch(method ->
                method.name.equals("forceCloseDestroyedService")
                        || method.name.equals("finishDestroyedService")
                        || method.name.equals("shouldDeferServiceShutdown"))
                && subject.declaredFields.stream().noneMatch(field ->
                        field.name.equals("destroyFinalizationTimeout")
                                || field.name.equals("destroyFinalizationGate"));

        List<ClassInfo> receivers = audit.project.values().stream()
                .map(record -> record.info)
                .filter(info -> IME_SERVICE.equals(info.nestHost)
                        && "android/content/BroadcastReceiver".equals(info.superName))
                .toList();
        boolean exactReceiver = receivers.size() == 1;
        if (exactReceiver) {
            ClassInfo receiver = receivers.get(0);
            long onReceiveMethods = receiver.declaredMethods.stream()
                    .filter(method -> method.name.equals("onReceive")
                            && method.descriptor.equals(
                                    "(Landroid/content/Context;Landroid/content/Intent;)V")
                            && (method.access & Opcodes.ACC_PUBLIC) != 0)
                    .count();
            long actionReads = receiver.methodEdges.stream()
                    .filter(edge -> edge.sourceMethodName.equals("onReceive")
                            && edge.owner.equals("android/content/Intent")
                            && edge.name.equals("getAction")
                            && edge.descriptor.equals("()Ljava/lang/String;"))
                    .count();
            long cancellationRuns = receiver.methodEdges.stream()
                    .filter(edge -> edge.sourceMethodName.equals("onReceive")
                            && edge.owner.equals("java/lang/Runnable")
                            && edge.name.equals("run")
                            && edge.descriptor.equals("()V"))
                    .count();
            exactReceiver = onReceiveMethods == 1 && actionReads == 1 && cancellationRuns == 1;
        }

        if (!exactFields || !exactMethods || !noDeferredFinalization || !exactReceiver) {
            violations.add(
                    violation(
                            audit.name,
                            subject,
                            "CMP006_LIFECYCLE_SHAPE",
                            "IME must own one private screen-off receiver and one exact cancel-only lifecycle boundary"));
        }
    }

    private static void inspectCmp006ProductionEdges(
            VariantAudit audit, List<Violation> violations) {
        Map<String, String> lifecycleMethods = Map.of(
                "onStartInput", "(Landroid/view/inputmethod/EditorInfo;Z)V",
                "onFinishInput", "()V",
                "onFinishInputView", "(Z)V",
                "onWindowHidden", "()V",
                "onDestroy", "()V");
        for (Map.Entry<String, String> lifecycle : lifecycleMethods.entrySet()) {
            requireExactProductionEdge(
                    audit,
                    violations,
                    IME_SERVICE,
                    lifecycle.getKey(),
                    lifecycle.getValue(),
                    IME_SERVICE,
                    "cancelVoiceForLifecycle",
                    "()V",
                    1,
                    "CMP006_EXACT_EDGE");
        }
        requireExactProductionEdge(
                audit,
                violations,
                IME_SERVICE,
                "cancelVoiceForLifecycle",
                "()V",
                IME_SERVICE,
                "cancelControllerForLifecycle",
                "(L" + VOICE_CONTROLLER + ";)V",
                1,
                "CMP006_EXACT_EDGE");
        requireExactProductionEdge(
                audit,
                violations,
                IME_SERVICE,
                "cancelControllerForLifecycle",
                "(L" + VOICE_CONTROLLER + ";)V",
                VOICE_CONTROLLER,
                "cancel",
                "()V",
                1,
                "CMP006_EXACT_EDGE");
        requireExactProductionEdge(
                audit,
                violations,
                IME_SERVICE,
                "onCreate",
                "()V",
                IME_SERVICE,
                "registerScreenOffReceiver",
                "()V",
                1,
                "CMP006_EXACT_EDGE");
        requireExactProductionEdge(
                audit,
                violations,
                IME_SERVICE,
                "onDestroy",
                "()V",
                IME_SERVICE,
                "unregisterScreenOffReceiver",
                "()V",
                1,
                "CMP006_EXACT_EDGE");

        ClassRecord record = audit.project.get(IME_SERVICE);
        if (record == null) return;
        ClassInfo subject = record.info;
        long stopEdges = subject.methodEdges.stream()
                .filter(edge -> edge.sourceMethodName.equals("cancelVoiceForLifecycle")
                        && edge.owner.equals(VOICE_CONTROLLER)
                        && edge.name.equals("stop"))
                .count();
        long prematureReleaseEdges = subject.methodEdges.stream()
                .filter(edge -> edge.sourceMethodName.equals("cancelVoiceForLifecycle")
                        && edge.owner.equals(IME_SERVICE)
                        && edge.name.equals("releaseVoiceCoordinatorAfterEditorLifecycle"))
                .count();
        long lifecycleMethodReferences = subject.methodEdges.stream()
                .filter(edge -> edge.sourceMethodName.equals("<init>")
                        && edge.owner.equals(IME_SERVICE)
                        && edge.name.equals("cancelVoiceForLifecycle")
                        && edge.descriptor.equals("()V"))
                .count();
        long registerEdges = subject.methodEdges.stream()
                .filter(edge -> edge.sourceMethodName.equals("registerScreenOffReceiver")
                        && edge.owner.equals(IME_SERVICE)
                        && edge.name.equals("registerReceiver"))
                .count();
        long unregisterEdges = subject.methodEdges.stream()
                .filter(edge -> edge.sourceMethodName.equals("unregisterScreenOffReceiver")
                        && edge.owner.equals(IME_SERVICE)
                        && edge.name.equals("unregisterReceiver")
                        && edge.descriptor.equals("(Landroid/content/BroadcastReceiver;)V"))
                .count();
        if (stopEdges != 0
                || prematureReleaseEdges != 0
                || lifecycleMethodReferences != 1
                || registerEdges != 2
                || unregisterEdges != 1) {
            violations.add(
                    violation(
                            audit.name,
                            subject,
                            "CMP006_EXACT_EDGE",
                            "screen-off must capture the exact cancellation once; registration must be non-exported and teardown must never stop-and-await-final"));
        }
    }

    private static void inspectStr010ProductionEdges(
            VariantAudit audit, List<Violation> violations) {
        String select = "(Landroid/content/Context;L" + VOICE_PIPELINE_ADAPTER + ";)L"
                + VOICE_CONTROLLER + ";";
        requireExactProductionEdge(
                audit,
                violations,
                IME_SERVICE,
                "onCreate",
                "()V",
                RECOGNITION_ROUTER_VOICE_CONFIG,
                "select",
                select,
                1,
                "STR010_EXACT_EDGE");
        requireExactProductionEdge(
                audit,
                violations,
                VOICE_LAB_ACTIVITY,
                "onCreate",
                "(Landroid/os/Bundle;)V",
                RECOGNITION_ROUTER_VOICE_CONFIG,
                "select",
                select,
                1,
                "STR010_EXACT_EDGE");
        requireExactProductionEdge(
                audit,
                violations,
                VOICE_PIPELINE_RECOGNITION_ENGINE,
                "<init>",
                "(Landroid/content/Context;)V",
                RECOGNITION_ROUTER_VOICE_CONFIG,
                "select",
                select,
                1,
                "STR010_EXACT_EDGE");

        String controllerConstructor = "(Landroid/content/Context;L"
                + VOICE_PIPELINE_ADAPTER + ";)V";
        long selectCallers = 0;
        long constructorCallers = 0;
        for (ClassRecord record : audit.project.values()) {
            for (MethodEdge edge : record.info.methodEdges) {
                if (edge.owner.equals(RECOGNITION_ROUTER_VOICE_CONFIG)
                        && edge.name.equals("select")
                        && edge.descriptor.equals(select)) {
                    selectCallers++;
                }
                if (edge.owner.equals(RECOGNITION_ROUTER_VOICE_CONTROLLER)
                        && edge.name.equals("<init>")
                        && edge.descriptor.equals(controllerConstructor)) {
                    constructorCallers++;
                }
            }
        }
        if (selectCallers != 3 || constructorCallers != 1) {
            violations.add(new Violation(
                    audit.name,
                    RECOGNITION_ROUTER_VOICE_CONFIG,
                    "STR010_EXACT_EDGE",
                    "whole-controller flag must have exactly three production selectors and one constructor edge; selectors="
                            + selectCallers + " constructors=" + constructorCallers));
        }
    }

    private static void inspectVoc001ProductionEdges(
            VariantAudit audit, List<Violation> violations) {
        requireExactProductionEdge(
                audit,
                violations,
                IME_SERVICE,
                "onCreate",
                "()V",
                VOICE_PIPELINE_ADAPTER,
                "<init>",
                "(L" + VOICE_PIPELINE + ";)V",
                1,
                "VOC001_EXACT_EDGE");
        requireExactProductionEdge(
                audit,
                violations,
                VOICE_LAB_ACTIVITY,
                "onCreate",
                "(Landroid/os/Bundle;)V",
                VOICE_PIPELINE_ADAPTER,
                "<init>",
                "(L" + VOICE_PIPELINE + ";)V",
                1,
                "VOC001_EXACT_EDGE");
        requireExactProductionEdge(
                audit,
                violations,
                VOICE_PIPELINE_RECOGNITION_ENGINE,
                "<init>",
                "(Landroid/content/Context;)V",
                VOICE_PIPELINE_ADAPTER,
                "<init>",
                "(L" + VOICE_PIPELINE + ";)V",
                1,
                "VOC001_EXACT_EDGE");

        Map<String, Set<String>> requiredCalls = Map.of(
                IME_SERVICE, Set.of("start", "stop", "cancel", "state"),
                VOICE_LAB_ACTIVITY, Set.of("start", "stop"),
                VOICE_PIPELINE_RECOGNITION_ENGINE, Set.of("start", "stop", "cancel"));
        for (Map.Entry<String, Set<String>> entry : requiredCalls.entrySet()) {
            ClassRecord record = audit.project.get(entry.getKey());
            if (record == null) continue;
            ClassInfo subject = record.info;
            List<FieldDeclaration> fields = subject.declaredFields.stream()
                    .filter(field -> field.descriptor.equals("L" + VOICE_CONTROLLER + ";"))
                    .toList();
            boolean exactField = fields.size() == 1
                    && fields.get(0).name.equals("voiceController")
                    && (fields.get(0).access & Opcodes.ACC_PRIVATE) != 0;
            Set<String> observed = subject.methodEdges.stream()
                    .filter(edge -> edge.owner.equals(VOICE_CONTROLLER))
                    .map(MethodEdge::name)
                    .collect(java.util.stream.Collectors.toSet());
            if (!exactField || !observed.containsAll(entry.getValue())) {
                violations.add(
                        violation(
                                audit.name,
                                subject,
                                "VOC001_CONTROLLER_CALLER",
                                "production caller must own one controller and use its exact core surface"));
            }
        }
    }

