    private static void inspectVoiceWriterBranching(
            VariantAudit audit, List<Violation> violations) {
        ClassRecord service = audit.project.get(IME_SERVICE);
        if (service == null) return;
        boolean transcript = hasEarlyReturnBeforeLegacyCall(
                service.info,
                "applyTranscriptUpdate",
                "(L" + IME_SERVICE
                        + "$CommitTarget;Lcom/opentypeless/android/ime/TranscriptUpdate;)V",
                "applyVoiceTransactionUpdate",
                Set.of("applySpeechCoreProjection", "apply"));
        boolean terminal = hasEarlyReturnBeforeLegacyCall(
                service.info,
                "commitResult",
                "(L" + IME_SERVICE
                        + "$CommitTarget;Lcom/opentypeless/android/ime/DictationResult;)V",
                "commitVoiceTransactionResult",
                Set.of("commitSpeechCoreV2Result", "targetStillValid"));
        boolean construction = hasMutuallyExclusiveVoiceConstruction(service.info);
        if (!transcript || !terminal || !construction) {
            violations.add(
                    new Violation(
                            audit.name,
                            IME_SERVICE,
                            "EDT017_WRITER_MUTUAL_EXCLUSION",
                            "voice partial/final/session construction must return from one frozen writer branch"));
        }
    }

    private static boolean hasEarlyReturnBeforeLegacyCall(
            ClassInfo owner,
            String methodName,
            String descriptor,
            String transactionHelper,
            Set<String> legacyCalls) {
        MethodNode method = findMethod(owner, methodName, descriptor);
        if (method == null) return false;
        AbstractInsnNode[] instructions = method.instructions.toArray();
        int transaction = -1;
        int legacy = Integer.MAX_VALUE;
        for (int index = 0; index < instructions.length; index++) {
            if (!(instructions[index] instanceof MethodInsnNode call)) continue;
            if (call.owner.equals(IME_SERVICE) && call.name.equals(transactionHelper)) {
                transaction = index;
            }
            if ((call.owner.equals(IME_SERVICE)
                            || call.owner.equals("com/opentypeless/android/ime/VoiceCompositionSession"))
                    && legacyCalls.contains(call.name)) {
                legacy = Math.min(legacy, index);
            }
        }
        if (transaction < 0 || legacy == Integer.MAX_VALUE || transaction >= legacy) return false;
        for (int index = transaction + 1; index < legacy; index++) {
            if (instructions[index].getOpcode() == Opcodes.RETURN) return true;
        }
        return false;
    }

    private static boolean hasMutuallyExclusiveVoiceConstruction(ClassInfo owner) {
        MethodNode method = findMethod(owner, "toggleRecording",
                "(Lcom/opentypeless/android/ime/DictationRequest$CaptureMode;)V");
        if (method == null) return false;
        AbstractInsnNode[] instructions = method.instructions.toArray();
        int transactionNew = -1;
        int legacyNew = -1;
        for (int index = 0; index < instructions.length; index++) {
            if (instructions[index] instanceof MethodInsnNode call
                    && call.owner.equals(VOICE_TRANSACTION_SESSION)
                    && call.name.equals("acquire")) {
                transactionNew = index;
            }
            if (!(instructions[index] instanceof TypeInsnNode type)
                    || type.getOpcode() != Opcodes.NEW) continue;
            if (type.desc.equals("com/opentypeless/android/ime/VoiceCompositionSession")) {
                legacyNew = index;
            }
        }
        if (transactionNew < 0 || legacyNew < 0 || transactionNew >= legacyNew) return false;
        for (int index = transactionNew + 1; index < legacyNew; index++) {
            if (instructions[index] instanceof JumpInsnNode jump
                    && jump.getOpcode() == Opcodes.GOTO
                    && method.instructions.indexOf(jump.label) > legacyNew) {
                return true;
            }
        }
        return false;
    }

    private static String rawTransitionConstructorDescriptor() {
        return "(Ljava/lang/Object;JJJL" + EDITOR_SESSION_MANAGER + "$ActiveEditor;"
                + "Lcom/opentypeless/android/editor/TextRange;"
                + "Lcom/opentypeless/android/editor/TextRange;"
                + "Lcom/opentypeless/android/editor/TextRange;L" + RAW_PROOF_STATE + ";"
                + "Lcom/opentypeless/android/editor/EditorSessionSnapshot;"
                + "Lcom/opentypeless/android/editor/TextFingerprint;"
                + "Lcom/opentypeless/android/editor/TextFingerprint;)V";
    }

    private static void requireExactProductionTargetCount(
            VariantAudit audit,
            List<Violation> violations,
            String sourceOwner,
            String targetOwner,
            String targetName,
            String targetDescriptor,
            long expected,
            String rule) {
        ClassRecord record = audit.project.get(sourceOwner);
        long observed = record == null ? 0 : record.info.methodEdges.stream()
                .filter(edge -> edge.owner.equals(targetOwner)
                        && edge.name.equals(targetName)
                        && edge.descriptor.equals(targetDescriptor))
                .count();
        if (observed != expected) {
            violations.add(
                    new Violation(
                            audit.name,
                            sourceOwner,
                            rule,
                            targetOwner + "." + targetName + targetDescriptor + " expected="
                                    + expected + " actual=" + observed));
        }
    }

    private static void requireExactProductionEdge(
            VariantAudit audit,
            List<Violation> violations,
            String sourceOwner,
            String sourceName,
            String sourceDescriptor,
            String targetOwner,
            String targetName,
            String targetDescriptor,
            long expected) {
        requireExactProductionEdge(
                audit,
                violations,
                sourceOwner,
                sourceName,
                sourceDescriptor,
                targetOwner,
                targetName,
                targetDescriptor,
                expected,
                "EDT011_EXACT_EDGE");
    }

    private static void requireExactProductionEdge(
            VariantAudit audit,
            List<Violation> violations,
            String sourceOwner,
            String sourceName,
            String sourceDescriptor,
            String targetOwner,
            String targetName,
            String targetDescriptor,
            long expected,
            String rule) {
        ClassRecord record = audit.project.get(sourceOwner);
        long observed = record == null ? 0 : record.info.methodEdges.stream()
                .filter(edge -> edge.sourceMethodName.equals(sourceName)
                        && edge.sourceMethodDescriptor.equals(sourceDescriptor)
                        && edge.owner.equals(targetOwner)
                        && edge.name.equals(targetName)
                        && edge.descriptor.equals(targetDescriptor))
                .count();
        if (observed != expected) {
            violations.add(
                    new Violation(
                            audit.name,
                            sourceOwner,
                            rule,
                            sourceName + sourceDescriptor + " -> " + targetOwner + "."
                                    + targetName + targetDescriptor + " expected=" + expected
                                    + " actual=" + observed));
        }
    }

    private static boolean isAllowedCommitLedgerExactIdCall(
            ClassInfo subject, MethodEdge edge) {
        if (!edge.descriptor.equals(COMMIT_LEDGER_EXACT_ID_DESCRIPTOR)) return false;
        if (subject.name.equals(COMMIT_LEDGER)) {
            return edge.name.equals("resolve")
                    && edge.sourceMethodName.equals("consume")
                    && edge.sourceMethodDescriptor.equals(COMMIT_LEDGER_EXACT_ID_DESCRIPTOR);
        }
        if (!subject.name.equals(EDITOR_TRANSACTION_MANAGER)) return false;
        if (edge.name.equals("resolve")) {
            return (edge.sourceMethodName.equals("undoCommit")
                            && edge.sourceMethodDescriptor.equals(UNDO_FACADE_DESCRIPTOR))
                    || (edge.sourceMethodName.equals("restoreRawCommit")
                            && edge.sourceMethodDescriptor.equals(RAW_RESTORE_FACADE_DESCRIPTOR))
                    || (edge.sourceMethodName.equals("resolveCommitRecord")
                            && edge.sourceMethodDescriptor.equals(COMMIT_LEDGER_EXACT_ID_DESCRIPTOR));
        }
        return (edge.sourceMethodName.equals("updateLedgerForUndo")
                        && edge.sourceMethodDescriptor.equals(
                                "(Lcom/opentypeless/android/editor/EditorTransactionResult;"
                                        + "Ljava/lang/String;Lcom/opentypeless/android/editor/"
                                        + "EditorSessionSnapshot;)V"))
                || (edge.sourceMethodName.equals("consumeCommitRecord")
                        && edge.sourceMethodDescriptor.equals(COMMIT_LEDGER_EXACT_ID_DESCRIPTOR))
                || (edge.sourceMethodName.equals("updateLedgerForRaw")
                        && edge.sourceMethodDescriptor.equals(
                                "(Lcom/opentypeless/android/editor/EditorTransactionResult;"
                                        + "Ljava/lang/String;Lcom/opentypeless/android/editor/"
                                        + "EditorSessionSnapshot;)V"));
    }

    private static void inspectCfg001Contract(
            String variant, ClassInfo subject, List<Violation> violations) {
        if (!CONFIG_REQUIRED_TYPES.contains(subject.name)) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "CFG001_EXTRA_BINARY",
                            "config package is closed to the exact CFG-001 through CFG-005 binaries"));
            return;
        }

        if (subject.name.equals(PROVIDER_CONFIG)) {
            inspectProviderConfigInterface(variant, subject, violations);
        } else if (subject.name.equals(PROVIDER_CONFIG_ASR)
                || subject.name.equals(PROVIDER_CONFIG_LLM)
                || subject.name.equals(PROVIDER_CONFIG_CONNECTOR)
                || subject.name.equals(PROVIDER_CONFIG_ENDPOINT)) {
            inspectProviderConfigRecord(variant, subject, violations);
        } else if (subject.name.equals(SECRET_REF)) {
            inspectSecretRefRecord(variant, subject, violations);
        } else if (subject.name.equals(SECRET_REF_KIND)) {
            inspectSecretRefKind(variant, subject, violations);
        } else if (subject.name.equals(RECOGNITION_ROUTE)) {
            inspectRecognitionRouteRecord(variant, subject, violations);
        } else if (subject.name.equals(RECOGNITION_ROUTE_STEP)) {
            inspectRecognitionRouteStepRecord(variant, subject, violations);
        } else if (subject.name.equals(RECOGNITION_RETRY_POLICY)) {
            inspectRecognitionRetryPolicyRecord(variant, subject, violations);
        } else if (subject.name.equals(RECOGNITION_PRIVACY_CLASS)) {
            inspectRecognitionRouteEnum(
                    variant,
                    subject,
                    List.of("ON_DEVICE", "LOCAL_NETWORK", "PUBLIC_NETWORK"),
                    violations);
        } else if (subject.name.equals(RECOGNITION_PROVIDER_CAPABILITY)) {
            inspectRecognitionRouteEnum(
                    variant,
                    subject,
                    List.of(
                            "STREAMING",
                            "PARTIAL_REVISION",
                            "ENDPOINTING",
                            "ON_DEVICE",
                            "PROMPT",
                            "BIASING_TERMS",
                            "DYNAMIC_KEYTERMS",
                            "LANGUAGE_DETECTION",
                            "TIMESTAMPS",
                            "AUDIO_UPLOAD"),
                    violations);
        } else if (subject.name.equals(RECOGNITION_FAILURE_CLASS)) {
            inspectRecognitionRouteEnum(
                    variant,
                    subject,
                    List.of(
                            "UNAVAILABLE",
                            "MODEL_MISSING",
                            "PERMISSION_DENIED",
                            "OEM_MIC_BLOCKED",
                            "AUDIO_ERROR",
                            "NETWORK_UNAVAILABLE",
                            "NETWORK_TIMEOUT",
                            "AUTHENTICATION",
                            "QUOTA_EXCEEDED",
                            "RATE_LIMITED",
                            "SERVER_ERROR",
                            "PROTOCOL_ERROR",
                            "RECOGNIZER_BUSY",
                            "NO_MATCH",
                            "SPEECH_TIMEOUT",
                            "UNSUPPORTED_LANGUAGE",
                            "CANCELLED",
                            "TARGET_CHANGED",
                            "INTERNAL_ERROR"),
                    violations);
        } else if (subject.name.equals(RECOGNITION_CONFIRMATION_POLICY)) {
            inspectRecognitionRouteEnum(
                    variant,
                    subject,
                    List.of(
                            "NOT_REQUIRED",
                            "REQUIRE_ON_PRIVACY_DOWNGRADE",
                            "REQUIRE_BEFORE_USE"),
                    violations);
        } else if (subject.name.equals(OVERRIDE_VALUE)) {
            inspectOverrideValueInterface(variant, subject, violations);
        } else if (subject.name.equals(OVERRIDE_VALUE_INHERIT)
                || subject.name.equals(OVERRIDE_VALUE_DISABLED)) {
            inspectOverrideValueSingleton(variant, subject, violations);
        } else if (subject.name.equals(OVERRIDE_VALUE_EXPLICIT)) {
            inspectOverrideValueRecord(variant, subject, violations);
        } else if (subject.name.equals(OVERRIDE_VALUE_CODEC)) {
            inspectOverrideValueCodec(variant, subject, violations);
        } else if (subject.name.equals(OVERRIDE_SCALAR_CODEC)) {
            inspectOverrideScalarCodec(variant, subject, violations);
        } else if (subject.name.equals(OVERRIDE_DB_ROW)) {
            inspectOverrideDbRow(variant, subject, violations);
        } else if (subject.name.equals(OVERRIDE_FORMAT_EXCEPTION)) {
            inspectOverrideFormatException(variant, subject, violations);
        } else if (subject.name.equals(PROCESSING_MODE)) {
            inspectCfg004ProcessingMode(variant, subject, violations);
        } else if (CFG004_REQUIRED_TYPES.contains(subject.name)) {
            inspectCfg004Record(variant, subject, violations);
        } else if (CFG005_REQUIRED_TYPES.contains(subject.name)) {
            inspectCfg005Contract(variant, subject, violations);
        } else if (subject.name.equals(APP_PICKER_MODEL)
                || subject.name.equals(APP_PICKER_ENTRY)) {
            inspectCfg009Model(variant, subject, violations);
        }

        if (subject.name.equals(RECOGNITION_ROUTE)
                || RECOGNITION_ROUTE.equals(subject.nestHost)) {
            Set<String> forbiddenRouteAuthority = Set.of(
                    PROVIDER_CONFIG,
                    PROVIDER_CONFIG_ASR,
                    PROVIDER_CONFIG_LLM,
                    PROVIDER_CONFIG_CONNECTOR,
                    PROVIDER_CONFIG_ENDPOINT,
                    SECRET_REF,
                    SECRET_REF_KIND,
                    "com/opentypeless/android/diagnostics/RecognitionRoute",
                    "com/opentypeless/android/settings/RecognitionBackend",
                    "java/net/URI",
                    "java/net/URISyntaxException");
            if (referencesAnyType(subject, forbiddenRouteAuthority)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "CFG002_AUTHORITY_BOUNDARY",
                                "route config may not carry provider, endpoint, secret, legacy route, or execution authority"));
            }
        }

        if (subject.name.equals(OVERRIDE_VALUE)
                || OVERRIDE_VALUE.equals(subject.nestHost)) {
            if (referencesAnyType(subject, Set.of(
                    OVERRIDE_VALUE_CODEC,
                    OVERRIDE_SCALAR_CODEC,
                    OVERRIDE_DB_ROW,
                    OVERRIDE_FORMAT_EXCEPTION,
                    PROVIDER_CONFIG,
                    SECRET_REF,
                    RECOGNITION_ROUTE))) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "CFG003_MODEL_AUTHORITY",
                                "three-state domain values may not depend on codecs or other config authority"));
            }
        }
        if (subject.name.equals(OVERRIDE_VALUE_CODEC)
                || OVERRIDE_VALUE_CODEC.equals(subject.nestHost)) {
            inspectOverrideCodecAuthority(variant, subject, violations);
        }
        if (CFG004_REQUIRED_TYPES.contains(subject.name)) {
            inspectCfg004Authority(variant, subject, violations);
        }
        if (CFG005_REQUIRED_TYPES.contains(subject.name)) {
            inspectCfg005Authority(variant, subject, violations);
        }
        inspectCfg005FactoryAuthority(variant, subject, violations);

        for (TypeEdge edge : subject.typeEdges) {
            if (isCfg001ForbiddenType(edge.type)
                    && !isExactCfg003JsonEdge(subject, edge.type)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "CFG001_DOMAIN_DEPENDENCY",
                                edge.kind.externalName + " references " + edge.type));
            }
        }
        for (MethodEdge edge : subject.methodEdges) {
            if ((isCfg001ForbiddenType(edge.owner)
                            && !isExactCfg003JsonEdge(subject, edge.owner))
                    || edge.owner.equals("java/lang/System")
                    || edge.owner.equals("java/lang/Runtime")
                    || edge.owner.equals("java/lang/Thread")
                    || edge.owner.startsWith("java/util/concurrent/")) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "CFG001_EXECUTION_EDGE",
                                edge.sourceMethodName + edge.sourceMethodDescriptor
                                        + " invokes " + edge.owner + "." + edge.name));
            }
        }
    }

    private static boolean isExactCfg003JsonEdge(ClassInfo subject, String type) {
        return subject.name.equals(OVERRIDE_VALUE_CODEC)
                && type != null
                && type.startsWith("org/json/");
    }

    private static void inspectRec001Contract(
            String variant, ClassInfo subject, List<Violation> violations) {
        if (subject.name.equals(PROVIDER_CAPABILITIES)) {
            inspectRec001Capabilities(variant, subject, violations);
        } else if (subject.name.equals(PROVIDER_AUDIO_FORMAT)) {
            inspectRec001AudioFormat(variant, subject, violations);
        } else if (subject.name.equals(PROVIDER_IMPLEMENTATION_KIND)) {
            inspectRec001ImplementationKind(variant, subject, violations);
        } else if (subject.name.equals(PROVIDER_DESCRIPTOR)) {
            inspectRec001Descriptor(variant, subject, violations);
        }

        Set<String> forbiddenTypes = Set.of(
                PROVIDER_CONFIG,
                PROVIDER_CONFIG_ASR,
                PROVIDER_CONFIG_LLM,
                PROVIDER_CONFIG_CONNECTOR,
                PROVIDER_CONFIG_ENDPOINT,
                SECRET_REF,
                SECRET_REF_KIND,
                INPUT_CONNECTION,
                INPUT_METHOD_SERVICE,
                "java/net/URI",
                "java/net/URL");
        if (referencesAnyType(subject, forbiddenTypes)) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "REC001_DOMAIN_DEPENDENCY",
                            "provider descriptors cannot carry config, endpoint, secret, Android, or execution authority"));
        }
        for (TypeEdge edge : subject.typeEdges) {
            if (isCfg001ForbiddenType(edge.type)
                    && !edge.type.equals(RECOGNITION_BACKEND)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "REC001_DOMAIN_DEPENDENCY",
                                edge.kind.externalName + " references " + edge.type));
            }
        }
    }

    private static void inspectRec001Capabilities(
            String variant, ClassInfo subject, List<Violation> violations) {
        String constructor = "(ZZZZZZZZZZL" + PROVIDER_IMPLEMENTATION_KIND + ";L"
                + RECOGNITION_PRIVACY_CLASS
                + ";Ljava/lang/Long;Ljava/util/Set;)V";
        String factory = "(L" + RECOGNITION_BACKEND + ";)L" + PROVIDER_CAPABILITIES + ";";
        String prefixFactory = "()L" + PROVIDER_CAPABILITIES + ";";
        List<String> fields = List.of(
                "supportsStreaming:Z",
                "supportsPartialRevision:Z",
                "supportsEndpointing:Z",
                "supportsOnDevice:Z",
                "supportsPrompt:Z",
                "supportsBiasingTerms:Z",
                "supportsDynamicKeyterms:Z",
                "supportsLanguageDetection:Z",
                "supportsTimestamps:Z",
                "supportsAudioUpload:Z",
                "implementationKind:L" + PROVIDER_IMPLEMENTATION_KIND + ";",
                "privacyClass:L" + RECOGNITION_PRIVACY_CLASS + ";",
                "maxAudioDurationMs:Ljava/lang/Long;",
                "supportedAudioFormats:Ljava/util/Set;",
                "MAX_DECLARED_AUDIO_DURATION_MS:J",
                "APP_CAPTURE_LIMIT_MS:J",
                "PCM_16_MONO_16_KHZ:Ljava/util/Set;");
        Set<String> methods = Set.of(
                "<init>" + constructor,
                "declaredForBackend" + factory,
                "toString()Ljava/lang/String;",
                "hashCode()I",
                "equals(Ljava/lang/Object;)Z",
                "supportsStreaming()Z",
                "supportsPartialRevision()Z",
                "supportsEndpointing()Z",
                "supportsOnDevice()Z",
                "supportsPrompt()Z",
                "supportsBiasingTerms()Z",
                "supportsDynamicKeyterms()Z",
                "supportsLanguageDetection()Z",
                "supportsTimestamps()Z",
                "supportsAudioUpload()Z",
                "implementationKind()L" + PROVIDER_IMPLEMENTATION_KIND + ";",
                "privacyClass()L" + RECOGNITION_PRIVACY_CLASS + ";",
                "maxAudioDurationMs()Ljava/lang/Long;",
                "supportedAudioFormats()Ljava/util/Set;");
        boolean fieldAccess = subject.declaredFields.size() == fields.size();
        for (int index = 0; fieldAccess && index < subject.declaredFields.size(); index++) {
            FieldDeclaration field = subject.declaredFields.get(index);
            int expected = index < 14
                    ? Opcodes.ACC_PRIVATE | Opcodes.ACC_FINAL
                    : index < 16
                            ? Opcodes.ACC_PUBLIC | Opcodes.ACC_STATIC | Opcodes.ACC_FINAL
                            : Opcodes.ACC_PRIVATE | Opcodes.ACC_STATIC | Opcodes.ACC_FINAL;
            fieldAccess = (field.access & (Opcodes.ACC_PUBLIC | Opcodes.ACC_PRIVATE
                            | Opcodes.ACC_PROTECTED | Opcodes.ACC_STATIC | Opcodes.ACC_FINAL))
                    == expected;
        }
        boolean genericFormats = fieldHasSignature(
                        subject,
                        "supportedAudioFormats",
                        "Ljava/util/Set<L" + PROVIDER_AUDIO_FORMAT + ";>;")
                && methodHasSignature(
                        subject,
                        "supportedAudioFormats()Ljava/util/Set;",
                        "()Ljava/util/Set<L" + PROVIDER_AUDIO_FORMAT + ";>;");
        boolean explicitFactory = hasExactEdge(
                subject,
                "declaredForBackend",
                factory,
                PROVIDER_CAPABILITIES,
                "<init>",
                constructor,
                5);
        boolean explicitPrefix = hasPackageStaticMethod(
                        subject, "prefixReplayPreview", prefixFactory)
                && hasExactEdge(
                        subject,
                        "prefixReplayPreview",
                        prefixFactory,
                        PROVIDER_CAPABILITIES,
                        "<init>",
                        constructor,
                        1);
        boolean nameInference = subject.methodEdges.stream().anyMatch(edge ->
                edge.sourceMethodName.equals("declaredForBackend")
                        && edge.sourceMethodDescriptor.equals(factory)
                        && (edge.owner.equals("java/lang/String")
                                || (edge.owner.equals("java/lang/Enum")
                                        && edge.name.equals("name"))));
        int expectedAccess = Opcodes.ACC_PUBLIC | Opcodes.ACC_FINAL | Opcodes.ACC_RECORD;
        if ((subject.access & expectedAccess) != expectedAccess
                || !"java/lang/Record".equals(subject.superName)
                || !subject.interfaces.isEmpty()
                || subject.nestHost != null
                || !subject.nestMembers.equals(Set.of(
                        PROVIDER_AUDIO_FORMAT,
                        PROVIDER_IMPLEMENTATION_KIND,
                        PROVIDER_CAPABILITIES + "$1"))
                || !subject.permittedSubclasses.isEmpty()
                || !fieldShape(subject.declaredFields, fields)
                || !fieldAccess
                || !genericFormats
                || !publicMethodSurface(subject).equals(methods)) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "REC001_CAPABILITY_SHAPE",
                            "expected exact immutable ten-flag capability, implementation kind, privacy, duration, and audio-format record"));
        }
        if (!explicitFactory || !explicitPrefix || nameInference) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "REC001_EXPLICIT_DECLARATION",
                            "built-in capabilities must use five explicit backend constructions plus one exact prefix-replay declaration"));
        }
    }

    private static void inspectRec001AudioFormat(
            String variant, ClassInfo subject, List<Violation> violations) {
        String enumType = subject.name;
        List<String> constants = subject.declaredFields.stream()
                .filter(field -> field.descriptor.equals("L" + enumType + ";"))
                .map(FieldDeclaration::name)
                .toList();
        List<FieldDeclaration> support = subject.declaredFields.stream()
                .filter(field -> !field.descriptor.equals("L" + enumType + ";"))
                .toList();
        boolean supportField = support.size() == 1
                && support.get(0).name.equals("$VALUES")
                && support.get(0).descriptor.equals("[L" + enumType + ";")
                && (support.get(0).access
                                & (Opcodes.ACC_PRIVATE | Opcodes.ACC_STATIC | Opcodes.ACC_FINAL))
                        == (Opcodes.ACC_PRIVATE | Opcodes.ACC_STATIC | Opcodes.ACC_FINAL);
        Set<String> methods = Set.of(
                "values()[L" + enumType + ";",
                "valueOf(Ljava/lang/String;)L" + enumType + ";");
        int expectedAccess = Opcodes.ACC_PUBLIC | Opcodes.ACC_FINAL | Opcodes.ACC_ENUM;
        if ((subject.access & expectedAccess) != expectedAccess
                || !"java/lang/Enum".equals(subject.superName)
                || !subject.interfaces.isEmpty()
                || !PROVIDER_CAPABILITIES.equals(subject.nestHost)
                || !subject.nestMembers.isEmpty()
                || !subject.permittedSubclasses.isEmpty()
                || !constants.equals(List.of("PCM_16_MONO_16000_HZ"))
                || !supportField
                || !publicMethodSurface(subject).equals(methods)) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "REC001_AUDIO_FORMAT_SHAPE",
                            "expected exact closed PCM16 mono 16kHz provider audio vocabulary"));
        }
    }

