    private static void inspectStr002Authority(
            String variant, ClassInfo subject, List<Violation> violations) {
        boolean providerFamily = subject.name.equals(WEBSOCKET_STREAMING_PROVIDER)
                || Objects.equals(subject.nestHost, WEBSOCKET_STREAMING_PROVIDER);
        boolean qwenProviderFamily = subject.name.equals(QWEN3_ASR_VLLM_PROVIDER)
                || Objects.equals(subject.nestHost, QWEN3_ASR_VLLM_PROVIDER);
        boolean clientFamily = subject.name.equals(STREAMING_WEBSOCKET_CLIENT)
                || Objects.equals(subject.nestHost, STREAMING_WEBSOCKET_CLIENT);
        for (TypeEdge edge : subject.typeEdges) {
            boolean providerType = edge.type.equals(WEBSOCKET_STREAMING_PROVIDER)
                    || STR002_REQUIRED_TYPES.contains(edge.type)
                            && edge.type.startsWith(WEBSOCKET_STREAMING_PROVIDER + "$");
            boolean clientType = edge.type.equals(STREAMING_WEBSOCKET_CLIENT)
                    || STR002_REQUIRED_TYPES.contains(edge.type)
                            && edge.type.startsWith(STREAMING_WEBSOCKET_CLIENT + "$");
            if (providerType && !(providerFamily || qwenProviderFamily)) {
                violations.add(violation(
                        variant,
                        subject,
                        "STR002_ADAPTER_SCOPE",
                        edge.kind.externalName + " references " + edge.type));
            }
            if (clientType
                    && !(clientFamily
                            || providerFamily
                            || subject.name.equals(WEBSOCKET_STREAMING_CLIENT_BACKEND))) {
                violations.add(violation(
                        variant,
                        subject,
                        "STR002_CLIENT_CALLER",
                        edge.kind.externalName + " references " + edge.type));
            }
        }
        String clientOpen = "(L" + STREAMING_WEBSOCKET_CONFIG + ";[CL"
                + STREAMING_WEBSOCKET_LISTENER + ";)L" + STREAMING_WEBSOCKET_SESSION + ";";
        String credentialUse = "(L" + SECRET_REF + ";L"
                + WEBSOCKET_STREAMING_CREDENTIAL_OPERATION + ";)L"
                + WEBSOCKET_STREAMING_CONNECTION + ";";
        for (MethodEdge edge : subject.methodEdges) {
            if (edge.owner.equals(STREAMING_WEBSOCKET_CLIENT)
                    && edge.name.equals("open")
                    && edge.descriptor.equals(clientOpen)
                    && !(subject.name.equals(WEBSOCKET_STREAMING_CLIENT_BACKEND)
                            && edge.sourceMethodName.equals("openWithCredential"))) {
                violations.add(violation(
                        variant,
                        subject,
                        "STR002_CLIENT_CALLER",
                        edge.sourceMethodName + edge.sourceMethodDescriptor));
            }
            if (edge.owner.equals(STREAMING_WIRE_STREAM)
                    && edge.name.equals("accept")
                    && !(subject.name.equals(STREAMING_WEBSOCKET_SESSION_IMPL)
                            && edge.sourceMethodName.equals("onMessage")
                            && edge.sourceMethodDescriptor.equals(
                                    "(Lokhttp3/WebSocket;Ljava/lang/String;)V"))) {
                violations.add(violation(
                        variant,
                        subject,
                        "STR002_WIRE_CALLER",
                        edge.sourceMethodName + edge.sourceMethodDescriptor));
            }
            if (edge.owner.equals(WEBSOCKET_STREAMING_CREDENTIAL_ACCESS)
                    && edge.name.equals("use")
                    && edge.descriptor.equals(credentialUse)
                    && !(subject.name.equals(WEBSOCKET_STREAMING_CLIENT_BACKEND)
                            && edge.sourceMethodName.equals("open"))) {
                violations.add(violation(
                        variant,
                        subject,
                        "STR002_CREDENTIAL_CALLER",
                        edge.sourceMethodName + edge.sourceMethodDescriptor));
            }
        }
    }

    private static void inspectStr003Contract(
            String variant, ClassInfo subject, List<Violation> violations) {
        for (TypeEdge edge : subject.typeEdges) {
            if (isStr003ForbiddenType(edge.type)) {
                violations.add(violation(
                        variant,
                        subject,
                        "STR003_ADAPTER_DEPENDENCY",
                        edge.kind.externalName + " references " + edge.type));
            }
        }
        for (MethodEdge edge : subject.methodEdges) {
            if (edge.name.equals("getMessage")
                    && edge.descriptor.equals("()Ljava/lang/String;")) {
                violations.add(violation(
                        variant,
                        subject,
                        "STR003_FAILURE_REDACTION",
                        edge.sourceMethodName + edge.sourceMethodDescriptor
                                + " reads raw exception detail"));
            }
        }

        if (subject.name.equals(QWEN3_ASR_VLLM_CLIENT)) {
            inspectStr003Client(variant, subject, violations);
        } else if (subject.name.equals(QWEN3_ASR_VLLM_CONFIG)) {
            List<String> fields = List.of(
                    "endpoint:L" + PROVIDER_CONFIG_ENDPOINT + ";",
                    "sessionId:L" + SPEECH_SESSION_ID + ";",
                    "model:Ljava/lang/String;");
            if ((subject.access & (Opcodes.ACC_PUBLIC | Opcodes.ACC_FINAL | Opcodes.ACC_RECORD))
                            != (Opcodes.ACC_PUBLIC | Opcodes.ACC_FINAL | Opcodes.ACC_RECORD)
                    || !Objects.equals(subject.nestHost, QWEN3_ASR_VLLM_CLIENT)
                    || !fieldShape(subject.declaredFields, fields)
                    || !hasFixedStringReturn(
                            subject,
                            "toString",
                            "()Ljava/lang/String;",
                            "Qwen3AsrVllmConfig{endpoint=<redacted>, session=<redacted>, model=<redacted>}")) {
                violations.add(violation(
                        variant,
                        subject,
                        "STR003_CLIENT_SHAPE",
                        "Qwen client config must remain an exact immutable redacted endpoint/session/model record"));
            }
        } else if (subject.name.equals(QWEN3_ASR_VLLM_LISTENER)) {
            inspectStr003Interface(
                    variant,
                    subject,
                    QWEN3_ASR_VLLM_CLIENT,
                    Set.of(
                            "onOpen()V",
                            "onEvent(L" + RECOGNITION_EVENT + ";)V",
                            "onFailure(L" + QWEN3_ASR_VLLM_FAILURE + ";)V"),
                    "STR003_CLIENT_SHAPE",
                    violations);
        } else if (subject.name.equals(QWEN3_ASR_VLLM_SESSION)) {
            inspectStr003Interface(
                    variant,
                    subject,
                    QWEN3_ASR_VLLM_CLIENT,
                    Set.of(
                            "sendPcm([BII)Z",
                            "finish()Z",
                            "queuedBytes()J",
                            "cancel()V",
                            "close()V"),
                    "STR003_CLIENT_SHAPE",
                    violations);
        } else if (subject.name.equals(QWEN3_ASR_VLLM_PROBE_RESULT)
                || subject.name.equals(QWEN3_ASR_VLLM_FAILURE)) {
            Set<String> outcomes = subject.name.equals(QWEN3_ASR_VLLM_PROBE_RESULT)
                    ? Set.of(
                            "AVAILABLE",
                            "MODEL_MISSING",
                            "AUTHENTICATION",
                            "RATE_LIMITED",
                            "SERVER_ERROR",
                            "NETWORK_TIMEOUT",
                            "NETWORK_UNAVAILABLE",
                            "PROTOCOL_ERROR",
                            "INTERNAL_ERROR")
                    : Set.of(
                            "MODEL_MISSING",
                            "AUTHENTICATION",
                            "RATE_LIMITED",
                            "SERVER_ERROR",
                            "NETWORK_TIMEOUT",
                            "NETWORK_UNAVAILABLE",
                            "PROTOCOL_ERROR",
                            "INTERNAL_ERROR");
            inspectStr002Enum(
                    variant,
                    subject,
                    subject.name,
                    outcomes,
                    subject.name.equals(QWEN3_ASR_VLLM_PROBE_RESULT)
                            ? "STR003_PROBE_MAPPING"
                            : "STR003_FAILURE_MAPPING",
                    violations);
        } else if (subject.name.equals(QWEN3_ASR_VLLM_SESSION_IMPL)) {
            inspectStr003ClientSession(variant, subject, violations);
        } else if (subject.name.equals(QWEN3_ASR_VLLM_SERVER_EVENT)) {
            if ((subject.access & (Opcodes.ACC_INTERFACE | Opcodes.ACC_ABSTRACT))
                            != (Opcodes.ACC_INTERFACE | Opcodes.ACC_ABSTRACT)
                    || !Objects.equals(subject.nestHost, QWEN3_ASR_VLLM_CLIENT)
                    || !subject.permittedSubclasses.equals(Set.of(
                            QWEN3_ASR_VLLM_SESSION_CREATED,
                            QWEN3_ASR_VLLM_TRANSCRIPTION_DELTA,
                            QWEN3_ASR_VLLM_TRANSCRIPTION_DONE,
                            QWEN3_ASR_VLLM_SERVER_FAILURE))) {
                violations.add(violation(
                        variant,
                        subject,
                        "STR003_PROTOCOL_SHAPE",
                        "server event must remain one private sealed four-event vocabulary"));
            }
        } else if (subject.name.equals(QWEN3_ASR_VLLM_SESSION_CREATED)) {
            inspectStr003ServerRecord(variant, subject, List.of(), violations);
        } else if (subject.name.equals(QWEN3_ASR_VLLM_TRANSCRIPTION_DELTA)
                || subject.name.equals(QWEN3_ASR_VLLM_TRANSCRIPTION_DONE)) {
            inspectStr003ServerRecord(
                    variant, subject, List.of("text:Ljava/lang/String;"), violations);
        } else if (subject.name.equals(QWEN3_ASR_VLLM_SERVER_FAILURE)) {
            inspectStr003ServerRecord(
                    variant,
                    subject,
                    List.of("failure:L" + QWEN3_ASR_VLLM_FAILURE + ";"),
                    violations);
        } else if (subject.name.equals(QWEN3_ASR_VLLM_SERVICE_PATH)) {
            inspectStr002Enum(
                    variant,
                    subject,
                    QWEN3_ASR_VLLM_SERVICE_PATH,
                    Set.of("MODELS", "REALTIME"),
                    "STR003_PROTOCOL_SHAPE",
                    violations);
        } else if (subject.name.equals(QWEN3_ASR_VLLM_PROVIDER)) {
            inspectStr003Provider(variant, subject, violations);
        } else if (subject.name.equals(QWEN3_ASR_VLLM_PROBE_LISTENER)) {
            inspectStr003Interface(
                    variant,
                    subject,
                    QWEN3_ASR_VLLM_PROVIDER,
                    Set.of("onResult(L" + PROVIDER_PROBE_OBSERVATION + ";)V"),
                    "STR003_PROBE_SHAPE",
                    violations);
        } else if (subject.name.equals(QWEN3_ASR_VLLM_PROBE_WORKER)) {
            inspectStr003Interface(
                    variant,
                    subject,
                    QWEN3_ASR_VLLM_PROVIDER,
                    Set.of("execute(Ljava/lang/Runnable;)V", "close()V"),
                    "STR003_PROBE_SHAPE",
                    violations);
        } else if (subject.name.equals(QWEN3_ASR_VLLM_CREDENTIAL_ACCESS)) {
            inspectStr003Interface(
                    variant,
                    subject,
                    QWEN3_ASR_VLLM_PROVIDER,
                    Set.of("use(L" + SECRET_REF + ";L"
                            + QWEN3_ASR_VLLM_CREDENTIAL_OPERATION
                            + ";)Ljava/lang/Object;"),
                    "STR003_CREDENTIAL_BOUNDARY",
                    violations);
        } else if (subject.name.equals(QWEN3_ASR_VLLM_CREDENTIAL_OPERATION)) {
            inspectStr003Interface(
                    variant,
                    subject,
                    QWEN3_ASR_VLLM_PROVIDER,
                    Set.of("apply([C)Ljava/lang/Object;"),
                    "STR003_CREDENTIAL_BOUNDARY",
                    violations);
        } else if (subject.name.equals(QWEN3_ASR_VLLM_PROBE_REQUEST)) {
            if ((subject.access & Opcodes.ACC_FINAL) == 0
                    || !Objects.equals(subject.nestHost, QWEN3_ASR_VLLM_PROVIDER)
                    || !fieldShape(subject.declaredFields, List.of(
                            "generation:J",
                            "sessionId:L" + SPEECH_SESSION_ID + ";",
                            "listener:L" + QWEN3_ASR_VLLM_PROBE_LISTENER + ";"))) {
                violations.add(violation(
                        variant,
                        subject,
                        "STR003_PROBE_SHAPE",
                        "probe request must remain a private generation/session/listener identity"));
            }
        } else if (subject.name.equals(QWEN3_ASR_VLLM_SINGLE_PROBE_WORKER)) {
            inspectStr003ProbeWorker(variant, subject, violations);
        } else if (subject.name.equals(QWEN3_ASR_VLLM_CLIENT_BACKEND)) {
            inspectStr003ClientBackend(variant, subject, violations);
        } else if (subject.name.equals(QWEN3_ASR_VLLM_REJECTED_SESSION)) {
            inspectStr003RejectedSession(variant, subject, violations);
        }
    }

    private static void inspectStr003Client(
            String variant, ClassInfo subject, List<Violation> violations) {
        String probe = "(L" + QWEN3_ASR_VLLM_CONFIG + ";[C)L"
                + QWEN3_ASR_VLLM_PROBE_RESULT + ";";
        String open = "(L" + QWEN3_ASR_VLLM_CONFIG + ";[CL"
                + QWEN3_ASR_VLLM_LISTENER + ";)L" + QWEN3_ASR_VLLM_SESSION + ";";
        boolean shape = (subject.access & (Opcodes.ACC_PUBLIC | Opcodes.ACC_FINAL))
                        == (Opcodes.ACC_PUBLIC | Opcodes.ACC_FINAL)
                && subject.interfaces.equals(Set.of("java/lang/AutoCloseable"))
                && fieldShape(subject.declaredFields, List.of(
                        "MAX_PCM_FRAME_BYTES:I",
                        "MAX_OUTGOING_QUEUE_BYTES:J",
                        "MAX_JSON_UTF16_UNITS:I",
                        "MAX_PROBE_BYTES:I",
                        "MAX_MODELS:I",
                        "MAX_CREDENTIAL_CODE_POINTS:I",
                        "MAX_JSON_DEPTH:I",
                        "SESSION_CREATED_KEYS:Ljava/util/Set;",
                        "DELTA_KEYS:Ljava/util/Set;",
                        "DONE_KEYS:Ljava/util/Set;",
                        "ERROR_KEYS:Ljava/util/Set;",
                        "realtimeClient:Lokhttp3/OkHttpClient;",
                        "probeClient:Lokhttp3/OkHttpClient;"))
                && publicMethodSurface(subject).equals(Set.of(
                        "<init>()V", "probe" + probe, "open" + open, "close()V"))
                && hasExactEdge(
                        subject,
                        "probe",
                        probe,
                        "okhttp3/OkHttpClient",
                        "newCall",
                        "(Lokhttp3/Request;)Lokhttp3/Call;",
                        1)
                && hasExactEdge(
                        subject,
                        "open",
                        open,
                        QWEN3_ASR_VLLM_SESSION_IMPL,
                        "start",
                        "(Lokhttp3/Request;)V",
                        1);
        boolean transport = hasImmediateIntArgumentCount(
                        subject,
                        "<init>",
                        "()V",
                        "okhttp3/OkHttpClient$Builder",
                        "followRedirects",
                        "(Z)Lokhttp3/OkHttpClient$Builder;",
                        Opcodes.ICONST_0,
                        2)
                && hasImmediateIntArgumentCount(
                        subject,
                        "<init>",
                        "()V",
                        "okhttp3/OkHttpClient$Builder",
                        "followSslRedirects",
                        "(Z)Lokhttp3/OkHttpClient$Builder;",
                        Opcodes.ICONST_0,
                        2)
                && hasImmediateIntArgumentCount(
                        subject,
                        "<init>",
                        "()V",
                        "okhttp3/OkHttpClient$Builder",
                        "retryOnConnectionFailure",
                        "(Z)Lokhttp3/OkHttpClient$Builder;",
                        Opcodes.ICONST_0,
                        2)
                && hasExactEdge(
                        subject,
                        "boundedBody",
                        "(Lokhttp3/ResponseBody;)Ljava/lang/String;",
                        "okio/BufferedSource",
                        "request",
                        "(J)Z",
                        1)
                && hasExactEdge(
                        subject,
                        "decodeServerEvent",
                        "(Ljava/lang/String;)L" + QWEN3_ASR_VLLM_SERVER_EVENT + ";",
                        QWEN3_ASR_VLLM_CLIENT,
                        "requireJsonDepth",
                        "(Ljava/lang/String;)V",
                        1);
        if (!shape) {
            violations.add(violation(
                    variant,
                    subject,
                    "STR003_CLIENT_SHAPE",
                    "Qwen client must remain the exact public Config/credential probe/realtime bridge"));
        }
        if (!transport) {
            violations.add(violation(
                    variant,
                    subject,
                    "STR003_TRANSPORT_BOUND",
                    "Qwen client must retain no redirects/retry and bounded probe/JSON processing"));
        }
    }

    private static void inspectStr003ClientSession(
            String variant, ClassInfo subject, List<Violation> violations) {
        String textMessage = "(Lokhttp3/WebSocket;Ljava/lang/String;)V";
        boolean shape = (subject.access & Opcodes.ACC_FINAL) != 0
                && (subject.access & (Opcodes.ACC_PUBLIC | Opcodes.ACC_PROTECTED)) == 0
                && Objects.equals(subject.nestHost, QWEN3_ASR_VLLM_CLIENT)
                && subject.superName.equals("okhttp3/WebSocketListener")
                && subject.interfaces.equals(Set.of(QWEN3_ASR_VLLM_SESSION))
                && fieldShape(subject.declaredFields, List.of(
                        "config:L" + QWEN3_ASR_VLLM_CONFIG + ";",
                        "listener:L" + QWEN3_ASR_VLLM_LISTENER + ";",
                        "webSocket:Lokhttp3/WebSocket;",
                        "transcript:Ljava/lang/StringBuilder;",
                        "sequence:J",
                        "opened:Z",
                        "ready:Z",
                        "finishing:Z",
                        "cancelled:Z",
                        "terminal:Z",
                        "this$0:L" + QWEN3_ASR_VLLM_CLIENT + ";"))
                && hasExactEdge(
                        subject,
                        "start",
                        "(Lokhttp3/Request;)V",
                        "okhttp3/OkHttpClient",
                        "newWebSocket",
                        "(Lokhttp3/Request;Lokhttp3/WebSocketListener;)Lokhttp3/WebSocket;",
                        1)
                && hasExactEdge(
                        subject,
                        "onMessage",
                        textMessage,
                        QWEN3_ASR_VLLM_CLIENT,
                        "decodeServerEvent",
                        "(Ljava/lang/String;)L" + QWEN3_ASR_VLLM_SERVER_EVENT + ";",
                        1)
                && hasExactEdge(
                        subject,
                        "sendPcm",
                        "([BII)Z",
                        QWEN3_ASR_VLLM_CLIENT,
                        "audioAppend",
                        "([BII)Ljava/lang/String;",
                        1)
                && hasExactEdge(
                        subject,
                        "finish",
                        "()Z",
                        QWEN3_ASR_VLLM_CLIENT,
                        "audioCommit",
                        "()Ljava/lang/String;",
                        1)
                && hasExactPrivateMethod(subject, "releaseContentLocked", "()V", false);
        MethodNode toString = findMethod(subject, "toString", "()Ljava/lang/String;");
        boolean redacted = toString != null
                && stringConstants(subject, "toString", "()Ljava/lang/String;")
                        .contains(", content=<redacted>}")
                && !readsField(
                        toString,
                        Opcodes.GETFIELD,
                        QWEN3_ASR_VLLM_SESSION_IMPL,
                        "transcript",
                        "Ljava/lang/StringBuilder;")
                && !readsField(
                        toString,
                        Opcodes.GETFIELD,
                        QWEN3_ASR_VLLM_SESSION_IMPL,
                        "listener",
                        "L" + QWEN3_ASR_VLLM_LISTENER + ";");
        if (!shape) {
            violations.add(violation(
                    variant,
                    subject,
                    "STR003_PROTOCOL_CONTRACT",
                    "one private session must own exact WebSocket, protocol decode, bounded send and cleanup edges"));
        }
        if (!redacted) {
            violations.add(violation(
                    variant,
                    subject,
                    "STR003_FAILURE_REDACTION",
                    "Qwen session diagnostics must redact transcript, session and callback state"));
        }
    }

