    private static void inspectStr006Contract(
            String variant, ClassInfo subject, List<Violation> violations) {
        boolean family = subject.name.equals(TWO_STAGE_STREAMING_PROVIDER)
                || Objects.equals(subject.nestHost, TWO_STAGE_STREAMING_PROVIDER);
        if (family) {
            for (TypeEdge edge : subject.typeEdges) {
                if (isStr006ForbiddenType(edge.type)) {
                    violations.add(violation(
                            variant,
                            subject,
                            "STR006_ADAPTER_DEPENDENCY",
                            edge.kind.externalName + " references " + edge.type));
                }
                if (edge.type.startsWith(LOCAL_STREAMING_PROVIDER + "$")
                        && !Set.of(
                                        LOCAL_STREAMING_START_REQUEST,
                                        LOCAL_STREAMING_SESSION)
                                .contains(edge.type)) {
                    violations.add(violation(
                            variant,
                            subject,
                            "STR006_CHILD_SCOPE",
                            edge.kind.externalName + " references " + edge.type));
                }
                if (edge.type.startsWith(SENSEVOICE_FINAL_PROVIDER + "$" )
                        && !edge.type.equals(SENSEVOICE_START_REQUEST)) {
                    violations.add(violation(
                            variant,
                            subject,
                            "STR006_CHILD_SCOPE",
                            edge.kind.externalName + " references " + edge.type));
                }
            }
            for (MethodEdge edge : subject.methodEdges) {
                if (edge.name.equals("getMessage")
                        && edge.descriptor.equals("()Ljava/lang/String;")) {
                    violations.add(violation(
                            variant,
                            subject,
                            "STR006_FAILURE_REDACTION",
                            edge.sourceMethodName + edge.sourceMethodDescriptor
                                    + " reads raw throwable detail"));
                }
            }
        }

        if (subject.name.equals(TWO_STAGE_STREAMING_PROVIDER)) {
            inspectStr006Provider(variant, subject, violations);
        } else if (subject.name.equals(TWO_STAGE_START_REQUEST)) {
            inspectStr006StartRequest(variant, subject, violations);
        } else if (subject.name.equals(TWO_STAGE_REQUEST_CLAIM)) {
            inspectStr006RequestClaim(variant, subject, violations);
        } else if (subject.name.equals(TWO_STAGE_SESSION_STATE)) {
            inspectStr006SessionState(variant, subject, violations);
        } else if (subject.name.equals(TWO_STAGE_STREAMING_SESSION)) {
            inspectStr006Interface(
                    variant,
                    subject,
                    Set.of("acceptPcm([BI)Z", "acceptedPcmBytes()I"),
                    Set.of(RECOGNITION_PROVIDER_SESSION),
                    violations);
        } else if (subject.name.equals(TWO_STAGE_WORKER)) {
            inspectStr006Interface(
                    variant,
                    subject,
                    Set.of("execute(Ljava/lang/Runnable;)V", "close()V"),
                    Set.of(),
                    violations);
        } else if (subject.name.equals(TWO_STAGE_PCM_BUFFER)) {
            inspectStr006PcmBuffer(variant, subject, violations);
        } else if (subject.name.equals(TWO_STAGE_AUDIO_CLAIM)) {
            inspectStr006AudioClaim(variant, subject, violations);
        } else if (subject.name.equals(TWO_STAGE_SINGLE_WORKER)) {
            inspectStr006SingleWorker(variant, subject, violations);
        }
    }

