    private static boolean hasImmediateIntArgument(
            ClassInfo subject,
            String sourceName,
            String sourceDescriptor,
            String owner,
            String name,
            String descriptor,
            int expectedOpcode) {
        MethodNode method = findMethod(subject, sourceName, sourceDescriptor);
        if (method == null) return false;
        AbstractInsnNode[] instructions = method.instructions.toArray();
        int matches = 0;
        for (int index = 0; index < instructions.length; index++) {
            if (!(instructions[index] instanceof MethodInsnNode call)
                    || !call.owner.equals(owner)
                    || !call.name.equals(name)
                    || !call.desc.equals(descriptor)) {
                continue;
            }
            matches++;
            int argument = previousRealInstruction(instructions, index - 1);
            if (argument < 0 || instructions[argument].getOpcode() != expectedOpcode) return false;
        }
        return matches == 1;
    }

    private static boolean hasImmediateIntArgumentCount(
            ClassInfo subject,
            String sourceName,
            String sourceDescriptor,
            String owner,
            String name,
            String descriptor,
            int expectedOpcode,
            int expectedCount) {
        MethodNode method = findMethod(subject, sourceName, sourceDescriptor);
        if (method == null) return false;
        AbstractInsnNode[] instructions = method.instructions.toArray();
        int matches = 0;
        for (int index = 0; index < instructions.length; index++) {
            if (!(instructions[index] instanceof MethodInsnNode call)
                    || !call.owner.equals(owner)
                    || !call.name.equals(name)
                    || !call.desc.equals(descriptor)) {
                continue;
            }
            matches++;
            int argument = previousRealInstruction(instructions, index - 1);
            if (argument < 0 || instructions[argument].getOpcode() != expectedOpcode) return false;
        }
        return matches == expectedCount;
    }

    private static void inspectRec005Authority(
            String variant, ClassInfo subject, List<Violation> violations) {
        boolean uploadFamily = subject.name.equals(OPENAI_UPLOAD_PROVIDER)
                || Objects.equals(subject.nestHost, OPENAI_UPLOAD_PROVIDER);
        Set<String> uploadInternal = Set.of(
                OPENAI_UPLOAD_START_REQUEST,
                OPENAI_UPLOAD_BACKEND,
                OPENAI_UPLOAD_WORKER,
                OPENAI_UPLOAD_CREDENTIAL_ACCESS,
                OPENAI_UPLOAD_CREDENTIAL_OPERATION,
                OPENAI_UPLOAD_CREDENTIAL_UNAVAILABLE,
                OPENAI_UPLOAD_CLIENT_BACKEND,
                OPENAI_UPLOAD_SINGLE_WORKER,
                OPENAI_UPLOAD_AUDIO_CLAIM,
                OPENAI_UPLOAD_SESSION);
        if (!uploadFamily) {
            for (TypeEdge edge : subject.typeEdges) {
                boolean exactMapperCredentialClassification =
                        subject.name.equals(RECOGNITION_FAILURE_MAPPER)
                                && edge.type.equals(OPENAI_UPLOAD_CREDENTIAL_UNAVAILABLE);
                if (uploadInternal.contains(edge.type) && !exactMapperCredentialClassification) {
                    violations.add(
                            violation(
                                    variant,
                                    subject,
                                    "REC005_ADAPTER_SCOPE",
                                    edge.kind.externalName + " references " + edge.type));
                }
            }
        }

        String upload = "([BLjava/lang/String;[CLjava/lang/String;Ljava/lang/String;"
                + "Ljava/lang/String;Ljava/util/function/BooleanSupplier;)Ljava/lang/String;";
        String backendTranscribe = "(L" + PROVIDER_CONFIG_ASR
                + ";[BLjava/lang/String;Ljava/lang/String;J"
                + "Ljava/util/function/BooleanSupplier;)Ljava/lang/String;";
        String credentialUse = "(L" + SECRET_REF + ";L"
                + OPENAI_UPLOAD_CREDENTIAL_OPERATION + ";)Ljava/lang/String;";
        for (MethodEdge edge : subject.methodEdges) {
            if (edge.owner.equals(OPENAI_COMPATIBLE_CLIENT)
                    && edge.name.equals("transcribe")
                    && edge.descriptor.equals(upload)) {
                boolean exactCaller = subject.name.equals(OPENAI_UPLOAD_CLIENT_BACKEND)
                        && edge.sourceMethodName.equals("transcribeWithCredential")
                        && edge.sourceMethodDescriptor.equals(upload);
                boolean legacyDelegate = subject.name.equals(OPENAI_COMPATIBLE_CLIENT)
                        && edge.sourceMethodName.equals("transcribe")
                        && edge.sourceMethodDescriptor.equals(
                                "([BL" + APP_SETTINGS
                                        + ";Ljava/lang/String;Ljava/util/function/BooleanSupplier;)"
                                        + "Ljava/lang/String;");
                if (!exactCaller && !legacyDelegate) {
                    violations.add(
                            violation(
                                    variant,
                                    subject,
                                    "REC005_CLIENT_CALLER",
                                    edge.sourceMethodName + edge.sourceMethodDescriptor));
                }
            }
            if (edge.owner.equals(OPENAI_UPLOAD_CREDENTIAL_ACCESS)
                    && edge.name.equals("use")
                    && edge.descriptor.equals(credentialUse)) {
                boolean exactCaller = subject.name.equals(OPENAI_UPLOAD_CLIENT_BACKEND)
                        && edge.sourceMethodName.equals("transcribe")
                        && edge.sourceMethodDescriptor.equals(backendTranscribe);
                if (!exactCaller) {
                    violations.add(
                            violation(
                                    variant,
                                    subject,
                                    "REC005_CREDENTIAL_CALLER",
                                    edge.sourceMethodName + edge.sourceMethodDescriptor));
                }
            }
            if ((edge.owner.equals(OPENAI_UPLOAD_BACKEND)
                            || edge.owner.equals(OPENAI_UPLOAD_WORKER)
                            || edge.owner.equals(OPENAI_UPLOAD_CREDENTIAL_OPERATION))
                    && !subject.name.equals(OPENAI_UPLOAD_PROVIDER)
                    && !subject.name.equals(OPENAI_UPLOAD_CLIENT_BACKEND)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "REC005_ADAPTER_CALLER",
                                edge.sourceMethodName + edge.sourceMethodDescriptor
                                        + " invokes " + edge.owner + "#" + edge.name));
            }
        }
    }

    private static void inspectRec006Contract(
            String variant, ClassInfo subject, List<Violation> violations) {
        if (subject.name.equals(SENSEVOICE_FINAL_PROVIDER)) {
            inspectRec006Adapter(variant, subject, violations);
        } else if (subject.name.equals(SENSEVOICE_START_REQUEST)) {
            inspectRec006StartRequest(variant, subject, violations);
        } else if (subject.name.equals(SENSEVOICE_AVAILABILITY)) {
            inspectRec006Enum(
                    variant,
                    subject,
                    SENSEVOICE_AVAILABILITY,
                    Set.of(
                            "READY",
                            "MODEL_MISSING",
                            "MODEL_CORRUPT",
                            "LOW_MEMORY",
                            "UNSUPPORTED_ABI",
                            "SYSTEM_UNAVAILABLE"),
                    "REC006_AVAILABILITY_MAPPING",
                    violations);
        } else if (subject.name.equals(SENSEVOICE_BACKEND)) {
            inspectRec006Interface(
                    variant,
                    subject,
                    Set.of(
                            "availability()L" + SENSEVOICE_AVAILABILITY + ";",
                            "transcribe([BLjava/lang/String;ZLjava/util/function/BooleanSupplier;)"
                                    + "Ljava/lang/String;",
                            "cancel()V",
                            "close()V"),
                    "REC006_BACKEND_SHAPE",
                    violations);
        } else if (subject.name.equals(SENSEVOICE_WORKER)) {
            inspectRec006Interface(
                    variant,
                    subject,
                    Set.of("execute(Ljava/lang/Runnable;)V", "close()V"),
                    "REC006_WORKER_BOUND",
                    violations);
        } else if (subject.name.equals(SENSEVOICE_CLIENT_BACKEND)) {
            inspectRec006ClientBackend(variant, subject, violations);
        } else if (subject.name.equals(SENSEVOICE_SINGLE_WORKER)) {
            inspectRec006SingleWorker(variant, subject, violations);
        } else if (subject.name.equals(SENSEVOICE_AUDIO_CLAIM)) {
            inspectRec006AudioClaim(variant, subject, violations);
        } else if (subject.name.equals(SENSEVOICE_SESSION)) {
            inspectRec006Session(variant, subject, violations);
        } else if (subject.name.equals(SENSEVOICE_SWITCH)) {
            inspectRec006CompilerSwitch(variant, subject, violations);
        } else if (subject.name.equals(LOCAL_OFFLINE_DEVICE_SUPPORT)) {
            inspectRec006Enum(
                    variant,
                    subject,
                    LOCAL_OFFLINE_DEVICE_SUPPORT,
                    Set.of("SUPPORTED", "LOW_MEMORY", "UNSUPPORTED_ABI", "SYSTEM_UNAVAILABLE"),
                    "REC006_DEVICE_SUPPORT",
                    violations);
        } else if (subject.name.equals(LOCAL_OFFLINE_RECOGNIZER)) {
            inspectRec006DeviceProbe(variant, subject, violations);
        } else if (subject.name.equals(LOCAL_OFFLINE_CLIENT_RESULT)) {
            inspectRec006ClientResult(variant, subject, violations);
        }

        boolean providerFamily = subject.name.equals(SENSEVOICE_FINAL_PROVIDER)
                || Objects.equals(subject.nestHost, SENSEVOICE_FINAL_PROVIDER);
        if (providerFamily) {
            for (FieldDeclaration field : subject.declaredFields) {
                String descriptor = field.descriptor;
                if (descriptor.contains("InputConnection")
                        || descriptor.contains("EditorOperation")
                        || descriptor.contains("Throwable")
                        || descriptor.contains("SecretRef")
                        || descriptor.contains("ProviderConfig")
                        || descriptor.startsWith("Ljava/io/File")
                        || descriptor.startsWith("Ljava/nio/file/")) {
                    violations.add(
                            violation(
                                    variant,
                                    subject,
                                    "REC006_CAPABILITY_STORAGE",
                                    field.name + field.descriptor));
                }
            }
            for (TypeEdge edge : subject.typeEdges) {
                String type = edge.type;
                if (type.contains("InputConnection")
                        || type.contains("EditorOperation")
                        || type.endsWith("SecretRef")
                        || type.endsWith("ProviderConfig")
                        || type.equals(APP_SETTINGS)
                        || type.startsWith("java/net/")
                        || type.startsWith("java/nio/file/")
                        || type.startsWith("okhttp3/")
                        || type.startsWith("retrofit2/")
                        || type.startsWith("kotlinx/serialization/")
                        || isSerializationType(type)
                        || type.startsWith("java/lang/reflect/")
                        || type.startsWith("dalvik/system/")) {
                    violations.add(
                            violation(
                                    variant,
                                    subject,
                                    "REC006_ADAPTER_DEPENDENCY",
                                    edge.kind.externalName + " references " + type));
                }
            }
        }
    }

    private static void inspectRec006Interface(
            String variant,
            ClassInfo subject,
            Set<String> methods,
            String rule,
            List<Violation> violations) {
        int required = Opcodes.ACC_INTERFACE | Opcodes.ACC_ABSTRACT;
        int forbidden = Opcodes.ACC_PUBLIC | Opcodes.ACC_PROTECTED;
        if ((subject.access & required) != required
                || (subject.access & forbidden) != 0
                || !"java/lang/Object".equals(subject.superName)
                || !subject.interfaces.isEmpty()
                || !Objects.equals(subject.nestHost, SENSEVOICE_FINAL_PROVIDER)
                || !subject.declaredFields.isEmpty()
                || !subject.nestMembers.isEmpty()
                || !subject.permittedSubclasses.isEmpty()
                || !publicMethodSurface(subject).equals(methods)) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            rule,
                            "SenseVoice seam must remain a fieldless package-confined exact interface"));
        }
    }

    private static void inspectRec006Enum(
            String variant,
            ClassInfo subject,
            String owner,
            Set<String> expected,
            String rule,
            List<Violation> violations) {
        if ((subject.access & (Opcodes.ACC_FINAL | Opcodes.ACC_ENUM))
                        != (Opcodes.ACC_FINAL | Opcodes.ACC_ENUM)
                || !"java/lang/Enum".equals(subject.superName)
                || !enumConstants(subject, owner).equals(expected)) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            rule,
                            "local availability/support must remain the exact closed enum"));
        }
    }

    private static void inspectRec006Adapter(
            String variant, ClassInfo subject, List<Violation> violations) {
        List<String> fields = List.of(
                "lifecycleLock:Ljava/lang/Object;",
                "descriptor:L" + PROVIDER_DESCRIPTOR + ";",
                "backend:L" + SENSEVOICE_BACKEND + ";",
                "worker:L" + SENSEVOICE_WORKER + ";",
                "active:L" + SENSEVOICE_SESSION + ";",
                "closed:Z");
        Set<String> nests = Set.of(
                SENSEVOICE_SWITCH,
                SENSEVOICE_AUDIO_CLAIM,
                SENSEVOICE_BACKEND,
                SENSEVOICE_CLIENT_BACKEND,
                SENSEVOICE_SESSION,
                SENSEVOICE_SINGLE_WORKER,
                SENSEVOICE_START_REQUEST,
                SENSEVOICE_WORKER);
        Set<String> publicMethods = Set.of(
                "descriptor()L" + PROVIDER_DESCRIPTOR + ";",
                "probe()L" + PROVIDER_PROBE_OBSERVATION + ";",
                "prepare(L" + SENSEVOICE_START_REQUEST + ";)L"
                        + RECOGNITION_PROVIDER_PREPARATION + ";",
                "start(L" + SENSEVOICE_START_REQUEST + ";L"
                        + RECOGNITION_PROVIDER_EVENT_SINK + ";)L"
                        + RECOGNITION_PROVIDER_SESSION + ";",
                "close()V",
                "toString()Ljava/lang/String;",
                "prepare(Ljava/lang/Object;)L" + RECOGNITION_PROVIDER_PREPARATION + ";",
                "start(Ljava/lang/Object;L" + RECOGNITION_PROVIDER_EVENT_SINK + ";)L"
                        + RECOGNITION_PROVIDER_SESSION + ";");
        boolean fieldAccess = subject.declaredFields.size() == fields.size();
        for (int index = 0; fieldAccess && index < subject.declaredFields.size(); index++) {
            FieldDeclaration field = subject.declaredFields.get(index);
            int required = Opcodes.ACC_PRIVATE;
            if (index <= 3) required |= Opcodes.ACC_FINAL;
            int forbidden = index >= 4 ? Opcodes.ACC_FINAL : 0;
            fieldAccess = (field.access & required) == required
                    && (field.access & forbidden) == 0;
        }
        int forbiddenVisibility =
                Opcodes.ACC_PUBLIC | Opcodes.ACC_PROTECTED | Opcodes.ACC_PRIVATE;
        String constructor = "(L" + SENSEVOICE_BACKEND + ";L" + SENSEVOICE_WORKER + ";)V";
        String factory = "(Landroid/content/Context;)L" + SENSEVOICE_FINAL_PROVIDER + ";";
        boolean exactShape = (subject.access & Opcodes.ACC_FINAL) != 0
                && (subject.access & forbiddenVisibility) == 0
                && "java/lang/Object".equals(subject.superName)
                && subject.interfaces.equals(Set.of(RECOGNITION_PROVIDER))
                && subject.nestHost == null
                && subject.nestMembers.equals(nests)
                && fieldShape(subject.declaredFields, fields)
                && fieldAccess
                && publicMethodSurface(subject).equals(publicMethods)
                && hasPackageStaticMethod(subject, "create", factory)
                && hasDeclaredMethod(
                        subject,
                        "<init>",
                        constructor,
                        0,
                        forbiddenVisibility | Opcodes.ACC_STATIC)
                && hasExactEdge(
                        subject,
                        "create",
                        factory.substring(0, factory.indexOf(')') + 1)
                                + "L" + SENSEVOICE_FINAL_PROVIDER + ";",
                        LOCAL_OFFLINE_CLIENT,
                        "<init>",
                        "(Landroid/content/Context;)V",
                        1);
        if (!exactShape) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "REC006_ADAPTER_SHAPE",
                            "SenseVoice adapter must remain one package-confined final bounded owner"));
        }

        String start = "(L" + SENSEVOICE_START_REQUEST + ";L"
                + RECOGNITION_PROVIDER_EVENT_SINK + ";)L"
                + RECOGNITION_PROVIDER_SESSION + ";";
        String state = "(L" + SENSEVOICE_SESSION + ";)V";
        String transcribe = "([BLjava/lang/String;ZLjava/util/function/BooleanSupplier;)"
                + "Ljava/lang/String;";
        boolean lifecycle = hasExactEdge(
                        subject,
                        "start",
                        start,
                        SENSEVOICE_WORKER,
                        "execute",
                        "(Ljava/lang/Runnable;)V",
                        1)
                && hasExactEdge(
                        subject,
                        "runRecognition",
                        state,
                        SENSEVOICE_BACKEND,
                        "transcribe",
                        transcribe,
                        1)
                && hasExactEdge(
                        subject,
                        "close",
                        "()V",
                        SENSEVOICE_BACKEND,
                        "close",
                        "()V",
                        1)
                && hasExactEdge(
                        subject,
                        "close",
                        "()V",
                        SENSEVOICE_WORKER,
                        "close",
                        "()V",
                        3)
                && hasExactEdge(
                        subject,
                        "cancelLocked",
                        state,
                        SENSEVOICE_BACKEND,
                        "cancel",
                        "()V",
                        1);
        if (!lifecycle) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "REC006_LIFECYCLE",
                            "SenseVoice start/cancel/close must keep exact worker and backend edges"));
        }

        String emit = "(L" + SENSEVOICE_SESSION + ";L" + RECOGNITION_EVENT + ";)";
        boolean eventGate = hasExactEdge(
                        subject,
                        "emitNonTerminalLocked",
                        emit + "Z",
                        RECOGNITION_PROVIDER_EVENT_SINK,
                        "onEvent",
                        "(L" + RECOGNITION_EVENT + ";)V",
                        1)
                && hasExactEdge(
                        subject,
                        "emitTerminalLocked",
                        emit + "V",
                        RECOGNITION_PROVIDER_EVENT_SINK,
                        "onEvent",
                        "(L" + RECOGNITION_EVENT + ";)V",
                        1)
                && hasExactEdge(
                        subject,
                        "emitNonTerminalLocked",
                        emit + "Z",
                        SENSEVOICE_SESSION,
                        "releaseReferences",
                        "()V",
                        1)
                && hasExactEdge(
                        subject,
                        "emitTerminalLocked",
                        emit + "V",
                        SENSEVOICE_SESSION,
                        "releaseReferences",
                        "()V",
                        3)
                && subject.methodEdges.stream()
                        .filter(edge -> edge.owner.equals(RECOGNITION_PROVIDER_EVENT_SINK)
                                && edge.name.equals("onEvent"))
                        .count()
                        == 2L;
        if (!eventGate) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "REC006_EVENT_TERMINAL",
                            "events must cross one nonterminal and one terminal gate with cleanup"));
        }

        boolean finalOnly = subject.methodEdges.stream().filter(edge ->
                        edge.name.equals("<init>")
                                && edge.owner.startsWith(RECOGNITION_EVENT + "$"))
                .map(edge -> edge.owner)
                .collect(java.util.stream.Collectors.toSet())
                .equals(Set.of(
                        RECOGNITION_EVENT + "$Preparing",
                        RECOGNITION_EVENT + "$Ready",
                        RECOGNITION_EVENT + "$Final",
                        RECOGNITION_EVENT + "$Failure",
                        RECOGNITION_EVENT + "$Cancelled"));
        if (!finalOnly) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "REC006_EVENT_TERMINAL",
                            "local quality provider must not emit partial/speech/endpoint events"));
        }

        if (!hasExactPrivateMethod(
                        subject,
                        "failureClass",
                        "(Ljava/lang/Exception;)L" + RECOGNITION_FAILURE_CLASS + ";",
                        false)
                || !hasExactEdge(
                        subject,
                        "failureClass",
                        "(Ljava/lang/Exception;)L" + RECOGNITION_FAILURE_CLASS + ";",
                        RECOGNITION_FAILURE_MAPPER,
                        "fromLocalRuntime",
                        "(L" + RECOGNITION_LOCAL_AVAILABILITY
                                + ";Ljava/lang/Throwable;)L" + RECOGNITION_FAILURE_CLASS + ";",
                        1)
                || !hasExactEdge(
                        subject,
                        "availabilityFailureLocked",
                        "()L" + RECOGNITION_FAILURE_CLASS + ";",
                        RECOGNITION_FAILURE_MAPPER,
                        "fromLocalAvailability",
                        "(L" + RECOGNITION_LOCAL_AVAILABILITY + ";)L"
                                + RECOGNITION_FAILURE_CLASS + ";",
                        1)) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "REC006_AVAILABILITY_MAPPING",
                            "runtime failures must re-probe the exact closed availability map"));
        }
    }

    private static void inspectRec006StartRequest(
            String variant, ClassInfo subject, List<Violation> violations) {
        List<String> fields = List.of(
                "sessionId:L" + SPEECH_SESSION_ID + ";",
                "wav:[B",
                "language:Ljava/lang/String;",
                "useInverseTextNormalization:Z",
                "durationMs:J",
                "claimed:Z");
        String constructor = "(L" + SPEECH_SESSION_ID + ";[BLjava/lang/String;ZJ)V";
        boolean fieldAccess = subject.declaredFields.size() == fields.size()
                && subject.declaredFields.stream().allMatch(field ->
                        (field.access & Opcodes.ACC_PRIVATE) != 0)
                && subject.declaredFields.stream()
                        .filter(field -> Set.of(
                                        "sessionId",
                                        "language",
                                        "useInverseTextNormalization",
                                        "durationMs")
                                .contains(field.name))
                        .allMatch(field -> (field.access & Opcodes.ACC_FINAL) != 0)
                && subject.declaredFields.stream()
                        .filter(field -> Set.of("wav", "claimed").contains(field.name))
                        .noneMatch(field -> (field.access & Opcodes.ACC_FINAL) != 0);
        boolean shape = (subject.access & Opcodes.ACC_FINAL) != 0
                && (subject.access & (Opcodes.ACC_PUBLIC | Opcodes.ACC_PROTECTED)) == 0
                && Objects.equals(subject.nestHost, SENSEVOICE_FINAL_PROVIDER)
                && subject.interfaces.equals(Set.of("java/lang/AutoCloseable"))
                && fieldShape(subject.declaredFields, fields)
                && fieldAccess
                && publicMethodSurface(subject).equals(
                        Set.of("close()V", "toString()Ljava/lang/String;"))
                && hasDeclaredMethod(
                        subject,
                        "<init>",
                        constructor,
                        0,
                        Opcodes.ACC_PUBLIC | Opcodes.ACC_PRIVATE | Opcodes.ACC_PROTECTED
                                | Opcodes.ACC_STATIC)
                && hasExactPrivateMethod(
                        subject, "claim", "()L" + SENSEVOICE_AUDIO_CLAIM + ";", false)
                && hasExactEdge(
                        subject,
                        "<init>",
                        constructor,
                        "java/util/Arrays",
                        "copyOf",
                        "([BI)[B",
                        1)
                && hasExactEdge(
                        subject,
                        "close",
                        "()V",
                        "java/util/Arrays",
                        "fill",
                        "([BB)V",
                        1);
        if (!shape) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "REC006_REQUEST_BOUND",
                            "local request must copy, bound, single-claim, zero and redact audio"));
        }
    }

