    private static void inspectRec010PrivacyAuthorization(
            String variant, ClassInfo subject, List<Violation> violations) {
        String profile = "L" + EFFECTIVE_PROFILE + ";";
        String privacy = "L" + RECOGNITION_PRIVACY_CLASS + ";";
        String mode = "L" + RECOGNITION_ROUTER_AUTHORIZATION_MODE + ";";
        String authorization = "L" + RECOGNITION_ROUTER_PRIVACY_AUTHORIZATION + ";";
        String constructor = "(" + profile + mode + privacy + ")V";
        String requireConfirmation = "(" + profile + ")" + authorization;
        String preauthorized = "(" + profile + privacy + ")" + authorization;
        String allows = "(" + privacy + ")Z";
        Set<String> expectedMethods = Set.of(
                "<init>" + constructor,
                "requireConfirmation" + requireConfirmation,
                "preauthorized" + preauthorized,
                "allows" + allows,
                "toString()Ljava/lang/String;");
        boolean exactShape = (subject.access & Opcodes.ACC_FINAL) != 0
                && (subject.access & (Opcodes.ACC_PUBLIC | Opcodes.ACC_PRIVATE
                                | Opcodes.ACC_PROTECTED | Opcodes.ACC_INTERFACE
                                | Opcodes.ACC_ANNOTATION | Opcodes.ACC_ENUM | Opcodes.ACC_RECORD))
                        == 0
                && "java/lang/Object".equals(subject.superName)
                && subject.interfaces.isEmpty()
                && RECOGNITION_ROUTER.equals(subject.nestHost)
                && fieldShape(
                        subject.declaredFields,
                        List.of(
                                "ownerProfile:" + profile,
                                "mode:" + mode,
                                "maximumPrivacy:" + privacy))
                && subject.declaredFields.stream().allMatch(field ->
                        (field.access & (Opcodes.ACC_PRIVATE | Opcodes.ACC_FINAL))
                                == (Opcodes.ACC_PRIVATE | Opcodes.ACC_FINAL)
                                && (field.access & Opcodes.ACC_STATIC) == 0)
                && subject.declaredMethods.stream()
                        .map(method -> method.name + method.descriptor)
                        .collect(java.util.stream.Collectors.toSet())
                        .equals(expectedMethods)
                && hasExactPrivateMethod(subject, "<init>", constructor, false)
                && hasDeclaredMethod(
                        subject,
                        "requireConfirmation",
                        requireConfirmation,
                        Opcodes.ACC_STATIC,
                        Opcodes.ACC_PUBLIC | Opcodes.ACC_PRIVATE | Opcodes.ACC_PROTECTED)
                && hasDeclaredMethod(
                        subject,
                        "preauthorized",
                        preauthorized,
                        Opcodes.ACC_STATIC,
                        Opcodes.ACC_PUBLIC | Opcodes.ACC_PRIVATE | Opcodes.ACC_PROTECTED)
                && hasExactPrivateMethod(subject, "allows", allows, false);
        if (!exactShape) {
            violations.add(violation(
                    variant,
                    subject,
                    "REC010_CONFIRMATION_SHAPE",
                    "privacy authorization must remain a profile-bound package-confined closed proof"));
        }

        MethodNode authorizationConstructor = findMethod(subject, "<init>", constructor);
        MethodNode authorizationCheck = findMethod(subject, "allows", allows);
        boolean exactPolicy = authorizationConstructor != null
                && readsField(
                        authorizationConstructor,
                        Opcodes.GETSTATIC,
                        RECOGNITION_ROUTER_AUTHORIZATION_MODE,
                        "REQUIRE_CONFIRMATION",
                        mode)
                && readsField(
                        authorizationConstructor,
                        Opcodes.GETSTATIC,
                        RECOGNITION_PRIVACY_CLASS,
                        "ON_DEVICE",
                        privacy)
                && authorizationCheck != null
                && readsField(
                        authorizationCheck,
                        Opcodes.GETSTATIC,
                        RECOGNITION_ROUTER_AUTHORIZATION_MODE,
                        "PREAUTHORIZED",
                        mode)
                && hasExactEdge(
                        subject,
                        "requireConfirmation",
                        requireConfirmation,
                        RECOGNITION_ROUTER_PRIVACY_AUTHORIZATION,
                        "<init>",
                        constructor,
                        1)
                && hasExactEdge(
                        subject,
                        "preauthorized",
                        preauthorized,
                        RECOGNITION_ROUTER_PRIVACY_AUTHORIZATION,
                        "<init>",
                        constructor,
                        1)
                && hasExactEdge(
                        subject,
                        "allows",
                        allows,
                        RECOGNITION_ROUTER,
                        "exposure",
                        "(" + privacy + ")I",
                        2);
        if (!exactPolicy) {
            violations.add(violation(
                    variant,
                    subject,
                    "REC010_CONFIRMATION_POLICY",
                    "preauthorization must be explicitly bounded and default to confirmation"));
        }

        MethodNode diagnostic = findMethod(subject, "toString", "()Ljava/lang/String;");
        if (diagnostic == null
                || fieldAccessCount(
                                diagnostic,
                                Opcodes.GETFIELD,
                                RECOGNITION_ROUTER_PRIVACY_AUTHORIZATION,
                                "ownerProfile",
                                profile)
                        != 0) {
            violations.add(violation(
                    variant,
                    subject,
                    "REC010_CONFIRMATION_REDACTION",
                    "privacy authorization diagnostics must not read the owning profile"));
        }
    }

    private static void inspectRec009Enum(
            String variant,
            ClassInfo subject,
            Set<String> expected,
            List<Violation> violations) {
        if ((subject.access & (Opcodes.ACC_FINAL | Opcodes.ACC_ENUM))
                        != (Opcodes.ACC_FINAL | Opcodes.ACC_ENUM)
                || (subject.access & (Opcodes.ACC_PUBLIC | Opcodes.ACC_PROTECTED)) != 0
                || !"java/lang/Enum".equals(subject.superName)
                || !subject.interfaces.isEmpty()
                || !RECOGNITION_ROUTER.equals(subject.nestHost)
                || !enumConstants(subject, subject.name).equals(expected)
                || !publicMethodSurface(subject).equals(Set.of(
                        "values()[L" + subject.name + ";",
                        "valueOf(Ljava/lang/String;)L" + subject.name + ";"))) {
            violations.add(violation(
                    variant,
                    subject,
                    "REC009_ROUTER_SHAPE",
                    "router classification enum drifted from its exact closed vocabulary"));
        }
    }

    private static void inspectRec009Authority(
            String variant, ClassInfo subject, List<Violation> violations) {
        boolean routerFamily = subject.name.equals(RECOGNITION_ROUTER)
                || RECOGNITION_ROUTER.equals(subject.nestHost);
        boolean registryFamily = subject.name.equals(PROVIDER_REGISTRY)
                || PROVIDER_REGISTRY.equals(subject.nestHost);
        boolean routerVoiceFamily = subject.name.equals(RECOGNITION_ROUTER_VOICE_CONTROLLER)
                || RECOGNITION_ROUTER_VOICE_CONTROLLER.equals(subject.nestHost);
        Set<String> routeLeaseTypes = Set.of(
                PROVIDER_ROUTE_LOOKUP_RESULT,
                PROVIDER_ROUTE_LEASE_FOUND,
                PROVIDER_ROUTE_LEASE_REJECTED,
                PROVIDER_ROUTE_LEASE);
        Set<String> allowedRouterDependencies = new TreeSet<>(REC009_REQUIRED_TYPES);
        allowedRouterDependencies.addAll(REC011_REQUIRED_TYPES);
        allowedRouterDependencies.addAll(REC003_REQUIRED_TYPES);
        allowedRouterDependencies.addAll(Set.of(
                RECOGNITION_ROUTE,
                RECOGNITION_ROUTE_STEP,
                RECOGNITION_RETRY_POLICY,
                RECOGNITION_PRIVACY_CLASS,
                RECOGNITION_PROVIDER_CAPABILITY,
                RECOGNITION_FAILURE_CLASS,
                RECOGNITION_CONFIRMATION_POLICY,
                EFFECTIVE_PROFILE,
                EFFECTIVE_RESOLVED_VALUE,
                OVERRIDE_VALUE,
                OVERRIDE_VALUE_DISABLED,
                OVERRIDE_VALUE_EXPLICIT,
                PROVIDER_CAPABILITIES,
                PROVIDER_DESCRIPTOR));
        if (routerFamily) {
            for (TypeEdge edge : subject.typeEdges) {
                String type = edge.type;
                boolean forbidden = isAndroidPlatformType(type)
                        || isSerializationType(type)
                        || type != null && (type.startsWith("java/io/")
                                || type.startsWith("java/net/")
                                || type.startsWith("java/nio/file/")
                                || type.startsWith("java/util/concurrent/"))
                        || type != null
                                && type.startsWith("com/opentypeless/android/")
                                && !allowedRouterDependencies.contains(type);
                if (forbidden) {
                    violations.add(violation(
                            variant,
                            subject,
                            "REC009_ROUTER_DEPENDENCY",
                            edge.kind.externalName + " references " + type));
                }
            }
        } else if (!registryFamily && !routerVoiceFamily) {
            for (TypeEdge edge : subject.typeEdges) {
                if (REC009_REQUIRED_TYPES.contains(edge.type)
                        || routeLeaseTypes.contains(edge.type)) {
                    violations.add(violation(
                            variant,
                            subject,
                            routeLeaseTypes.contains(edge.type)
                                    ? "REC009_LEASE_SCOPE"
                                    : "REC009_ROUTER_SCOPE",
                            edge.kind.externalName + " references " + edge.type));
                }
                if (Set.of(
                                RECOGNITION_ROUTER_PRIVACY_AUTHORIZATION,
                                RECOGNITION_ROUTER_CONFIRMATION_DECISION)
                        .contains(edge.type)) {
                    violations.add(violation(
                            variant,
                            subject,
                            "REC010_CONFIRMATION_SCOPE",
                            edge.kind.externalName + " references " + edge.type));
                }
            }
        }

        for (MethodEdge edge : subject.methodEdges) {
            if (edge.owner.equals(PROVIDER_REGISTRY)
                    && (edge.name.equals("routeLease") || edge.name.equals("isCurrent"))
                    && !subject.name.equals(RECOGNITION_ROUTER)) {
                violations.add(violation(
                        variant,
                        subject,
                        "REC009_LEASE_CALLER",
                        edge.sourceMethodName + edge.sourceMethodDescriptor
                                + " invokes " + edge.name + edge.descriptor));
            }
            if (edge.owner.equals(PROVIDER_ROUTE_LEASE)
                    && edge.name.equals("descriptor")
                    && !Set.of(RECOGNITION_ROUTER, RECOGNITION_ROUTER_ATTEMPT)
                            .contains(subject.name)) {
                violations.add(violation(
                        variant,
                        subject,
                        "REC009_LEASE_CALLER",
                        edge.sourceMethodName + edge.sourceMethodDescriptor
                                + " resolves a route lease descriptor"));
            }
            if (edge.owner.equals(RECOGNITION_ROUTER)
                    && edge.name.equals("onConfirmation")
                    && !subject.name.equals(RECOGNITION_ROUTER)) {
                violations.add(violation(
                        variant,
                        subject,
                        "REC010_CONFIRMATION_CALLER",
                        edge.sourceMethodName + edge.sourceMethodDescriptor
                                + " resumes a pending route"));
            }
        }
    }

    private static void inspectRec011Contract(
            String variant, ClassInfo subject, List<Violation> violations) {
        if (subject.name.equals(PROVIDER_CIRCUIT_BREAKER)) {
            inspectRec011Breaker(variant, subject, violations);
        } else if (subject.name.equals(PROVIDER_CIRCUIT_PERMIT)) {
            inspectRec011Permit(variant, subject, violations);
        } else if (subject.name.equals(PROVIDER_CIRCUIT_ENTRY)) {
            inspectRec011Entry(variant, subject, violations);
        } else if (subject.name.equals(PROVIDER_CIRCUIT_ACQUIRE_RESULT)) {
            inspectRec011AcquireResult(variant, subject, violations);
        } else if (Set.of(PROVIDER_CIRCUIT_PERMIT_GRANTED, PROVIDER_CIRCUIT_PERMIT_REJECTED)
                .contains(subject.name)) {
            inspectRec011AcquireRecord(variant, subject, violations);
        } else if (subject.name.equals(PROVIDER_CIRCUIT_CLOCK)) {
            inspectRec011Clock(variant, subject, violations);
        } else if (subject.name.equals(PROVIDER_CIRCUIT_STATE)) {
            inspectRec011Enum(
                    variant, subject, Set.of("CLOSED", "OPEN", "HALF_OPEN"), violations);
        } else if (subject.name.equals(PROVIDER_CIRCUIT_REJECTION_REASON)) {
            inspectRec011Enum(
                    variant,
                    subject,
                    Set.of(
                            "OPEN",
                            "HALF_OPEN_BUSY",
                            "CAPACITY_EXCEEDED",
                            "CLOCK_INVALID",
                            "GENERATION_EXHAUSTED"),
                    violations);
        } else if (subject.name.equals(PROVIDER_CIRCUIT_DISPOSITION)) {
            inspectRec011Enum(
                    variant,
                    subject,
                    Set.of(
                            "RECORDED",
                            "OPENED",
                            "RECOVERED",
                            "REOPENED",
                            "IGNORED_NON_HEALTH",
                            "IGNORED_STALE",
                            "CLOCK_INVALID",
                            "GENERATION_EXHAUSTED"),
                    violations);
        } else if (subject.name.equals(PROVIDER_CIRCUIT_SWITCH)) {
            Set<String> fields = subject.declaredFields.stream()
                    .map(field -> field.name + ":" + field.descriptor)
                    .collect(java.util.stream.Collectors.toSet());
            if (!PROVIDER_CIRCUIT_BREAKER.equals(subject.nestHost)
                    || !fields.equals(Set.of(
                            "$SwitchMap$com$opentypeless$android$config$RecognitionRoute$FailureClass:[I"))
                    || !publicMethodSurface(subject).isEmpty()) {
                violations.add(violation(
                        variant,
                        subject,
                        "REC011_BREAKER_POLICY",
                        "breaker switch helper may encode only the closed failure vocabulary"));
            }
        }
    }

    private static void inspectRec011Breaker(
            String variant, ClassInfo subject, List<Violation> violations) {
        String clock = "L" + PROVIDER_CIRCUIT_CLOCK + ";";
        String acquireResult = "L" + PROVIDER_CIRCUIT_ACQUIRE_RESULT + ";";
        String permit = "L" + PROVIDER_CIRCUIT_PERMIT + ";";
        String disposition = "L" + PROVIDER_CIRCUIT_DISPOSITION + ";";
        String entry = "L" + PROVIDER_CIRCUIT_ENTRY + ";";
        String rejection = "L" + PROVIDER_CIRCUIT_REJECTION_REASON + ";";
        String failure = "L" + RECOGNITION_FAILURE_CLASS + ";";
        String constructor = "(" + clock + ")V";
        String acquire = "(L" + PROVIDER_DESCRIPTOR + ";)" + acquireResult;
        String resolve = "(" + permit + ")" + disposition;
        String fail = "(" + permit + failure + ")" + disposition;
        Set<String> methods = Set.of(
                "<init>" + constructor,
                "acquire" + acquire,
                "onSuccess" + resolve,
                "onFailure" + fail,
                "abandon" + resolve,
                "size()I",
                "toString()Ljava/lang/String;",
                "reopen(" + entry + "Z)" + disposition,
                "currentPermit(" + permit + ")" + permit,
                "advanceEpoch(" + entry + ")Z",
                "closeHealthy(" + entry + ")V",
                "failClosed(" + entry + rejection + ")V",
                "readNow()J",
                "isHealthFailure(" + failure + ")Z",
                "isRecoveryEvidence(" + failure + ")Z");
        Set<String> expectedNestMembers = new TreeSet<>(REC011_REQUIRED_TYPES);
        expectedNestMembers.remove(PROVIDER_CIRCUIT_BREAKER);
        boolean exactShape = (subject.access & Opcodes.ACC_FINAL) != 0
                && (subject.access & (Opcodes.ACC_PUBLIC | Opcodes.ACC_PRIVATE
                                | Opcodes.ACC_PROTECTED | Opcodes.ACC_INTERFACE
                                | Opcodes.ACC_ANNOTATION | Opcodes.ACC_ENUM | Opcodes.ACC_RECORD))
                        == 0
                && "java/lang/Object".equals(subject.superName)
                && subject.interfaces.isEmpty()
                && subject.nestHost == null
                && subject.nestMembers.equals(expectedNestMembers)
                && fieldShape(
                        subject.declaredFields,
                        List.of(
                                "FAILURE_THRESHOLD:I",
                                "OPEN_INTERVAL_MILLIS:J",
                                "MAX_PROVIDERS:I",
                                "clock:" + clock,
                                "entries:Ljava/util/Map;",
                                "lastNowMillis:J"))
                && subject.declaredFields.size() == 6
                && subject.declaredMethods.stream()
                        .map(method -> method.name + method.descriptor)
                        .collect(java.util.stream.Collectors.toSet())
                        .equals(methods)
                && hasDeclaredMethod(
                        subject,
                        "<init>",
                        constructor,
                        0,
                        Opcodes.ACC_PUBLIC | Opcodes.ACC_PRIVATE | Opcodes.ACC_PROTECTED
                                | Opcodes.ACC_STATIC)
                && hasDeclaredMethod(
                        subject,
                        "acquire",
                        acquire,
                        Opcodes.ACC_SYNCHRONIZED,
                        Opcodes.ACC_PUBLIC | Opcodes.ACC_PRIVATE | Opcodes.ACC_PROTECTED
                                | Opcodes.ACC_STATIC)
                && hasDeclaredMethod(
                        subject,
                        "onSuccess",
                        resolve,
                        Opcodes.ACC_SYNCHRONIZED,
                        Opcodes.ACC_PUBLIC | Opcodes.ACC_PRIVATE | Opcodes.ACC_PROTECTED
                                | Opcodes.ACC_STATIC)
                && hasDeclaredMethod(
                        subject,
                        "onFailure",
                        fail,
                        Opcodes.ACC_SYNCHRONIZED,
                        Opcodes.ACC_PUBLIC | Opcodes.ACC_PRIVATE | Opcodes.ACC_PROTECTED
                                | Opcodes.ACC_STATIC)
                && hasDeclaredMethod(
                        subject,
                        "abandon",
                        resolve,
                        Opcodes.ACC_SYNCHRONIZED,
                        Opcodes.ACC_PUBLIC | Opcodes.ACC_PRIVATE | Opcodes.ACC_PROTECTED
                                | Opcodes.ACC_STATIC)
                && hasDeclaredMethod(
                        subject,
                        "size",
                        "()I",
                        Opcodes.ACC_SYNCHRONIZED,
                        Opcodes.ACC_PUBLIC | Opcodes.ACC_PRIVATE | Opcodes.ACC_PROTECTED
                                | Opcodes.ACC_STATIC)
                && hasDeclaredMethod(
                        subject,
                        "toString",
                        "()Ljava/lang/String;",
                        Opcodes.ACC_PUBLIC | Opcodes.ACC_SYNCHRONIZED,
                        Opcodes.ACC_STATIC);
        if (!exactShape) {
            violations.add(violation(
                    variant,
                    subject,
                    "REC011_BREAKER_SHAPE",
                    "breaker must remain the exact bounded process-local synchronized state machine"));
        }

        MethodNode success = findMethod(subject, "onSuccess", resolve);
        MethodNode failureMethod = findMethod(subject, "onFailure", fail);
        MethodNode abandon = findMethod(subject, "abandon", resolve);
        MethodNode current = findMethod(subject, "currentPermit", "(" + permit + ")" + permit);
        boolean policy = hasExactEdge(
                        subject,
                        "<init>",
                        constructor,
                        "java/util/IdentityHashMap",
                        "<init>",
                        "()V",
                        1)
                && hasExactEdge(
                        subject,
                        "readNow",
                        "()J",
                        PROVIDER_CIRCUIT_CLOCK,
                        "nowMillis",
                        "()J",
                        1)
                && success != null
                && fieldAccessCount(success, Opcodes.PUTFIELD,
                        PROVIDER_CIRCUIT_PERMIT, "consumed", "Z") == 1
                && failureMethod != null
                && fieldAccessCount(failureMethod, Opcodes.PUTFIELD,
                        PROVIDER_CIRCUIT_PERMIT, "consumed", "Z") == 1
                && abandon != null
                && fieldAccessCount(abandon, Opcodes.PUTFIELD,
                        PROVIDER_CIRCUIT_PERMIT, "consumed", "Z") == 1
                && current != null
                && fieldAccessCount(current, Opcodes.GETFIELD,
                        PROVIDER_CIRCUIT_PERMIT, "owner", "L" + PROVIDER_CIRCUIT_BREAKER + ";") == 1
                && fieldAccessCount(current, Opcodes.GETFIELD,
                        PROVIDER_CIRCUIT_PERMIT, "consumed", "Z") == 1
                && fieldAccessCount(current, Opcodes.GETFIELD,
                        PROVIDER_CIRCUIT_PERMIT, "epoch", "J") == 1;
        if (!policy) {
            violations.add(violation(
                    variant,
                    subject,
                    "REC011_BREAKER_POLICY",
                    "breaker must use identity keys, monotonic time and single-use owner/epoch permits"));
        }

        MethodNode diagnostic = findMethod(subject, "toString", "()Ljava/lang/String;");
        if (diagnostic == null
                || !stringConstants(subject, "toString", "()Ljava/lang/String;")
                        .containsAll(Set.of(
                                "ProviderCircuitBreaker{providerCount=",
                                ", openCount=",
                                ", halfOpenCount=",
                                ", identities=<redacted>}"))
                || subject.methodEdges.stream()
                        .filter(edge -> edge.sourceMethodName.equals("toString"))
                        .anyMatch(edge -> edge.owner.equals(PROVIDER_DESCRIPTOR))) {
            violations.add(violation(
                    variant,
                    subject,
                    "REC011_BREAKER_REDACTION",
                    "breaker diagnostics must expose only bounded counts and redacted identities"));
        }
    }

    private static void inspectRec011Permit(
            String variant, ClassInfo subject, List<Violation> violations) {
        List<String> fields = List.of(
                "owner:L" + PROVIDER_CIRCUIT_BREAKER + ";",
                "entry:L" + PROVIDER_CIRCUIT_ENTRY + ";",
                "epoch:J",
                "halfOpen:Z",
                "consumed:Z");
        String constructor = "(L" + PROVIDER_CIRCUIT_BREAKER + ";L"
                + PROVIDER_CIRCUIT_ENTRY + ";JZ)V";
        boolean exact = (subject.access & Opcodes.ACC_FINAL) != 0
                && (subject.access & (Opcodes.ACC_PUBLIC | Opcodes.ACC_PROTECTED)) == 0
                && "java/lang/Object".equals(subject.superName)
                && subject.interfaces.isEmpty()
                && PROVIDER_CIRCUIT_BREAKER.equals(subject.nestHost)
                && fieldShape(subject.declaredFields, fields)
                && subject.declaredFields.stream().allMatch(field ->
                        (field.access & Opcodes.ACC_PRIVATE) != 0
                                && (field.name.equals("consumed")
                                        || (field.access & Opcodes.ACC_FINAL) != 0))
                && subject.declaredMethods.stream()
                        .map(method -> method.name + method.descriptor)
                        .collect(java.util.stream.Collectors.toSet())
                        .equals(Set.of("<init>" + constructor, "toString()Ljava/lang/String;"))
                && hasExactPrivateMethod(subject, "<init>", constructor, false)
                && hasFixedStringReturn(
                        subject,
                        "toString",
                        "()Ljava/lang/String;",
                        "Permit{identity=<redacted>}");
        if (!exact) {
            violations.add(violation(
                    variant,
                    subject,
                    "REC011_PERMIT_SHAPE",
                    "permit must remain a privately constructed single-use owner/entry/epoch token"));
        }
    }

