    private static void inspectRec011AcquireRecord(
            String variant, ClassInfo subject, List<Violation> violations) {
        boolean granted = subject.name.equals(PROVIDER_CIRCUIT_PERMIT_GRANTED);
        String component = granted
                ? "L" + PROVIDER_CIRCUIT_PERMIT + ";"
                : "L" + PROVIDER_CIRCUIT_REJECTION_REASON + ";";
        String name = granted ? "permit" : "reason";
        String constructor = "(" + component + ")V";
        Set<String> methods = Set.of(
                name + "()" + component,
                "toString()Ljava/lang/String;",
                "hashCode()I",
                "equals(Ljava/lang/Object;)Z");
        MethodNode diagnostic = findMethod(subject, "toString", "()Ljava/lang/String;");
        boolean exact = (subject.access & (Opcodes.ACC_FINAL | Opcodes.ACC_RECORD))
                        == (Opcodes.ACC_FINAL | Opcodes.ACC_RECORD)
                && (subject.access & (Opcodes.ACC_PUBLIC | Opcodes.ACC_PROTECTED)) == 0
                && "java/lang/Record".equals(subject.superName)
                && subject.interfaces.equals(Set.of(PROVIDER_CIRCUIT_ACQUIRE_RESULT))
                && PROVIDER_CIRCUIT_BREAKER.equals(subject.nestHost)
                && fieldShape(subject.declaredFields, List.of(name + ":" + component))
                && publicMethodSurface(subject).equals(methods)
                && hasDeclaredMethod(
                        subject,
                        "<init>",
                        constructor,
                        0,
                        Opcodes.ACC_PUBLIC | Opcodes.ACC_PRIVATE | Opcodes.ACC_PROTECTED
                                | Opcodes.ACC_STATIC)
                && diagnostic != null
                && (!granted || fieldAccessCount(
                        diagnostic,
                        Opcodes.GETFIELD,
                        PROVIDER_CIRCUIT_PERMIT_GRANTED,
                        "permit",
                        component) == 0);
        if (!exact) {
            violations.add(violation(
                    variant,
                    subject,
                    granted ? "REC011_PERMIT_SHAPE" : "REC011_BREAKER_SHAPE",
                    "acquire result records must remain exact and content-free"));
        }
    }

