    private static void inspectCfg005Resolver(
            String variant, ClassInfo subject, List<Violation> violations) {
        String resolveDescriptor = "(L" + EFFECTIVE_REQUEST + ";)L" + EFFECTIVE_PROFILE + ";";
        Set<String> publicMethods = Set.of("resolve" + resolveDescriptor);
        boolean privateConstructor = subject.declaredMethods.stream().anyMatch(method ->
                method.name.equals("<init>")
                        && method.descriptor.equals("()V")
                        && (method.access & Opcodes.ACC_PRIVATE) != 0);
        boolean constantFields = fieldShape(
                        subject.declaredFields,
                        List.of("MAX_APP_RULES:I", "MAX_FIELD_RULES:I"))
                && subject.declaredFields.stream().allMatch(field ->
                        (field.access & (Opcodes.ACC_PUBLIC | Opcodes.ACC_STATIC | Opcodes.ACC_FINAL))
                                == (Opcodes.ACC_PUBLIC | Opcodes.ACC_STATIC | Opcodes.ACC_FINAL));
        String factoryDescriptor = "(L" + OVERRIDE_VALUE + ";L" + EFFECTIVE_RULE_SOURCE + ";L"
                + EFFECTIVE_EXPLANATION + ";)L" + EFFECTIVE_RESOLVED_VALUE + ";";
        boolean exactFactories = hasExactEdge(
                        subject, "resolve", resolveDescriptor, EFFECTIVE_PROFILE, "resolved",
                        factoryDescriptor, 1)
                && hasExactEdge(subject, "selected",
                        "(L" + OVERRIDE_VALUE + ";L" + EFFECTIVE_RULE_SOURCE + ";)L"
                                + EFFECTIVE_RESOLVED_VALUE + ";",
                        EFFECTIVE_PROFILE, "resolved", factoryDescriptor, 1)
                && hasExactEdge(subject, "hardDisabled", "()L" + EFFECTIVE_RESOLVED_VALUE + ";",
                        EFFECTIVE_PROFILE, "resolved", factoryDescriptor, 1)
                && hasExactEdge(subject, "hardValue",
                        "(Ljava/lang/Object;)L" + EFFECTIVE_RESOLVED_VALUE + ";",
                        EFFECTIVE_PROFILE, "resolved", factoryDescriptor, 1)
                && subject.methodEdges.stream()
                        .filter(edge -> edge.owner.equals(EFFECTIVE_PROFILE)
                                && edge.name.equals("resolved"))
                        .count() == 4L;
        boolean exactResolutionBranches = hasExactEdge(
                        subject, "resolve", resolveDescriptor, EFFECTIVE_PROFILE_RESOLVER,
                        "resolveLeaf",
                        "(L" + OVERRIDE_VALUE + ";L" + OVERRIDE_VALUE + ";L" + OVERRIDE_VALUE
                                + ";L" + OVERRIDE_VALUE + ";L" + OVERRIDE_VALUE + ";)L"
                                + EFFECTIVE_RESOLVED_VALUE + ";",
                        5)
                && hasExactEdge(subject, "resolve", resolveDescriptor, EFFECTIVE_PROFILE_RESOLVER,
                        "hardDisabled", "()L" + EFFECTIVE_RESOLVED_VALUE + ";", 4)
                && hasExactEdge(subject, "resolve", resolveDescriptor, EFFECTIVE_PROFILE_RESOLVER,
                        "hardValue", "(Ljava/lang/Object;)L" + EFFECTIVE_RESOLVED_VALUE + ";", 1);
        if ((subject.access & (Opcodes.ACC_PUBLIC | Opcodes.ACC_FINAL))
                        != (Opcodes.ACC_PUBLIC | Opcodes.ACC_FINAL)
                || !"java/lang/Object".equals(subject.superName)
                || !subject.interfaces.isEmpty()
                || subject.nestHost != null
                || !subject.nestMembers.equals(Set.of(
                        EFFECTIVE_PROVIDER_DEFAULTS,
                        EFFECTIVE_REQUEST,
                        EFFECTIVE_RESOLUTION_FAILURE,
                        EFFECTIVE_RESOLUTION_EXCEPTION))
                || !subject.permittedSubclasses.isEmpty()
                || !constantFields
                || !publicMethodSurface(subject).equals(publicMethods)
                || !privateConstructor
                || !exactFactories
                || !exactResolutionBranches) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "CFG005_RESOLVER_BINARY_SHAPE",
                            "expected one exact resolver with bounded inputs and five terminal leaves"));
        }
    }

