    private static void inspectEditorTransactionAuditHostBinding(
            String variant, ClassInfo subject, List<Violation> violations) {
        List<FieldDeclaration> sinkFields = subject.declaredFields.stream()
                .filter(field -> field.descriptor.equals("L" + AUDIT_SINK + ";"))
                .toList();
        boolean exactSinkField = sinkFields.size() == 1
                && sinkFields.get(0).name.equals("auditSink")
                && (sinkFields.get(0).access & (Opcodes.ACC_PRIVATE | Opcodes.ACC_FINAL))
                        == (Opcodes.ACC_PRIVATE | Opcodes.ACC_FINAL)
                && (sinkFields.get(0).access & Opcodes.ACC_STATIC) == 0;
        boolean storesAudit = subject.declaredFields.stream().anyMatch(field ->
                field.descriptor.equals("L" + EDITOR_TRANSACTION_AUDIT + ";")
                        || field.descriptor.equals("[L" + EDITOR_TRANSACTION_AUDIT + ";"));
        boolean exactHelpers = hasExactPrivateMethod(
                        subject, "auditReceipt", AUDIT_RECEIPT_DESCRIPTOR, false)
                && hasExactPrivateMethod(subject, "auditResult", AUDIT_RESULT_DESCRIPTOR, false)
                && hasExactPrivateMethod(subject, "recordAudit", RECORD_AUDIT_DESCRIPTOR, false)
                && hasExactPrivateMethod(subject, "operationKind", OPERATION_KIND_DESCRIPTOR, true);
        MethodNode recordAudit = subject.methodNodes.stream()
                .filter(method -> method.name.equals("recordAudit")
                        && method.desc.equals(RECORD_AUDIT_DESCRIPTOR))
                .findFirst()
                .orElse(null);
        boolean catchesRuntime = recordAudit != null
                && recordAudit.tryCatchBlocks.size() == 1
                && "java/lang/RuntimeException".equals(recordAudit.tryCatchBlocks.get(0).type);
        MethodNode operationKind = subject.methodNodes.stream()
                .filter(method -> method.name.equals("operationKind")
                        && method.desc.equals(OPERATION_KIND_DESCRIPTOR))
                .findFirst()
                .orElse(null);
        Map<String, String> expectedMappings = Map.ofEntries(
                Map.entry(
                        "com/opentypeless/android/editor/EditorOperation$SetComposition",
                        "SET_COMPOSITION"),
                Map.entry(
                        "com/opentypeless/android/editor/EditorOperation$CommitComposition",
                        "COMMIT_COMPOSITION"),
                Map.entry(
                        "com/opentypeless/android/editor/EditorOperation$InsertText",
                        "INSERT_TEXT"),
                Map.entry(REPLACE_SELECTION, "REPLACE_SELECTION"),
                Map.entry(REPLACE_LAST_COMMIT, "REPLACE_LAST_COMMIT"),
                Map.entry(
                        "com/opentypeless/android/editor/EditorOperation$DeleteBeforeCursor",
                        "DELETE_BEFORE_CURSOR"),
                Map.entry(
                        "com/opentypeless/android/editor/EditorOperation$PerformEditorAction",
                        "PERFORM_EDITOR_ACTION"));
        Map<String, Long> observedOperationTypes = new TreeMap<>();
        Map<String, Long> observedKinds = new TreeMap<>();
        if (operationKind != null) {
            for (AbstractInsnNode instruction : operationKind.instructions.toArray()) {
                if (instruction instanceof TypeInsnNode type
                        && type.getOpcode() == Opcodes.INSTANCEOF) {
                    observedOperationTypes.merge(type.desc, 1L, Long::sum);
                } else if (instruction instanceof FieldInsnNode field
                        && field.getOpcode() == Opcodes.GETSTATIC
                        && field.owner.equals(EDITOR_OPERATION_KIND)) {
                    observedKinds.merge(field.name, 1L, Long::sum);
                }
            }
        }
        Map<String, Long> expectedOperationTypes = new TreeMap<>();
        Map<String, Long> expectedKinds = new TreeMap<>();
        for (Map.Entry<String, String> mapping : expectedMappings.entrySet()) {
            expectedOperationTypes.put(mapping.getKey(), 1L);
            expectedKinds.put(mapping.getValue(), 1L);
        }
        if (!exactSinkField
                || storesAudit
                || !exactHelpers
                || !catchesRuntime
                || !observedOperationTypes.equals(expectedOperationTypes)
                || !observedKinds.equals(expectedKinds)) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "EDITOR_TRANSACTION_AUDIT_HOST_BINDING",
                            "ETM must own one sink, no audit storage and an exact seven-kind map"));
        }
    }

    private static boolean hasExactPrivateMethod(
            ClassInfo subject, String name, String descriptor, boolean requireStatic) {
        List<MethodDeclaration> methods = subject.declaredMethods.stream()
                .filter(method -> method.name.equals(name))
                .toList();
        if (methods.size() != 1 || !methods.get(0).descriptor.equals(descriptor)) return false;
        int access = methods.get(0).access;
        if ((access & Opcodes.ACC_PRIVATE) == 0) return false;
        return ((access & Opcodes.ACC_STATIC) != 0) == requireStatic;
    }

    private static void inspectReplaceSelectionModel(
            String variant, ClassInfo subject, List<Violation> violations) {
        List<String> expectedFields = List.of(
                "expectedSelection:Lcom/opentypeless/android/editor/TextRange;",
                "expectedTextHash:Lcom/opentypeless/android/editor/TextFingerprint;",
                "text:Ljava/lang/String;",
                "source:Lcom/opentypeless/android/editor/OperationSource;");
        List<String> observedFields = subject.declaredFields.stream()
                .filter(field -> (field.access & Opcodes.ACC_STATIC) == 0)
                .map(field -> field.name + ":" + field.descriptor)
                .toList();
        String constructor =
                "(Lcom/opentypeless/android/editor/TextRange;"
                        + "Lcom/opentypeless/android/editor/TextFingerprint;Ljava/lang/String;"
                        + "Lcom/opentypeless/android/editor/OperationSource;)V";
        boolean exactConstructor = subject.declaredMethods.stream()
                .anyMatch(method -> method.name.equals("<init>")
                        && method.descriptor.equals(constructor)
                        && (method.access & Opcodes.ACC_PUBLIC) != 0);
        boolean exactFields = observedFields.equals(expectedFields)
                && subject.declaredFields.stream()
                        .filter(field -> (field.access & Opcodes.ACC_STATIC) == 0)
                        .allMatch(field -> (field.access & (Opcodes.ACC_PRIVATE | Opcodes.ACC_FINAL))
                                == (Opcodes.ACC_PRIVATE | Opcodes.ACC_FINAL));
        if ((subject.access & (Opcodes.ACC_PUBLIC | Opcodes.ACC_FINAL | Opcodes.ACC_RECORD))
                        != (Opcodes.ACC_PUBLIC | Opcodes.ACC_FINAL | Opcodes.ACC_RECORD)
                || !subject.interfaces.equals(
                        Set.of("com/opentypeless/android/editor/EditorOperation"))
                || !exactFields
                || !exactConstructor) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "REPLACE_SELECTION_MODEL_SHAPE",
                            "ReplaceSelection exact range/hash/text/source record drifted"));
        }
    }

    private static void inspectReplaceSelectionPolicy(
            String variant, ClassInfo subject, List<Violation> violations) {
        if (!variant.equals("debug")
                && !variant.equals("release")
                && !referencesType(subject, REPLACE_SELECTION)) {
            return;
        }
        String descriptor =
                "(Lcom/opentypeless/android/editor/EditorSessionSnapshot;"
                        + "Lcom/opentypeless/android/editor/EditorOperation;L"
                        + EDITOR_SESSION_MANAGER + "$Validated;Z)"
                        + "Lcom/opentypeless/android/editor/RejectionReason;";
        MethodNode policy = subject.methodNodes.stream()
                .filter(method -> method.name.equals("policyRejection")
                        && method.desc.equals(descriptor))
                .findFirst()
                .orElse(null);
        boolean replaceBranch = false;
        boolean expectedRange = false;
        boolean expectedHash = false;
        boolean liveRange = false;
        boolean secureHash = false;
        boolean sensitiveDenial = false;
        boolean undoDenial = false;
        boolean rawDenial = false;
        if (policy != null) {
            for (AbstractInsnNode instruction : policy.instructions.toArray()) {
                if (instruction instanceof TypeInsnNode type
                        && type.getOpcode() == Opcodes.INSTANCEOF
                        && type.desc.equals(REPLACE_SELECTION)) {
                    replaceBranch = true;
                } else if (instruction instanceof MethodInsnNode call) {
                    if (call.owner.equals(REPLACE_SELECTION)
                            && call.name.equals("expectedSelection")
                            && call.desc.equals(
                                    "()Lcom/opentypeless/android/editor/TextRange;")) {
                        expectedRange = true;
                    } else if (call.owner.equals(REPLACE_SELECTION)
                            && call.name.equals("expectedTextHash")
                            && call.desc.equals(
                                    "()Lcom/opentypeless/android/editor/TextFingerprint;")) {
                        expectedHash = true;
                    } else if (call.owner.equals(VALIDATED_EVIDENCE)
                            && call.name.equals("selection")
                            && call.desc.equals(
                                    "()Lcom/opentypeless/android/editor/TextRange;")) {
                        liveRange = true;
                    } else if (call.owner.equals(
                                    "com/opentypeless/android/editor/TextFingerprint")
                            && call.name.equals("securelyMatches")) {
                        secureHash = true;
                    }
                } else if (instruction instanceof FieldInsnNode field
                        && field.getOpcode() == Opcodes.GETSTATIC) {
                    if (field.owner.equals(
                                    "com/opentypeless/android/editor/RejectionReason")
                            && field.name.equals("SENSITIVE_FIELD")) {
                        sensitiveDenial = true;
                    } else if (field.owner.equals(
                                    "com/opentypeless/android/editor/OperationSource")
                            && field.name.equals("UNDO")) {
                        undoDenial = true;
                    } else if (field.owner.equals(
                                    "com/opentypeless/android/editor/OperationSource")
                            && field.name.equals("RAW_RESTORE")) {
                        rawDenial = true;
                    }
                }
            }
        }
        if (!(replaceBranch
                && expectedRange
                && expectedHash
                && liveRange
                && secureHash
                && sensitiveDenial
                && undoDenial
                && rawDenial)) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "REPLACE_SELECTION_POLICY",
                            "policy must bind producer range/hash to fresh live selection and deny sensitive/authority labels"));
        }
    }

    private static void inspectReplaceSelectionDispatcher(
            String variant, ClassInfo subject, List<Violation> violations) {
        if (!variant.equals("debug")
                && !variant.equals("release")
                && !referencesType(subject, REPLACE_SELECTION)) {
            return;
        }
        MethodNode dispatcher = subject.methodNodes.stream()
                .filter(method -> method.name.equals("invokeMutator")
                        && method.desc.equals(
                                "(Landroid/view/inputmethod/InputConnection;"
                                        + "Lcom/opentypeless/android/editor/EditorOperation;)Z"))
                .findFirst()
                .orElse(null);
        int commitCalls = 0;
        boolean replaceBranch = false;
        boolean readsReplacement = false;
        boolean setSelection = false;
        if (dispatcher != null) {
            for (AbstractInsnNode instruction : dispatcher.instructions.toArray()) {
                if (instruction instanceof TypeInsnNode type
                        && type.getOpcode() == Opcodes.INSTANCEOF
                        && type.desc.equals(REPLACE_SELECTION)) {
                    replaceBranch = true;
                } else if (instruction instanceof MethodInsnNode call) {
                    if (call.owner.equals(REPLACE_SELECTION)
                            && call.name.equals("text")
                            && call.desc.equals("()Ljava/lang/String;")) {
                        readsReplacement = true;
                    }
                    if (call.owner.equals(INPUT_CONNECTION)
                            && call.name.equals("commitText")
                            && call.desc.equals("(Ljava/lang/CharSequence;I)Z")) {
                        commitCalls++;
                    }
                    if (call.owner.equals(INPUT_CONNECTION)
                            && call.name.equals("setSelection")) {
                        setSelection = true;
                    }
                }
            }
        }
        boolean exactReplaceFlow = dispatcher != null
                && replaceBranchUsesOnlySharedCommit(dispatcher);
        if (!(replaceBranch
                && readsReplacement
                && commitCalls == 1
                && !setSelection
                && exactReplaceFlow)) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "REPLACE_SELECTION_DISPATCHER",
                            "ReplaceSelection must converge on the single existing commitText sink without setSelection"));
        }
    }

    private static boolean replaceBranchUsesOnlySharedCommit(MethodNode dispatcher) {
        AbstractInsnNode[] instructions = dispatcher.instructions.toArray();
        int branch = -1;
        int textRead = -1;
        int commit = -1;
        for (int index = 0; index < instructions.length; index++) {
            AbstractInsnNode instruction = instructions[index];
            if (instruction instanceof TypeInsnNode type
                    && type.getOpcode() == Opcodes.INSTANCEOF
                    && type.desc.equals(REPLACE_SELECTION)) {
                if (branch >= 0) return false;
                branch = index;
            } else if (instruction instanceof MethodInsnNode call
                    && call.owner.equals(REPLACE_SELECTION)
                    && call.name.equals("text")
                    && call.desc.equals("()Ljava/lang/String;")) {
                if (textRead >= 0) return false;
                textRead = index;
            } else if (instruction instanceof MethodInsnNode call
                    && call.owner.equals(INPUT_CONNECTION)
                    && call.name.equals("commitText")
                    && call.desc.equals("(Ljava/lang/CharSequence;I)Z")) {
                if (commit >= 0) return false;
                commit = index;
            }
        }
        if (!(branch >= 0 && branch < textRead && textRead < commit)) return false;
        int conditionalIndex = nextRealInstruction(instructions, branch + 1);
        if (conditionalIndex < 0
                || !(instructions[conditionalIndex] instanceof JumpInsnNode conditional)
                || conditional.getOpcode() != Opcodes.IFEQ) {
            return false;
        }
        for (int index = conditionalIndex + 1; index < textRead; index++) {
            AbstractInsnNode instruction = instructions[index];
            if (instruction.getOpcode() < 0) continue;
            if (instruction instanceof JumpInsnNode) return false;
            if (instruction instanceof MethodInsnNode call
                    && isInputConnectionWriteCall(call)) {
                return false;
            }
        }
        int storeIndex = nextRealInstruction(instructions, textRead + 1);
        if (storeIndex < 0
                || !(instructions[storeIndex] instanceof VarInsnNode store)
                || store.getOpcode() != Opcodes.ASTORE) {
            return false;
        }
        boolean guardedNonNull = false;
        for (int index = storeIndex + 1; index < commit; index++) {
            AbstractInsnNode instruction = instructions[index];
            if (instruction instanceof MethodInsnNode call
                    && isInputConnectionWriteCall(call)) {
                return false;
            }
            if (instruction instanceof JumpInsnNode jump) {
                if (jump.getOpcode() != Opcodes.IFNULL) return false;
                int loadIndex = previousRealInstruction(instructions, index - 1);
                if (loadIndex < 0
                        || !(instructions[loadIndex] instanceof VarInsnNode load)
                        || load.getOpcode() != Opcodes.ALOAD
                        || load.var != store.var
                        || dispatcher.instructions.indexOf(jump.label) <= commit) {
                    return false;
                }
                guardedNonNull = true;
            }
        }
        int afterCommit = nextRealInstruction(instructions, commit + 1);
        return guardedNonNull
                && afterCommit >= 0
                && instructions[afterCommit].getOpcode() == Opcodes.IRETURN;
    }

    private static boolean isInputConnectionWriteCall(MethodInsnNode call) {
        return EDITOR_TRANSACTION_WRITE_SINKS.contains(
                member(call.owner, call.name, call.desc));
    }

    private static int nextRealInstruction(
            AbstractInsnNode[] instructions, int start) {
        for (int index = start; index < instructions.length; index++) {
            if (instructions[index].getOpcode() >= 0) return index;
        }
        return -1;
    }

    private static MethodNode findMethod(
            ClassInfo subject, String name, String descriptor) {
        return subject.methodNodes.stream()
                .filter(method -> method.name.equals(name)
                        && method.desc.equals(descriptor))
                .findFirst()
                .orElse(null);
    }

    private static int previousRealInstruction(
            AbstractInsnNode[] instructions, int start) {
        for (int index = start; index >= 0; index--) {
            if (instructions[index].getOpcode() >= 0) return index;
        }
        return -1;
    }

    private static void inspectUndoFacade(
            String variant, ClassInfo subject, List<Violation> violations) {
        List<MethodDeclaration> undoMethods = subject.declaredMethods.stream()
                .filter(method -> method.name.equals("undoCommit"))
                .toList();
        boolean exact = undoMethods.size() == 1
                && undoMethods.get(0).descriptor.equals(UNDO_FACADE_DESCRIPTOR)
                && (undoMethods.get(0).access
                                & (Opcodes.ACC_PUBLIC
                                        | Opcodes.ACC_PROTECTED
                                        | Opcodes.ACC_PRIVATE
                                        | Opcodes.ACC_STATIC
                                        | Opcodes.ACC_ABSTRACT))
                        == 0;
        if (!exact) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "UNDO_FACADE_SHAPE",
                            "expected one package-confined undoCommit"
                                    + UNDO_FACADE_DESCRIPTOR));
        }
    }

    private static void inspectRawRestoreFacade(
            String variant, ClassInfo subject, List<Violation> violations) {
        List<MethodDeclaration> rawMethods = subject.declaredMethods.stream()
                .filter(method -> method.name.equals("restoreRawCommit"))
                .toList();
        boolean exact = rawMethods.size() == 1
                && rawMethods.get(0).descriptor.equals(RAW_RESTORE_FACADE_DESCRIPTOR)
                && (rawMethods.get(0).access
                                & (Opcodes.ACC_PUBLIC
                                        | Opcodes.ACC_PROTECTED
                                        | Opcodes.ACC_PRIVATE
                                        | Opcodes.ACC_STATIC
                                        | Opcodes.ACC_ABSTRACT))
                        == 0;
        if (!exact) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "RAW_RESTORE_FACADE_SHAPE",
                            "expected one package-confined restoreRawCommit"
                                    + RAW_RESTORE_FACADE_DESCRIPTOR));
        }
    }

    private static void inspectReplaceLastCommitAuthority(
            String variant, ClassInfo subject, List<Violation> violations) {
        for (MethodNode method : subject.methodNodes) {
            boolean authorizesSemanticUndo =
                    method.desc.contains("L" + REPLACE_LAST_COMMIT + ";");
            for (AbstractInsnNode instruction : method.instructions.toArray()) {
                if (instruction instanceof TypeInsnNode type
                        && type.desc.equals(REPLACE_LAST_COMMIT)
                        && (type.getOpcode() == Opcodes.NEW
                                || type.getOpcode() == Opcodes.CHECKCAST
                                || type.getOpcode() == Opcodes.ANEWARRAY)) {
                    authorizesSemanticUndo = true;
                    break;
                }
                if (instruction instanceof MethodInsnNode call
                        && call.owner.equals(REPLACE_LAST_COMMIT)) {
                    authorizesSemanticUndo = true;
                    break;
                }
            }
            // INSTANCEOF is intentionally allowed in ordinary policy code so it can fail closed.
            String methodName = method.name.toLowerCase(Locale.ROOT);
            if (authorizesSemanticUndo
                    && !methodName.contains("undo")
                    && !methodName.contains("raw")) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "UNDO_OPERATION_AUTHORITY",
                                method.name + method.desc
                                        + " references caller-constructible ReplaceLastCommit"));
            }
        }
    }

    private static void inspectRawRestoreApplyAuthority(
            String variant, ClassInfo subject, List<Violation> violations) {
        String policyDescriptor =
                "(Lcom/opentypeless/android/editor/EditorSessionSnapshot;"
                        + "Lcom/opentypeless/android/editor/EditorOperation;L"
                        + EDITOR_SESSION_MANAGER + "$Validated;Z)"
                        + "Lcom/opentypeless/android/editor/RejectionReason;";
        MethodNode policy = subject.methodNodes.stream()
                .filter(method -> method.name.equals("policyRejection")
                        && method.desc.equals(policyDescriptor))
                .findFirst()
                .orElse(null);
        boolean readsRawSource = false;
        boolean invokesSource = false;
        boolean returnsUnsupported = false;
        if (policy != null) {
            for (AbstractInsnNode instruction : policy.instructions.toArray()) {
                if (instruction instanceof FieldInsnNode field
                        && field.getOpcode() == Opcodes.GETSTATIC
                        && field.owner.equals(
                                "com/opentypeless/android/editor/OperationSource")
                        && field.name.equals("RAW_RESTORE")) {
                    readsRawSource = true;
                } else if (instruction instanceof MethodInsnNode call
                        && call.owner.equals("com/opentypeless/android/editor/EditorOperation")
                        && call.name.equals("source")
                        && call.desc.equals(
                                "()Lcom/opentypeless/android/editor/OperationSource;")) {
                    invokesSource = true;
                } else if (instruction instanceof FieldInsnNode field
                        && field.getOpcode() == Opcodes.GETSTATIC
                        && field.owner.equals(
                                "com/opentypeless/android/editor/RejectionReason")
                        && field.name.equals("OPERATION_NOT_SUPPORTED")) {
                    returnsUnsupported = true;
                }
            }
        }
        if (!(readsRawSource && invokesSource && returnsUnsupported)) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "RAW_RESTORE_APPLY_DENIAL",
                            "ordinary policy must read RAW_RESTORE and return "
                                    + "OPERATION_NOT_SUPPORTED"));
        }

        for (MethodNode method : subject.methodNodes) {
            for (AbstractInsnNode instruction : method.instructions.toArray()) {
                if (!(instruction instanceof FieldInsnNode field)
                        || field.getOpcode() != Opcodes.GETSTATIC
                        || !field.owner.equals(
                                "com/opentypeless/android/editor/OperationSource")
                        || !field.name.equals("RAW_RESTORE")) {
                    continue;
                }
                String name = method.name.toLowerCase(Locale.ROOT);
                if (!name.contains("raw") && !method.name.equals("policyRejection")) {
                    violations.add(
                            violation(
                                    variant,
                                    subject,
                                    "RAW_RESTORE_OPERATION_AUTHORITY",
                                    method.name + method.desc
                                            + " obtains RAW_RESTORE outside exact Raw flow"));
                }
            }
        }
    }

    private static void inspectCommitLedger(
            String variant,
            ClassInfo subject,
            Set<String> capabilityTypes,
            List<Violation> violations) {
        int forbiddenKinds =
                Opcodes.ACC_PUBLIC
                        | Opcodes.ACC_PROTECTED
                        | Opcodes.ACC_PRIVATE
                        | Opcodes.ACC_ABSTRACT
                        | Opcodes.ACC_INTERFACE
                        | Opcodes.ACC_ANNOTATION
                        | Opcodes.ACC_ENUM
                        | Opcodes.ACC_RECORD;
        if ((subject.access & Opcodes.ACC_FINAL) == 0
                || (subject.access & forbiddenKinds) != 0
                || subject.nestHost != null
                || !"java/lang/Object".equals(subject.superName)) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "COMMIT_LEDGER_DECLARATION",
                            "must be a package-private final top-level class with Object superclass"));
        }

        List<FieldDeclaration> slots = subject.declaredFields.stream()
                .filter(field -> field.descriptor.equals("L" + COMMIT_RECORD + ";"))
                .toList();
        boolean exactPrivateInstanceSlot = slots.size() == 1
                && (slots.get(0).access & Opcodes.ACC_PRIVATE) != 0
                && (slots.get(0).access & Opcodes.ACC_STATIC) == 0;
        if (!exactPrivateInstanceSlot) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "COMMIT_LEDGER_SINGLE_SLOT",
                            "expected exactly one direct CommitRecord field; observed=" + slots.size()));
        }
        for (FieldDeclaration field : subject.declaredFields) {
            if (field.name.toLowerCase(Locale.ROOT).contains("capacity")
                    || isCollectionBackedField(field)
                    || field.descriptor.equals("[L" + COMMIT_RECORD + ";")) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "COMMIT_LEDGER_SINGLE_SLOT",
                                "forbidden field " + field.name + field.descriptor));
            }
            if (fieldCarriesCapability(field, capabilityTypes)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "COMMIT_LEDGER_CAPABILITY_STORAGE",
                                field.name + field.descriptor));
            }
        }

        List<FieldDeclaration> ownerFields = subject.declaredFields.stream()
                .filter(field -> field.descriptor.equals("Ljava/lang/Thread;"))
                .filter(field -> (field.access & (Opcodes.ACC_PRIVATE | Opcodes.ACC_FINAL))
                        == (Opcodes.ACC_PRIVATE | Opcodes.ACC_FINAL))
                .toList();
        boolean capturesOwner = ownerFields.size() == 1
                && constructorStoresCurrentThread(subject, ownerFields.get(0).name);
        if (ownerFields.size() != 1 || !capturesOwner) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "COMMIT_LEDGER_OWNER_CONFINEMENT",
                            "must capture exactly one private final owner Thread in construction"));
        }
        boolean hasExactOwnerGuard = ownerFields.size() == 1
                && subject.declaredMethods.stream().anyMatch(method ->
                        method.name.equals("requireOwnerThread")
                                && method.descriptor.equals("()V")
                                && (method.access & Opcodes.ACC_PRIVATE) != 0
                                && (method.access & Opcodes.ACC_STATIC) == 0)
                && ownerGuardChecksCurrentThread(subject, ownerFields.get(0).name);
        if (!hasExactOwnerGuard) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "COMMIT_LEDGER_OWNER_CONFINEMENT",
                            "requireOwnerThread must compare Thread.currentThread with the captured owner"));
        }

        for (MethodDeclaration method : subject.declaredMethods) {
            if ((method.access & Opcodes.ACC_STATIC) != 0
                    || method.name.equals("<init>")
                    || method.name.equals("<clinit>")
                    || method.name.equals("toString")
                    || method.name.equals("requireOwnerThread")) {
                continue;
            }
            boolean guarded = subject.methodEdges.stream()
                    .anyMatch(edge -> edge.sourceMethodName.equals(method.name)
                            && edge.sourceMethodDescriptor.equals(method.descriptor)
                            && edge.owner.equals(COMMIT_LEDGER)
                            && edge.name.equals("requireOwnerThread")
                            && edge.descriptor.equals("()V"));
            if (!guarded) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "COMMIT_LEDGER_OWNER_CONFINEMENT",
                                method.name + method.descriptor + " lacks direct owner guard"));
            }
        }

        String exactLookupDescriptor =
                "(Ljava/lang/String;Lcom/opentypeless/android/editor/EditorSessionSnapshot;)"
                        + "Ljava/util/Optional;";
        for (String name : List.of("resolve", "consume")) {
            boolean exact = subject.declaredMethods.stream()
                    .anyMatch(method -> method.name.equals(name)
                            && method.descriptor.equals(exactLookupDescriptor)
                            && method.signature != null
                            && method.signature.contains("L" + COMMIT_RECORD + ";"));
            if (!exact) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "COMMIT_LEDGER_EXACT_ID_API",
                                name + exactLookupDescriptor));
            }
        }
        boolean exactIdComparison = subject.methodEdges.stream()
                .anyMatch(edge -> edge.sourceMethodName.equals("resolve")
                        && edge.sourceMethodDescriptor.equals(exactLookupDescriptor)
                        && edge.owner.equals("java/lang/String")
                        && edge.name.equals("equals")
                        && edge.descriptor.equals("(Ljava/lang/Object;)Z"));
        if (!exactIdComparison) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "COMMIT_LEDGER_EXACT_ID_API",
                            "resolve must compare the supplied exact identifier"));
        }
    }

    private static void inspectCommitEnvelope(
            String variant,
            ClassInfo subject,
            Set<String> capabilityTypes,
            List<Violation> violations) {
        Set<String> shapeTypes = new TreeSet<>();
        if (subject.superName != null) shapeTypes.add(subject.superName);
        shapeTypes.addAll(subject.interfaces);
        for (FieldDeclaration field : subject.declaredFields) {
            addDescriptorTypeNames(field.descriptor, shapeTypes);
            addSignatureTypeNames(field.signature, shapeTypes);
        }
        for (MethodDeclaration method : subject.declaredMethods) {
            addDescriptorTypeNames(method.descriptor, shapeTypes);
            addSignatureTypeNames(method.signature, shapeTypes);
            shapeTypes.addAll(method.exceptions);
        }
        for (TypeEdge edge : subject.typeEdges) {
            if (edge.kind == EdgeKind.ANNOTATION) shapeTypes.add(edge.type);
        }

        for (String type : shapeTypes) {
            if (isAndroidPlatformType(type) || capabilityTypes.contains(type)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "COMMIT_ENVELOPE_ANDROID_CAPABILITY",
                                "declaration references " + type));
            }
            if (isThrowableLike(type)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "COMMIT_ENVELOPE_THROWABLE",
                                "declaration references " + type));
            }
            if (isCommitExecutionType(type)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "COMMIT_ENVELOPE_EXECUTION_CAPABILITY",
                                "declaration references " + type));
            }
            if (isSerializationType(type)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "COMMIT_ENVELOPE_SERIALIZATION",
                                "declaration references " + type));
            }
        }
    }

    private static void inspectCommitRecencyLookup(
            String variant, ClassInfo subject, List<Violation> violations) {
        for (MethodDeclaration method : subject.declaredMethods) {
            Set<String> tokens = identifierTokens(method.name);
            if (java.util.Collections.disjoint(tokens, COMMIT_LOOKUP_RECENCY_TOKENS)) continue;
            // The protected owners have no legitimate recency API. Reject the semantic token
            // itself so resolveLatest()/fetchCurrent() cannot erase its return to Object.
            violations.add(
                    violation(
                            variant,
                            subject,
                            "COMMIT_RECENCY_LOOKUP_API",
                            method.name + method.descriptor));
        }
    }

    private static void inspectReceiptScopeType(
            String variant,
            ClassInfo subject,
            Set<String> capabilityTypes,
            List<Violation> violations) {
        if (subject.name.equals(SCOPED_RECEIPT_CONNECTION_USE)) {
            List<MethodDeclaration> methods = subject.declaredMethods.stream()
                    .filter(method -> !method.name.equals("<clinit>"))
                    .toList();
            String expected = "(L" + INPUT_CONNECTION + ";)L" + TRANSACTION_RECEIPT + ";";
            if (methods.size() != 1
                    || !methods.get(0).name.equals("use")
                    || !methods.get(0).descriptor.equals(expected)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "RECEIPT_SCOPE_METHOD_SURFACE",
                                "expected only use" + expected));
            }
            if (!subject.declaredFields.isEmpty()
                    || !subject.interfaces.isEmpty()
                    || (subject.access & (Opcodes.ACC_INTERFACE | Opcodes.ACC_ABSTRACT))
                            != (Opcodes.ACC_INTERFACE | Opcodes.ACC_ABSTRACT)
                    || (subject.access & (Opcodes.ACC_PUBLIC | Opcodes.ACC_PROTECTED)) != 0) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "RECEIPT_SCOPE_CAPABILITY_STORAGE",
                                "scoped callback must be package-confined with no fields or superinterfaces"));
            }
            return;
        }

        if (subject.name.equals(RECEIPT_CONNECTION_USE_RESULT)) {
            if (!subject.declaredFields.isEmpty()
                    || !subject.declaredMethods.isEmpty()
                    || !subject.interfaces.isEmpty()
                    || (subject.access & (Opcodes.ACC_INTERFACE | Opcodes.ACC_ABSTRACT))
                            != (Opcodes.ACC_INTERFACE | Opcodes.ACC_ABSTRACT)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "RECEIPT_SCOPE_RESULT_SHAPE",
                                "result root must be a fieldless, methodless closed marker"));
            }
        } else if (subject.name.equals(RECEIPT_CONNECTION_USED)) {
            if (subject.declaredFields.size() != 1
                    || !subject.declaredFields.get(0).descriptor.equals(
                            "L" + TRANSACTION_RECEIPT + ";")) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "RECEIPT_SCOPE_RESULT_SHAPE",
                                "used result must contain only the exact TransactionReceipt"));
            }
        } else if (subject.name.equals(RECEIPT_CONNECTION_INVALID)) {
            if (subject.declaredFields.size() != 1
                    || !subject.declaredFields.get(0).descriptor.equals(
                            "Lcom/opentypeless/android/editor/TargetChangeReason;")) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "RECEIPT_SCOPE_RESULT_SHAPE",
                                "invalid result must contain only TargetChangeReason"));
            }
        }

        for (FieldDeclaration field : subject.declaredFields) {
            if (fieldCarriesCapability(field, capabilityTypes)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "RECEIPT_SCOPE_CAPABILITY_STORAGE",
                                field.name + field.descriptor));
            }
        }
        for (MethodDeclaration method : subject.declaredMethods) {
            if (methodDescriptorCarriesCapability(method.descriptor, capabilityTypes)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "RECEIPT_SCOPE_CAPABILITY_RETURN",
                                method.name + method.descriptor));
            }
        }
    }

    private static void inspectReceiptHostLease(
            String variant, ClassInfo subject, List<Violation> violations) {
        String descriptor = "(L" + SCOPED_RECEIPT_CONNECTION_USE + ";)L"
                + RECEIPT_CONNECTION_USE_RESULT + ";";
        List<MethodDeclaration> receiptMethods = subject.declaredMethods.stream()
                .filter(method -> method.name.toLowerCase(Locale.ROOT).contains("receipt"))
                .toList();
        boolean exact = receiptMethods.size() == 1
                && receiptMethods.get(0).name.equals(
                        "consumeWithCurrentConnectionForReceipt")
                && receiptMethods.get(0).descriptor.equals(descriptor)
                && (receiptMethods.get(0).access
                                & (Opcodes.ACC_PUBLIC | Opcodes.ACC_PROTECTED | Opcodes.ACC_STATIC))
                        == 0;
        if (!exact) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "RECEIPT_SCOPE_METHOD_SURFACE",
                            "expected one package-confined consumeWithCurrentConnectionForReceipt"
                                    + descriptor));
        }
    }

    private static void inspectUndoEvidenceScopeType(
            String variant,
            ClassInfo subject,
            Set<String> capabilityTypes,
            List<Violation> violations) {
        int externallyVisible = Opcodes.ACC_PUBLIC | Opcodes.ACC_PROTECTED;
        if ((subject.access & externallyVisible) != 0) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "UNDO_EVIDENCE_SCOPE_SHAPE",
                            "Undo evidence types must remain package-confined"));
        }

        if (subject.name.equals(UNDO_EVIDENCE_READER)) {
            List<MethodDeclaration> methods = subject.declaredMethods.stream()
                    .filter(method -> !method.name.equals("<clinit>"))
                    .toList();
            if (!subject.declaredFields.isEmpty()
                    || !subject.interfaces.isEmpty()
                    || (subject.access & (Opcodes.ACC_INTERFACE | Opcodes.ACC_ABSTRACT))
                            != (Opcodes.ACC_INTERFACE | Opcodes.ACC_ABSTRACT)
                    || methods.size() != 1
                    || !methods.get(0).name.equals("read")
                    || !methods.get(0).descriptor.equals(UNDO_EVIDENCE_READ_DESCRIPTOR)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "UNDO_EVIDENCE_SCOPE_SHAPE",
                                "expected only read" + UNDO_EVIDENCE_READ_DESCRIPTOR));
            }
        } else if (subject.name.equals(UNDO_EVIDENCE_REQUEST)) {
            List<FieldDeclaration> fields = subject.declaredFields.stream()
                    .filter(field -> (field.access & Opcodes.ACC_STATIC) == 0)
                    .toList();
            if (!subject.interfaces.isEmpty()
                    || fields.size() != 2
                    || !fields.get(0).name.equals("beforeUtf16Units")
                    || !fields.get(0).descriptor.equals("I")
                    || !fields.get(1).name.equals("afterUtf16Units")
                    || !fields.get(1).descriptor.equals("I")) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "UNDO_EVIDENCE_SCOPE_SHAPE",
                                "request must contain only exact before/after UTF-16 bounds"));
            }
        } else if (subject.name.equals(UNDO_EVIDENCE_READ_RESULT)) {
            if (!subject.declaredFields.isEmpty()
                    || !subject.declaredMethods.isEmpty()
                    || !subject.interfaces.isEmpty()
                    || (subject.access & (Opcodes.ACC_INTERFACE | Opcodes.ACC_ABSTRACT))
                            != (Opcodes.ACC_INTERFACE | Opcodes.ACC_ABSTRACT)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "UNDO_EVIDENCE_SCOPE_SHAPE",
                                "result root must be a fieldless, methodless closed marker"));
            }
        } else if (subject.name.equals(UNDO_EVIDENCE)) {
            List<FieldDeclaration> fields = subject.declaredFields.stream()
                    .filter(field -> (field.access & Opcodes.ACC_STATIC) == 0)
                    .toList();
            List<String> expected = List.of(
                    "selectionAvailable:Z",
                    "selectionStart:I",
                    "selectionEnd:I",
                    "selectedTextAvailable:Z",
                    "selectedText:Ljava/lang/CharSequence;",
                    "beforeTextAvailable:Z",
                    "beforeText:Ljava/lang/CharSequence;",
                    "afterTextAvailable:Z",
                    "afterText:Ljava/lang/CharSequence;");
            List<String> observed = fields.stream()
                    .map(field -> field.name + ":" + field.descriptor)
                    .toList();
            if (!subject.interfaces.equals(Set.of(UNDO_EVIDENCE_READ_RESULT))
                    || !observed.equals(expected)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "UNDO_EVIDENCE_SCOPE_SHAPE",
                                "available result must contain only selected/before/after evidence"));
            }
            if (!hasFixedStringReturn(subject, "toString", "()Ljava/lang/String;",
                    "UndoEvidence{<redacted>}")) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "UNDO_EVIDENCE_REDACTION",
                                "toString must return only the fixed redacted marker"));
            }
        } else if (subject.name.equals(UNDO_EVIDENCE_UNAVAILABLE)) {
            if (!subject.declaredFields.isEmpty()
                    || !subject.interfaces.equals(Set.of(UNDO_EVIDENCE_READ_RESULT))) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "UNDO_EVIDENCE_SCOPE_SHAPE",
                                "unavailable result must be a fieldless exact result"));
            }
        }

        for (FieldDeclaration field : subject.declaredFields) {
            if (fieldCarriesCapability(field, capabilityTypes)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "UNDO_EVIDENCE_CAPABILITY_STORAGE",
                                field.name + field.descriptor));
            }
        }
        for (MethodDeclaration method : subject.declaredMethods) {
            boolean exactReader = subject.name.equals(UNDO_EVIDENCE_READER)
                    && method.name.equals("read")
                    && method.descriptor.equals(UNDO_EVIDENCE_READ_DESCRIPTOR);
            if (!exactReader
                    && methodDescriptorCarriesCapability(method.descriptor, capabilityTypes)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "UNDO_EVIDENCE_CAPABILITY_TRANSFER",
                                method.name + method.descriptor));
            }
        }
        for (TypeEdge edge : subject.typeEdges) {
            if (edge.type != null
                    && (edge.type.equals(COMMIT_RECORD)
                            || edge.type.equals(TRANSACTION_RECEIPT)
                            || edge.type.equals(REPLACE_LAST_COMMIT)
                            || edge.type.equals(PROJECTION_CONNECTION))) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "UNDO_EVIDENCE_AUTHORITY_PAYLOAD",
                                edge.kind.externalName + " references " + edge.type));
            }
        }
    }

    private static void inspectCurrentEvidenceScopeType(
            String variant,
            ClassInfo subject,
            Set<String> capabilityTypes,
            List<Violation> violations) {
        if ((subject.access & (Opcodes.ACC_PUBLIC | Opcodes.ACC_PROTECTED)) != 0
                || !EDITOR_SESSION_MANAGER.equals(subject.nestHost)) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "CURRENT_EVIDENCE_SCOPE_SHAPE",
                            "current evidence types must remain package-confined ESM nestmates"));
        }

        List<FieldDeclaration> fields = subject.declaredFields.stream()
                .filter(field -> (field.access & Opcodes.ACC_STATIC) == 0)
                .toList();
        if (subject.name.equals(CURRENT_EVIDENCE_READER)) {
            List<MethodDeclaration> methods = subject.declaredMethods.stream()
                    .filter(method -> !method.name.equals("<clinit>"))
                    .toList();
            if (!fields.isEmpty()
                    || !subject.interfaces.isEmpty()
                    || (subject.access & (Opcodes.ACC_INTERFACE | Opcodes.ACC_ABSTRACT))
                            != (Opcodes.ACC_INTERFACE | Opcodes.ACC_ABSTRACT)
                    || methods.size() != 1
                    || !methods.get(0).name.equals("read")
                    || !methods.get(0).descriptor.equals(CURRENT_EVIDENCE_READ_DESCRIPTOR)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "CURRENT_EVIDENCE_SCOPE_SHAPE",
                                "expected only read" + CURRENT_EVIDENCE_READ_DESCRIPTOR));
            }
        } else if (subject.name.equals(CURRENT_EVIDENCE_REQUEST)) {
            if (!fieldShape(fields, List.of("beforeUtf16Units:I", "afterUtf16Units:I"))) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "CURRENT_EVIDENCE_SCOPE_SHAPE",
                                "request must contain only exact before/after UTF-16 bounds"));
            }
        } else if (subject.name.equals(EVIDENCE_READ_RESULT)) {
            if (!fields.isEmpty()
                    || !subject.declaredMethods.isEmpty()
                    || !subject.interfaces.isEmpty()
                    || (subject.access & (Opcodes.ACC_INTERFACE | Opcodes.ACC_ABSTRACT))
                            != (Opcodes.ACC_INTERFACE | Opcodes.ACC_ABSTRACT)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "CURRENT_EVIDENCE_SCOPE_SHAPE",
                                "result root must be a fieldless, methodless marker"));
            }
        } else if (subject.name.equals(CURRENT_EVIDENCE)) {
            List<String> expected = List.of(
                    "selectionAvailable:Z",
                    "selectionStart:I",
                    "selectionEnd:I",
                    "selectedTextAvailable:Z",
                    "selectedText:Ljava/lang/CharSequence;",
                    "beforeTextAvailable:Z",
                    "beforeText:Ljava/lang/CharSequence;",
                    "afterTextAvailable:Z",
                    "afterText:Ljava/lang/CharSequence;");
            if (!subject.interfaces.equals(Set.of(EVIDENCE_READ_RESULT))
                    || !fieldShape(fields, expected)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "CURRENT_EVIDENCE_SCOPE_SHAPE",
                                "available evidence must contain exact absolute selection and bounded text"));
            }
            requireFixedRedaction(
                    variant,
                    subject,
                    "CurrentEvidence{<redacted>}",
                    "CURRENT_EVIDENCE_REDACTION",
                    violations);
        } else if (subject.name.equals(EVIDENCE_UNAVAILABLE)) {
            if (!fields.isEmpty() || !subject.interfaces.equals(Set.of(EVIDENCE_READ_RESULT))) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "CURRENT_EVIDENCE_SCOPE_SHAPE",
                                "unavailable evidence must be a fieldless exact result"));
            }
        } else if (subject.name.equals(VALIDATED_EVIDENCE)
                || subject.name.equals(MATERIALIZED_EVIDENCE)) {
            List<String> expected = List.of(
                    "selection:Lcom/opentypeless/android/editor/TextRange;",
                    "selected:Ljava/lang/String;",
                    "before:Ljava/lang/String;",
                    "after:Ljava/lang/String;");
            if (!fieldShape(fields, expected)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "CURRENT_EVIDENCE_SCOPE_SHAPE",
                                "materialized evidence must retain exact live selection plus bounded text"));
            }
            requireFixedRedaction(
                    variant,
                    subject,
                    subject.name.equals(VALIDATED_EVIDENCE)
                            ? "ValidatedEvidence{<redacted>}"
                            : "MaterializedEvidence{<redacted>}",
                    "CURRENT_EVIDENCE_REDACTION",
                    violations);
        } else if (subject.name.equals(EVIDENCE_ATTEMPT)) {
            if (!fieldShape(
                    fields,
                    List.of(
                            "evidence:L" + MATERIALIZED_EVIDENCE + ";",
                            "failureReason:Lcom/opentypeless/android/editor/TargetChangeReason;",
                            "observedSelection:Lcom/opentypeless/android/editor/TextRange;"))) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "CURRENT_EVIDENCE_SCOPE_SHAPE",
                                "evidence attempt must contain only materialized result/reason/selection"));
            }
            requireFixedRedaction(
                    variant,
                    subject,
                    "EvidenceAttempt{<redacted>}",
                    "CURRENT_EVIDENCE_REDACTION",
                    violations);
        }

        for (FieldDeclaration field : subject.declaredFields) {
            if (fieldCarriesCapability(field, capabilityTypes)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "CURRENT_EVIDENCE_CAPABILITY_STORAGE",
                                field.name + field.descriptor));
            }
        }
        for (MethodDeclaration method : subject.declaredMethods) {
            boolean exactReader = subject.name.equals(CURRENT_EVIDENCE_READER)
                    && method.name.equals("read")
                    && method.descriptor.equals(CURRENT_EVIDENCE_READ_DESCRIPTOR);
            if (!exactReader
                    && methodDescriptorCarriesCapability(method.descriptor, capabilityTypes)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "CURRENT_EVIDENCE_CAPABILITY_TRANSFER",
                                method.name + method.descriptor));
            }
        }
    }

    private static void inspectReplaceTransitionScopeType(
            String variant,
            ClassInfo subject,
            Set<String> capabilityTypes,
            List<Violation> violations) {
        if ((subject.access & (Opcodes.ACC_PUBLIC | Opcodes.ACC_PROTECTED)) != 0
                || !EDITOR_SESSION_MANAGER.equals(subject.nestHost)) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "REPLACE_TRANSITION_SCOPE_SHAPE",
                            "Replace proof types must remain package-confined ESM nestmates"));
        }
        List<FieldDeclaration> fields = subject.declaredFields.stream()
                .filter(field -> (field.access & Opcodes.ACC_STATIC) == 0)
                .toList();
        if (subject.name.equals(REPLACE_PROOF_STATE)) {
            List<String> constants = subject.declaredFields.stream()
                    .filter(field -> field.descriptor.equals("L" + REPLACE_PROOF_STATE + ";"))
                    .map(FieldDeclaration::name)
                    .toList();
            if ((subject.access & Opcodes.ACC_ENUM) == 0
                    || !constants.equals(List.of("ORIGINAL", "INTENDED"))) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "REPLACE_TRANSITION_SCOPE_SHAPE",
                                "ReplaceProofState must contain only ORIGINAL and INTENDED"));
            }
            return;
        }
        if (subject.name.equals(REPLACE_VALIDATION_RESULT)) {
            if (!fields.isEmpty()
                    || !subject.declaredMethods.isEmpty()
                    || (subject.access & (Opcodes.ACC_INTERFACE | Opcodes.ACC_ABSTRACT))
                            != (Opcodes.ACC_INTERFACE | Opcodes.ACC_ABSTRACT)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "REPLACE_TRANSITION_SCOPE_SHAPE",
                                "validation result root must be a fieldless marker"));
            }
        } else if (subject.name.equals(REPLACE_VALIDATED)) {
            if (!fields.isEmpty()
                    || !subject.interfaces.equals(Set.of(REPLACE_VALIDATION_RESULT))) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "REPLACE_TRANSITION_SCOPE_SHAPE",
                                "validated outcome must be a fieldless exact result"));
            }
        } else if (subject.name.equals(REPLACE_VALIDATION_INVALID)) {
            if (!fieldShape(
                            fields,
                            List.of(
                                    "reason:Lcom/opentypeless/android/editor/TargetChangeReason;"))
                    || !subject.interfaces.equals(Set.of(REPLACE_VALIDATION_RESULT))) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "REPLACE_TRANSITION_SCOPE_SHAPE",
                                "invalid outcome must contain only TargetChangeReason"));
            }
        } else if (subject.name.equals(REPLACE_TRANSITION)) {
            List<String> expected = List.of(
                    "ownerStamp:Ljava/lang/Object;",
                    "expectedEpoch:J",
                    "expectedToken:J",
                    "expectedAuthorityRevision:J",
                    "expectedEditor:L" + EDITOR_SESSION_MANAGER + "$ActiveEditor;",
                    "managerSelection:Lcom/opentypeless/android/editor/TextRange;",
                    "originalSelection:Lcom/opentypeless/android/editor/TextRange;",
                    "targetSelection:Lcom/opentypeless/android/editor/TextRange;",
                    "targetState:L" + REPLACE_PROOF_STATE + ";",
                    "replacementUtf16Units:I",
                    "expectedSelectedFingerprint:Lcom/opentypeless/android/editor/TextFingerprint;",
                    "expectedBeforeFingerprint:Lcom/opentypeless/android/editor/TextFingerprint;",
                    "expectedAfterFingerprint:Lcom/opentypeless/android/editor/TextFingerprint;",
                    "expectedContextFingerprint:Lcom/opentypeless/android/editor/TextFingerprint;",
                    "expectedReplacementFingerprint:Lcom/opentypeless/android/editor/TextFingerprint;",
                    "claimed:Z");
            boolean exactConstructor = subject.declaredMethods.stream()
                    .anyMatch(method -> method.name.equals("<init>")
                            && method.descriptor.equals(replaceTransitionConstructorDescriptor())
                            && (method.access & Opcodes.ACC_PRIVATE) != 0);
            boolean exactModifiers = fields.size() == expected.size();
            for (FieldDeclaration field : fields) {
                int required = Opcodes.ACC_PRIVATE;
                if (!field.name.equals("claimed")) required |= Opcodes.ACC_FINAL;
                int forbidden = field.name.equals("claimed") ? Opcodes.ACC_FINAL : 0;
                exactModifiers &= (field.access & required) == required
                        && (field.access & forbidden) == 0;
            }
            if ((subject.access & Opcodes.ACC_FINAL) == 0
                    || !fieldShape(fields, expected)
                    || !exactModifiers
                    || !exactConstructor) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "REPLACE_TRANSITION_SCOPE_SHAPE",
                                "ReplaceTransition exact owner/selection/fingerprint surface drifted"));
            }
            requireFixedRedaction(
                    variant,
                    subject,
                    "ReplaceTransition{<redacted>}",
                    "REPLACE_TRANSITION_REDACTION",
                    violations);
        }
        for (FieldDeclaration field : subject.declaredFields) {
            if (fieldCarriesCapability(field, capabilityTypes)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "REPLACE_TRANSITION_CAPABILITY_STORAGE",
                                field.name + field.descriptor));
            }
        }
        for (MethodDeclaration method : subject.declaredMethods) {
            if (methodDescriptorCarriesCapability(method.descriptor, capabilityTypes)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "REPLACE_TRANSITION_CAPABILITY_TRANSFER",
                                method.name + method.descriptor));
            }
        }
    }

    private static boolean fieldShape(
            List<FieldDeclaration> fields, List<String> expected) {
        return fields.stream().map(field -> field.name + ":" + field.descriptor).toList()
                .equals(expected);
    }

    private static void requireFixedRedaction(
            String variant,
            ClassInfo subject,
            String expected,
            String rule,
            List<Violation> violations) {
        if (!hasFixedStringReturn(subject, "toString", "()Ljava/lang/String;", expected)) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            rule,
                            "toString must return only the fixed redacted marker"));
        }
    }

    private static boolean hasFixedStringReturn(
            ClassInfo subject, String name, String descriptor, String expected) {
        for (MethodNode method : subject.methodNodes) {
            if (!method.name.equals(name) || !method.desc.equals(descriptor)) continue;
            List<AbstractInsnNode> real = Arrays.stream(method.instructions.toArray())
                    .filter(instruction -> instruction.getOpcode() >= 0)
                    .toList();
            return real.size() == 2
                    && real.get(0) instanceof LdcInsnNode constant
                    && expected.equals(constant.cst)
                    && real.get(1).getOpcode() == Opcodes.ARETURN;
        }
        return false;
    }

    private static void inspectRawRestoreScopeType(
            String variant,
            ClassInfo subject,
            Set<String> capabilityTypes,
            List<Violation> violations) {
        if ((subject.access & (Opcodes.ACC_PUBLIC | Opcodes.ACC_PROTECTED)) != 0
                || !EDITOR_SESSION_MANAGER.equals(subject.nestHost)) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "RAW_TRANSITION_SCOPE_SHAPE",
                            "Raw proof types must be package-confined exact ESM nestmates"));
        }

        if (subject.name.equals(RAW_PROOF_STATE)) {
            List<String> constants = subject.declaredFields.stream()
                    .filter(field -> field.descriptor.equals("L" + RAW_PROOF_STATE + ";"))
                    .map(FieldDeclaration::name)
                    .toList();
            if ((subject.access & Opcodes.ACC_ENUM) == 0
                    || !"java/lang/Enum".equals(subject.superName)
                    || !subject.interfaces.isEmpty()
                    || !constants.equals(List.of("COMMITTED", "ORIGINAL", "UNDO", "RAW"))) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "RAW_TRANSITION_SCOPE_SHAPE",
                            "RawProofState must contain only COMMITTED, ORIGINAL, UNDO and RAW"));
            }
            return;
        }

        List<String> expectedFields = List.of(
                "ownerStamp:Ljava/lang/Object;",
                "expectedEpoch:J",
                "expectedToken:J",
                "expectedAuthorityRevision:J",
                "expectedEditor:L" + EDITOR_SESSION_MANAGER + "$ActiveEditor;",
                "managerSelection:Lcom/opentypeless/android/editor/TextRange;",
                "provenFromSelection:Lcom/opentypeless/android/editor/TextRange;",
                "targetSelection:Lcom/opentypeless/android/editor/TextRange;",
                "targetState:L" + RAW_PROOF_STATE + ";",
                "expectedOrigin:Lcom/opentypeless/android/editor/EditorSessionSnapshot;",
                "expectedInsertedFingerprint:Lcom/opentypeless/android/editor/TextFingerprint;",
                "expectedReplacementFingerprint:Lcom/opentypeless/android/editor/TextFingerprint;",
                "claimed:Z");
        List<String> observedFields = subject.declaredFields.stream()
                .map(field -> field.name + ":" + field.descriptor)
                .toList();
        boolean fieldModifiers = subject.declaredFields.size() == expectedFields.size();
        for (int index = 0; fieldModifiers && index < subject.declaredFields.size(); index++) {
            FieldDeclaration field = subject.declaredFields.get(index);
            int required = Opcodes.ACC_PRIVATE;
            if (!field.name.equals("claimed")) required |= Opcodes.ACC_FINAL;
            int forbidden = field.name.equals("claimed") ? Opcodes.ACC_FINAL : 0;
            fieldModifiers = (field.access & required) == required
                    && (field.access & forbidden) == 0
                    && (field.access & Opcodes.ACC_STATIC) == 0;
        }
        List<MethodDeclaration> methods = subject.declaredMethods.stream()
                .filter(method -> !method.name.equals("<clinit>"))
                .toList();
        boolean exactMethods = methods.size() == 2
                && methods.stream().anyMatch(method -> method.name.equals("<init>")
                        && method.descriptor.equals(rawTransitionConstructorDescriptor())
                        && (method.access & Opcodes.ACC_PRIVATE) != 0)
                && methods.stream().anyMatch(method -> method.name.equals("toString")
                        && method.descriptor.equals("()Ljava/lang/String;"));
        if ((subject.access & (Opcodes.ACC_FINAL
                                | Opcodes.ACC_INTERFACE
                                | Opcodes.ACC_ABSTRACT
                                | Opcodes.ACC_ENUM
                                | Opcodes.ACC_RECORD))
                        != Opcodes.ACC_FINAL
                || !"java/lang/Object".equals(subject.superName)
                || !subject.interfaces.isEmpty()
                || !observedFields.equals(expectedFields)
                || !fieldModifiers
                || !exactMethods) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "RAW_TRANSITION_SCOPE_SHAPE",
                            "RawTransition exact owner/authority/fingerprint field surface drifted"));
        }
        if (!hasFixedStringReturn(
                subject, "toString", "()Ljava/lang/String;", "RawTransition{<redacted>}")) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "RAW_TRANSITION_REDACTION",
                            "toString must return only the fixed redacted marker"));
        }
        for (FieldDeclaration field : subject.declaredFields) {
            if (fieldCarriesCapability(field, capabilityTypes)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "RAW_TRANSITION_CAPABILITY_STORAGE",
                                field.name + field.descriptor));
            }
        }
        for (MethodDeclaration method : subject.declaredMethods) {
            if (methodDescriptorCarriesCapability(method.descriptor, capabilityTypes)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "RAW_TRANSITION_CAPABILITY_TRANSFER",
                                method.name + method.descriptor));
            }
        }
    }

    private static void inspectRawTransitionHostBinding(
            String variant, ClassInfo subject, List<Violation> violations) {
        boolean exactStamp = subject.declaredFields.stream()
                .anyMatch(field -> field.name.equals("rawTransitionOwnerStamp")
                        && field.descriptor.equals("Ljava/lang/Object;")
                        && (field.access & (Opcodes.ACC_PRIVATE | Opcodes.ACC_FINAL))
                                == (Opcodes.ACC_PRIVATE | Opcodes.ACC_FINAL)
                        && (field.access & Opcodes.ACC_STATIC) == 0);
        MethodNode prepare = subject.methodNodes.stream()
                .filter(method -> method.name.equals("prepareRawTransition")
                        && method.desc.equals(PREPARE_RAW_TRANSITION_DESCRIPTOR))
                .findFirst()
                .orElse(null);
        MethodNode validate = subject.methodNodes.stream()
                .filter(method -> method.name.equals("validateRawTransitionState")
                        && method.desc.equals(VALIDATE_RAW_TRANSITION_DESCRIPTOR))
                .findFirst()
                .orElse(null);
        boolean prepareReadsStamp = readsField(
                prepare,
                Opcodes.GETFIELD,
                EDITOR_SESSION_MANAGER,
                "rawTransitionOwnerStamp",
                "Ljava/lang/Object;");
        boolean validateReadsHostStamp = readsField(
                validate,
                Opcodes.GETFIELD,
                EDITOR_SESSION_MANAGER,
                "rawTransitionOwnerStamp",
                "Ljava/lang/Object;");
        boolean validateReadsTokenStamp = readsField(
                validate,
                Opcodes.GETFIELD,
                RAW_TRANSITION,
                "ownerStamp",
                "Ljava/lang/Object;");
        boolean identityBranch = validate != null && Arrays.stream(validate.instructions.toArray())
                .anyMatch(instruction -> instruction.getOpcode() == Opcodes.IF_ACMPEQ
                        || instruction.getOpcode() == Opcodes.IF_ACMPNE);
        if (!(exactStamp
                && prepareReadsStamp
                && validateReadsHostStamp
                && validateReadsTokenStamp
                && identityBranch)) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "RAW_TRANSITION_OWNER_BINDING",
                            "RawTransition must be minted and consumed against exact owner stamp"));
        }
    }

    private static void inspectReplaceTransitionHostBinding(
            String variant, ClassInfo subject, List<Violation> violations) {
        boolean exactStamp = subject.declaredFields.stream()
                .anyMatch(field -> field.name.equals("replaceTransitionOwnerStamp")
                        && field.descriptor.equals("Ljava/lang/Object;")
                        && (field.access & (Opcodes.ACC_PRIVATE | Opcodes.ACC_FINAL))
                                == (Opcodes.ACC_PRIVATE | Opcodes.ACC_FINAL)
                        && (field.access & Opcodes.ACC_STATIC) == 0);
        MethodNode prepare = subject.methodNodes.stream()
                .filter(method -> method.name.equals("prepareReplaceTransition")
                        && method.desc.equals(PREPARE_REPLACE_TRANSITION_DESCRIPTOR))
                .findFirst()
                .orElse(null);
        MethodNode validate = subject.methodNodes.stream()
                .filter(method -> method.name.equals("validateReplaceTransitionState")
                        && method.desc.equals(VALIDATE_REPLACE_TRANSITION_DESCRIPTOR))
                .findFirst()
                .orElse(null);
        boolean prepareReadsStamp = readsField(
                prepare,
                Opcodes.GETFIELD,
                EDITOR_SESSION_MANAGER,
                "replaceTransitionOwnerStamp",
                "Ljava/lang/Object;");
        boolean validateReadsHostStamp = readsField(
                validate,
                Opcodes.GETFIELD,
                EDITOR_SESSION_MANAGER,
                "replaceTransitionOwnerStamp",
                "Ljava/lang/Object;");
        boolean validateReadsTokenStamp = readsField(
                validate,
                Opcodes.GETFIELD,
                REPLACE_TRANSITION,
                "ownerStamp",
                "Ljava/lang/Object;");
        boolean readsClaimed = readsField(
                validate,
                Opcodes.GETFIELD,
                REPLACE_TRANSITION,
                "claimed",
                "Z");
        boolean writesClaimed = readsField(
                validate,
                Opcodes.PUTFIELD,
                REPLACE_TRANSITION,
                "claimed",
                "Z");
        boolean identityBranch = validate != null
                && Arrays.stream(validate.instructions.toArray())
                        .anyMatch(instruction -> instruction.getOpcode() == Opcodes.IF_ACMPEQ
                                || instruction.getOpcode() == Opcodes.IF_ACMPNE);
        if (!(exactStamp
                && prepareReadsStamp
                && validateReadsHostStamp
                && validateReadsTokenStamp
                && readsClaimed
                && writesClaimed
                && identityBranch)) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "REPLACE_TRANSITION_OWNER_BINDING",
                            "ReplaceTransition must be one-shot and bound to the exact owner stamp"));
        }
    }

    private static boolean readsField(
            MethodNode method,
            int opcode,
            String owner,
            String name,
            String descriptor) {
        return method != null && Arrays.stream(method.instructions.toArray())
                .anyMatch(instruction -> instruction instanceof FieldInsnNode field
                        && field.getOpcode() == opcode
                        && field.owner.equals(owner)
                        && field.name.equals(name)
                        && field.desc.equals(descriptor));
    }

    private static long fieldAccessCount(
            MethodNode method,
            int opcode,
            String owner,
            String name,
            String descriptor) {
        if (method == null) return 0L;
        return Arrays.stream(method.instructions.toArray())
                .filter(instruction -> instruction instanceof FieldInsnNode field
                        && field.getOpcode() == opcode
                        && field.owner.equals(owner)
                        && field.name.equals(name)
                        && field.desc.equals(descriptor))
                .count();
    }

    private static boolean fieldReadsFeedNullCheck(
            MethodNode method,
            int opcode,
            String owner,
            String name,
            String descriptor) {
        if (method == null) return false;
        AbstractInsnNode[] instructions = method.instructions.toArray();
        int matches = 0;
        for (int index = 0; index < instructions.length; index++) {
            AbstractInsnNode instruction = instructions[index];
            if (!(instruction instanceof FieldInsnNode field)
                    || field.getOpcode() != opcode
                    || !field.owner.equals(owner)
                    || !field.name.equals(name)
                    || !field.desc.equals(descriptor)) {
                continue;
            }
            matches++;
            int next = index + 1;
            while (next < instructions.length && instructions[next].getOpcode() < 0) next++;
            if (next >= instructions.length
                    || !(instructions[next] instanceof JumpInsnNode jump)
                    || (jump.getOpcode() != Opcodes.IFNULL
                            && jump.getOpcode() != Opcodes.IFNONNULL)) {
                return false;
            }
        }
        return matches == 1;
    }

    private static boolean isCollectionBackedField(FieldDeclaration field) {
        String value = field.descriptor + Objects.toString(field.signature, "");
        return value.contains("Ljava/util/Map")
                || value.contains("Ljava/util/HashMap")
                || value.contains("Ljava/util/LinkedHashMap")
                || value.contains("Ljava/util/Collection")
                || value.contains("Ljava/util/List")
                || value.contains("Ljava/util/Set")
                || value.contains("Ljava/util/Queue")
                || value.contains("Ljava/util/Deque");
    }

    private static boolean fieldCarriesCapability(
            FieldDeclaration field, Set<String> capabilityTypes) {
        Type type = Type.getType(field.descriptor);
        if (typeCarriesCapability(type, capabilityTypes)) return true;
        if (field.signature == null) return false;
        return capabilityTypes.stream().anyMatch(typeName -> field.signature.contains(typeName));
    }

    private static boolean constructorStoresCurrentThread(ClassInfo subject, String fieldName) {
        for (MethodNode method : subject.methodNodes) {
            if (!method.name.equals("<init>")) continue;
            AbstractInsnNode[] instructions = method.instructions.toArray();
            for (int index = 0; index < instructions.length; index++) {
                AbstractInsnNode instruction = instructions[index];
                if (!(instruction instanceof MethodInsnNode call)
                        || call.getOpcode() != Opcodes.INVOKESTATIC
                        || !call.owner.equals("java/lang/Thread")
                        || !call.name.equals("currentThread")
                        || !call.desc.equals("()Ljava/lang/Thread;")) {
                    continue;
                }
                for (int following = index + 1; following < instructions.length; following++) {
                    AbstractInsnNode next = instructions[following];
                    if (next.getOpcode() < 0) continue;
                    return next instanceof FieldInsnNode field
                            && next.getOpcode() == Opcodes.PUTFIELD
                            && field.owner.equals(COMMIT_LEDGER)
                            && field.name.equals(fieldName)
                            && field.desc.equals("Ljava/lang/Thread;");
                }
            }
        }
        return false;
    }

    private static boolean ownerGuardChecksCurrentThread(ClassInfo subject, String fieldName) {
        for (MethodNode method : subject.methodNodes) {
            if (!method.name.equals("requireOwnerThread") || !method.desc.equals("()V")) continue;
            boolean currentThread = false;
            boolean ownerRead = false;
            boolean identityBranch = false;
            boolean throwsStateFailure = false;
            for (AbstractInsnNode instruction : method.instructions.toArray()) {
                if (instruction instanceof MethodInsnNode call
                        && call.getOpcode() == Opcodes.INVOKESTATIC
                        && call.owner.equals("java/lang/Thread")
                        && call.name.equals("currentThread")
                        && call.desc.equals("()Ljava/lang/Thread;")) {
                    currentThread = true;
                } else if (instruction instanceof FieldInsnNode field
                        && field.getOpcode() == Opcodes.GETFIELD
                        && field.owner.equals(COMMIT_LEDGER)
                        && field.name.equals(fieldName)
                        && field.desc.equals("Ljava/lang/Thread;")) {
                    ownerRead = true;
                } else if (instruction.getOpcode() == Opcodes.IF_ACMPEQ
                        || instruction.getOpcode() == Opcodes.IF_ACMPNE) {
                    identityBranch = true;
                } else if (instruction instanceof TypeInsnNode type
                        && type.getOpcode() == Opcodes.NEW
                        && type.desc.equals("java/lang/IllegalStateException")) {
                    throwsStateFailure = true;
                }
            }
            return currentThread && ownerRead && identityBranch && throwsStateFailure;
        }
        return false;
    }

    private static void addDescriptorTypeNames(String descriptor, Set<String> output) {
        List<TypeEdge> edges = new ArrayList<>();
        ClassFileParser.addDescriptorTypes(descriptor, EdgeKind.METHOD_DESCRIPTOR, edges);
        for (TypeEdge edge : edges) {
            if (edge.type != null) output.add(edge.type);
        }
    }

    private static void addSignatureTypeNames(String signature, Set<String> output) {
        List<TypeEdge> edges = new ArrayList<>();
        ClassFileParser.addSignatureTypes(signature, EdgeKind.METHOD_SIGNATURE, edges);
        for (TypeEdge edge : edges) {
            if (edge.type != null) output.add(edge.type);
        }
    }

    private static Set<String> identifierTokens(String value) {
        String separated = value.replaceAll("(?<=[a-z0-9])(?=[A-Z])", "_");
        Set<String> result = new HashSet<>();
        for (String token : separated.toLowerCase(Locale.ROOT).split("_")) {
            if (!token.isEmpty()) result.add(token);
        }
        return Set.copyOf(result);
    }

    private static boolean isThrowableLike(String type) {
        if (type == null) return false;
        int slash = type.lastIndexOf('/');
        String simple = slash < 0 ? type : type.substring(slash + 1);
        return type.equals("java/lang/Throwable")
                || simple.endsWith("Throwable")
                || simple.endsWith("Exception")
                || simple.endsWith("Error");
    }

    private static boolean isCommitExecutionType(String type) {
        if (type == null) return false;
        if (COMMIT_EXECUTION_TYPES.contains(type)) return true;
        for (String prefix : COMMIT_EXECUTION_PREFIXES) {
            if (type.startsWith(prefix)) return true;
        }
        return false;
    }

    private static boolean isSerializationType(String type) {
        if (type == null) return false;
        if (SERIALIZATION_TYPES.contains(type)) return true;
        for (String prefix : SERIALIZATION_PREFIXES) {
            if (type.startsWith(prefix)) return true;
        }
        return false;
    }

    private static void inspectTransactionCapabilityShape(
            String variant,
            ClassInfo subject,
            Set<String> capabilityTypes,
            List<Violation> violations) {
        boolean storesCapability =
                subject.typeEdges.stream()
                        .anyMatch(
                                edge ->
                                        (edge.kind == EdgeKind.FIELD_DESCRIPTOR
                                                        || edge.kind == EdgeKind.FIELD_SIGNATURE)
                                                && capabilityTypes.contains(edge.type));
        if (storesCapability) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "EDITOR_TRANSACTION_CAPABILITY_STORAGE",
                            "transaction manager and nestmates may not retain editor capabilities"));
        }
        for (MethodDeclaration method : subject.declaredMethods) {
            if (typeCarriesCapability(
                    Type.getReturnType(method.descriptor), capabilityTypes)) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "EDITOR_TRANSACTION_CAPABILITY_RETURN",
                                method.name + method.descriptor));
            }
        }
    }

    /**
     * Tracks the exact InputConnection capability through erased Object locals and stack values.
     * Descriptor checks alone cannot see {@code Object retained = connection}, an Object return,
     * or a call such as {@code thirdParty.accept((Object) connection)}.
     */
    private static void inspectTransactionCapabilityFlow(
            String variant,
            ClassInfo subject,
            Set<String> capabilityTypes,
            List<Violation> violations) {
        CapabilityInterpreter interpreter = new CapabilityInterpreter(capabilityTypes);
        for (MethodNode method : subject.methodNodes) {
            Frame<BasicValue>[] frames;
            try {
                frames = new Analyzer<>(interpreter).analyze(subject.name, method);
            } catch (AnalyzerException | RuntimeException unavailable) {
                violations.add(
                        violation(
                                variant,
                                subject,
                                "EDITOR_TRANSACTION_TAINT_ANALYSIS",
                                method.name + method.desc + " could not be proven safe"));
                continue;
            }

            AbstractInsnNode[] instructions = method.instructions.toArray();
            for (int index = 0; index < instructions.length; index++) {
                Frame<BasicValue> frame = frames[index];
                if (frame == null) continue;
                AbstractInsnNode instruction = instructions[index];
                int opcode = instruction.getOpcode();

                if (instruction instanceof TypeInsnNode typeInstruction
                        && opcode == Opcodes.CHECKCAST
                        && typeInstructionCarriesCapability(
                                typeInstruction.desc, capabilityTypes)) {
                    violations.add(
                            violation(
                                    variant,
                                    subject,
                                    "EDITOR_TRANSACTION_CAPABILITY_PROVENANCE",
                                    method.name + method.desc + " -> CHECKCAST "
                                            + typeInstruction.desc));
                    continue;
                }
                if (instruction instanceof FieldInsnNode field
                        && (opcode == Opcodes.PUTFIELD || opcode == Opcodes.PUTSTATIC)
                        && stackTopIsCapability(frame)) {
                    violations.add(
                            violation(
                                    variant,
                                    subject,
                                    "EDITOR_TRANSACTION_CAPABILITY_STORAGE",
                                    method.name + method.desc + " -> "
                                            + field.owner + "." + field.name + field.desc));
                    continue;
                }
                if (opcode == Opcodes.AASTORE && stackTopIsCapability(frame)) {
                    violations.add(
                            violation(
                                    variant,
                                    subject,
                                    "EDITOR_TRANSACTION_CAPABILITY_STORAGE",
                                    method.name + method.desc + " -> array-store"));
                    continue;
                }
                if ((opcode == Opcodes.ARETURN || opcode == Opcodes.ATHROW)
                        && stackTopIsCapability(frame)) {
                    violations.add(
                            violation(
                                    variant,
                                    subject,
                                    "EDITOR_TRANSACTION_CAPABILITY_RETURN",
                                    method.name + method.desc));
                    continue;
                }
                if (instruction instanceof MethodInsnNode call
                        && callConsumesCapability(call, frame)
                        && !isAllowedTransactionCapabilityCall(call, frame, capabilityTypes)) {
                    violations.add(
                            violation(
                                    variant,
                                    subject,
                                    "EDITOR_TRANSACTION_CAPABILITY_TRANSFER",
                                    method.name + method.desc + " -> "
                                            + call.owner + "." + call.name + call.desc));
                    continue;
                }
                if (instruction instanceof InvokeDynamicInsnNode dynamic
                        && dynamicConsumesCapability(dynamic, frame)
                        && !isAllowedScopedTransactionLambda(dynamic, frame, capabilityTypes)) {
                    violations.add(
                            violation(
                                    variant,
                                    subject,
                                    "EDITOR_TRANSACTION_CAPABILITY_TRANSFER",
                                    method.name + method.desc + " -> invokedynamic "
                                            + dynamic.name + dynamic.desc));
                }
            }
        }
    }

    private static boolean stackTopIsCapability(Frame<BasicValue> frame) {
        return frame.getStackSize() > 0
                && CapabilityInterpreter.isCapability(
                        frame.getStack(frame.getStackSize() - 1));
    }

    private static boolean callConsumesCapability(
            MethodInsnNode call, Frame<BasicValue> frame) {
        int arguments = Type.getArgumentTypes(call.desc).length;
        int firstArgument = frame.getStackSize() - arguments;
        if (firstArgument < 0) return true;
        for (int index = firstArgument; index < frame.getStackSize(); index++) {
            if (CapabilityInterpreter.isCapability(frame.getStack(index))) return true;
        }
        if (call.getOpcode() != Opcodes.INVOKESTATIC) {
            int receiver = firstArgument - 1;
            return receiver < 0
                    || CapabilityInterpreter.isCapability(frame.getStack(receiver));
        }
        return false;
    }

    private static boolean isAllowedTransactionCapabilityCall(
            MethodInsnNode call,
            Frame<BasicValue> frame,
            Set<String> capabilityTypes) {
        Type[] argumentTypes = Type.getArgumentTypes(call.desc);
        int firstArgument = frame.getStackSize() - argumentTypes.length;
        if (firstArgument < 0) return false;
        int receiver = call.getOpcode() == Opcodes.INVOKESTATIC ? -1 : firstArgument - 1;
        boolean receiverCapability = receiver >= 0
                && CapabilityInterpreter.isCapability(frame.getStack(receiver));

        if (receiverCapability
                && call.getOpcode() == Opcodes.INVOKEINTERFACE
                && member(call.owner, call.name, call.desc) != null
                && EDITOR_TRANSACTION_WRITE_SINKS.contains(
                        member(call.owner, call.name, call.desc))) {
            for (int index = 0; index < argumentTypes.length; index++) {
                if (CapabilityInterpreter.isCapability(frame.getStack(firstArgument + index))) {
                    return false;
                }
            }
            return true;
        }

        if (call.owner.equals(EDITOR_SESSION_MANAGER + "$HostLease")
                && call.name.equals("consumeWithCurrentConnection")
                && call.desc.equals(
                        "(Lcom/opentypeless/android/editor/host/EditorSessionManager$ScopedConnectionUse;)"
                                + "Lcom/opentypeless/android/editor/host/EditorSessionManager$ConnectionUseResult;")) {
            return argumentTypes.length == 1
                    && CapabilityInterpreter.isCapability(frame.getStack(firstArgument));
        }

        if (call.owner.equals(HOST_LEASE)
                && call.name.equals("consumeWithCurrentConnectionForReceipt")
                && call.desc.equals(
                        "(L" + SCOPED_RECEIPT_CONNECTION_USE + ";)L"
                                + RECEIPT_CONNECTION_USE_RESULT + ";")) {
            return argumentTypes.length == 1
                    && CapabilityInterpreter.isCapability(frame.getStack(firstArgument));
        }

        if (!call.owner.equals(EDITOR_TRANSACTION_MANAGER) || receiverCapability) return false;
        for (int index = 0; index < argumentTypes.length; index++) {
            BasicValue value = frame.getStack(firstArgument + index);
            if (CapabilityInterpreter.isCapability(value)
                    && !typeCarriesCapability(argumentTypes[index], capabilityTypes)) {
                return false;
            }
        }
        return true;
    }

    private static boolean dynamicConsumesCapability(
            InvokeDynamicInsnNode dynamic, Frame<BasicValue> frame) {
        int arguments = Type.getArgumentTypes(dynamic.desc).length;
        int firstArgument = frame.getStackSize() - arguments;
        if (firstArgument < 0) return true;
        for (int index = firstArgument; index < frame.getStackSize(); index++) {
            if (CapabilityInterpreter.isCapability(frame.getStack(index))) return true;
        }
        return false;
    }

    private static boolean isAllowedScopedTransactionLambda(
            InvokeDynamicInsnNode dynamic,
            Frame<BasicValue> frame,
            Set<String> capabilityTypes) {
        Type methodType = Type.getMethodType(dynamic.desc);
        Type result = methodType.getReturnType();
        if (result.getSort() != Type.OBJECT
                || !result.getInternalName().equals(
                        EDITOR_SESSION_MANAGER + "$ScopedConnectionUse")
                || !dynamic.bsm.getOwner().equals("java/lang/invoke/LambdaMetafactory")) {
            return false;
        }
        boolean exactImplementation = false;
        for (Object argument : dynamic.bsmArgs) {
            if (argument instanceof Handle handle
                    && handle.getOwner().equals(EDITOR_TRANSACTION_MANAGER)) {
                exactImplementation = true;
            }
        }
        if (!exactImplementation) return false;

        Type[] argumentTypes = methodType.getArgumentTypes();
        int firstArgument = frame.getStackSize() - argumentTypes.length;
        if (firstArgument < 0) return false;
        for (int index = 0; index < argumentTypes.length; index++) {
            BasicValue value = frame.getStack(firstArgument + index);
            if (CapabilityInterpreter.isCapability(value)
                    && !typeCarriesCapability(argumentTypes[index], capabilityTypes)) {
                return false;
            }
        }
        return true;
    }

    private static void inspectTransactionMethodEdge(
            String variant,
            ClassInfo subject,
            MethodEdge edge,
            Set<String> capabilityTypes,
            List<Violation> violations) {
        if (isAccessor(edge, capabilityTypes)
                || (capabilityTypes.contains(edge.owner)
                        && INPUT_METHOD_SERVICE_INDIRECT_SEND_NAMES.contains(edge.name))) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "EDITOR_TRANSACTION_INDIRECT_IME_ACCESS",
                            edge.owner + "." + edge.name + edge.descriptor));
        }
        if (isLegacyBinary(edge.owner)) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "EDITOR_TRANSACTION_LEGACY_TRANSFER",
                            edge.owner + "." + edge.name + edge.descriptor));
        }
        if (methodDescriptorCarriesCapability(edge.descriptor, capabilityTypes)
                && !(subject.name.equals(EDITOR_TRANSACTION_MANAGER)
                        && edge.owner.equals(EDITOR_TRANSACTION_MANAGER))) {
            violations.add(
                    violation(
                            variant,
                            subject,
                            "EDITOR_TRANSACTION_CAPABILITY_TRANSFER",
                            edge.owner + "." + edge.name + edge.descriptor));
        }
    }

    private static boolean isAllowedTransactionCapabilityConsumer(
            ClassInfo subject, Map<String, ClassRecord> project) {
        return subject.name.equals(EDITOR_TRANSACTION_MANAGER)
                || isExactOrNestmate(subject, TRANSACTION_SCOPED_CONSUMERS, project);
    }

    private static boolean isAllowedReceiptScopeConsumer(
            ClassInfo subject, Map<String, ClassRecord> project) {
        return isExactOrNestmate(subject, Set.of(EDITOR_SESSION_MANAGER), project)
                || isExactOrNestmate(subject, Set.of(EDITOR_TRANSACTION_MANAGER), project);
    }

    private static boolean isAllowedUndoEvidenceScopeConsumer(
            ClassInfo subject, Map<String, ClassRecord> project) {
        return isExactOrNestmate(subject, Set.of(EDITOR_SESSION_MANAGER), project)
                || isExactOrNestmate(subject, Set.of(EDITOR_TRANSACTION_MANAGER), project);
    }

    private static boolean isAllowedRawRestoreScopeConsumer(
            ClassInfo subject, Map<String, ClassRecord> project) {
        return isExactOrNestmate(subject, Set.of(EDITOR_SESSION_MANAGER), project)
                || isExactOrNestmate(subject, Set.of(EDITOR_TRANSACTION_MANAGER), project);
    }

    private static boolean isAllowedReplaceEvidenceScopeConsumer(
            ClassInfo subject, Map<String, ClassRecord> project) {
        return isExactOrNestmate(subject, Set.of(EDITOR_SESSION_MANAGER), project)
                || isExactOrNestmate(subject, Set.of(EDITOR_TRANSACTION_MANAGER), project);
    }

    private static boolean isLegacyBinary(String owner) {
        for (String legacy : LEGACY_OWNER_TOP_LEVELS) {
            if (owner.equals(legacy) || owner.startsWith(legacy + "$")) return true;
        }
        return false;
    }

    private static boolean methodDescriptorCarriesCapability(
            String descriptor, Set<String> capabilityTypes) {
        Type method = Type.getMethodType(descriptor);
        for (Type argument : method.getArgumentTypes()) {
            if (typeCarriesCapability(argument, capabilityTypes)) return true;
        }
        return typeCarriesCapability(method.getReturnType(), capabilityTypes);
    }

    private static boolean typeCarriesCapability(Type type, Set<String> capabilityTypes) {
        if (type.getSort() == Type.ARRAY) {
            return typeCarriesCapability(type.getElementType(), capabilityTypes);
        }
        return type.getSort() == Type.OBJECT
                && capabilityTypes.contains(type.getInternalName());
    }

    private static boolean typeInstructionCarriesCapability(
            String descriptorOrInternalName, Set<String> capabilityTypes) {
        Type type = descriptorOrInternalName.startsWith("[")
                ? Type.getType(descriptorOrInternalName)
                : Type.getObjectType(descriptorOrInternalName);
        return typeCarriesCapability(type, capabilityTypes);
    }

    private static boolean classCarriesCapability(ClassInfo info, Set<String> capabilityTypes) {
        if (capabilityTypes.contains(info.name)) return true;
        for (TypeEdge edge : info.typeEdges) {
            if (edge.kind != EdgeKind.LDC_TYPE && capabilityTypes.contains(edge.type)) return true;
        }
        return false;
    }

    private static boolean isMetadataOnlyCapabilityReference(
            ClassInfo info, Set<String> capabilityTypes) {
        if (!info.name.equals(HOME_ACTIVITY) && !info.name.equals(MAIN_ACTIVITY)) return false;
        return info.typeEdges.stream()
                .filter(edge -> capabilityTypes.contains(edge.type))
                .allMatch(edge -> edge.kind == EdgeKind.LDC_TYPE && IME_SERVICE.equals(edge.type));
    }

    private static boolean isTrustedCapabilityOwner(
            ClassInfo subject, Map<String, ClassRecord> project) {
        return subject.name.equals(EDITOR_TRANSACTION_MANAGER)
                || isExactOrNestmate(subject, EXACT_HOST_OWNERS, project)
                || subject.name.equals("com/opentypeless/android/ime/EditorEvidenceReader")
                || subject.name.equals(PROJECTION_CONNECTION)
                || isLegacyOwner(subject, project);
    }

    private static boolean isExactOrNestmate(
            ClassInfo subject, Set<String> exactHosts, Map<String, ClassRecord> project) {
        if (exactHosts.contains(subject.name)) return true;
        if (subject.nestHost == null || !exactHosts.contains(subject.nestHost)) return false;
        ClassRecord host = project.get(subject.nestHost);
        return host != null && host.info.nestMembers.contains(subject.name);
    }

    private static boolean isLegacyOwner(ClassInfo subject, Map<String, ClassRecord> project) {
        if (LEGACY_OWNER_TOP_LEVELS.contains(subject.name)) return true;
        if (subject.nestHost == null || !LEGACY_OWNER_TOP_LEVELS.contains(subject.nestHost)) {
            return false;
        }
        ClassRecord host = project.get(subject.nestHost);
        return host != null && host.info.nestMembers.contains(subject.name);
    }

    private static boolean hierarchicallyImeService(
            String subject, Set<String> capabilityTypes) {
        // Capability membership alone is intentionally not used for authorization. This is only a
        // narrow accessor exception for the real service binary; subclasses are rejected owners.
        return subject.equals(IME_SERVICE) && capabilityTypes.contains(subject);
    }

    private static boolean isWriteSink(MethodEdge edge, Set<String> capabilityTypes) {
        String exact = member(edge.owner, edge.name, edge.descriptor);
        if (WRITE_SINKS.contains(exact)) return true;
        if (INPUT_METHOD_SERVICE_INDIRECT_WRITE_SINKS.contains(exact)) return true;
        if (!capabilityTypes.contains(edge.owner)) return false;
        return WRITE_SINKS.contains(member(INPUT_CONNECTION, edge.name, edge.descriptor))
                || WRITE_SINKS.contains(member(PROJECTION_CONNECTION, edge.name, edge.descriptor))
                || INPUT_METHOD_SERVICE_INDIRECT_WRITE_SINKS.contains(
                        member(INPUT_METHOD_SERVICE, edge.name, edge.descriptor));
    }

    private static boolean isAccessor(MethodEdge edge, Set<String> capabilityTypes) {
        if (INPUT_CONNECTION_ACCESSORS.contains(member(edge.owner, edge.name, edge.descriptor))) {
            return true;
        }
        return capabilityTypes.contains(edge.owner)
                && ((edge.name.equals("getCurrentInputConnection")
                                && edge.descriptor.equals("()Landroid/view/inputmethod/InputConnection;"))
                        || (edge.name.equals("getCurrentInputBinding")
                                && edge.descriptor.equals("()Landroid/view/inputmethod/InputBinding;"))
                        || (edge.name.equals("getConnection")
                                && edge.descriptor.equals("()Landroid/view/inputmethod/InputConnection;")));
    }

    private static boolean isReflective(MethodEdge edge) {
        String key = edge.owner + "." + edge.name;
        return REFLECTION_MEMBERS.contains(key);
    }

    private static boolean isPureDomain(String name) {
        if (name.startsWith("com/opentypeless/android/editor/host/")) return false;
        if (name.startsWith(CONFIG_PREFIX)) return true;
        if (name.startsWith(EDITOR_DOMAIN_PREFIX)) return true;
        for (String prefix : SPEECH_DOMAIN_PREFIXES) {
            if (name.startsWith(prefix)) return true;
        }
        return false;
    }

    private static boolean isPureEditorDomain(String name) {
        return name.startsWith(EDITOR_DOMAIN_PREFIX)
                && !name.startsWith("com/opentypeless/android/editor/host/");
    }

    private static boolean isAndroidPlatformType(String type) {
        return type != null && (type.startsWith("android/") || type.startsWith("androidx/"));
    }

    private static Violation violation(
            String variant, ClassInfo subject, String rule, String detail) {
        return new Violation(variant, subject.name, rule, detail);
    }

    private static Set<String> buildWriteSinks() {
        Set<String> sinks = new LinkedHashSet<>();
        addInputConnectionSink(sinks, "deleteSurroundingText", "(II)Z");
        addInputConnectionSink(sinks, "deleteSurroundingTextInCodePoints", "(II)Z");
        addInputConnectionSink(sinks, "setComposingText", "(Ljava/lang/CharSequence;I)Z");
        addInputConnectionSink(
                sinks,
                "setComposingText",
                "(Ljava/lang/CharSequence;ILandroid/view/inputmethod/TextAttribute;)Z");
        addInputConnectionSink(sinks, "setComposingRegion", "(II)Z");
        addInputConnectionSink(
                sinks,
                "setComposingRegion",
                "(IILandroid/view/inputmethod/TextAttribute;)Z");
        addInputConnectionSink(sinks, "finishComposingText", "()Z");
        addInputConnectionSink(sinks, "commitText", "(Ljava/lang/CharSequence;I)Z");
        addInputConnectionSink(
                sinks,
                "commitText",
                "(Ljava/lang/CharSequence;ILandroid/view/inputmethod/TextAttribute;)Z");
        addInputConnectionSink(
                sinks,
                "commitCompletion",
                "(Landroid/view/inputmethod/CompletionInfo;)Z");
        addInputConnectionSink(
                sinks,
                "commitCorrection",
                "(Landroid/view/inputmethod/CorrectionInfo;)Z");
        addInputConnectionSink(sinks, "setSelection", "(II)Z");
        addInputConnectionSink(sinks, "performEditorAction", "(I)Z");
        addInputConnectionSink(sinks, "performContextMenuAction", "(I)Z");
        addInputConnectionSink(sinks, "beginBatchEdit", "()Z");
        addInputConnectionSink(sinks, "endBatchEdit", "()Z");
        addInputConnectionSink(sinks, "sendKeyEvent", "(Landroid/view/KeyEvent;)Z");
        addInputConnectionSink(sinks, "clearMetaKeyStates", "(I)Z");
        addInputConnectionSink(sinks, "closeConnection", "()V");
        addInputConnectionSink(sinks, "reportFullscreenMode", "(Z)Z");
        addInputConnectionSink(sinks, "performSpellCheck", "()Z");
        addInputConnectionSink(
                sinks, "performPrivateCommand", "(Ljava/lang/String;Landroid/os/Bundle;)Z");
        addInputConnectionSink(sinks, "requestCursorUpdates", "(I)Z");
        addInputConnectionSink(sinks, "requestCursorUpdates", "(II)Z");
        addInputConnectionSink(
                sinks,
                "performHandwritingGesture",
                "(Landroid/view/inputmethod/HandwritingGesture;Ljava/util/concurrent/Executor;Ljava/util/function/IntConsumer;)V");
        addInputConnectionSink(
                sinks,
                "previewHandwritingGesture",
                "(Landroid/view/inputmethod/PreviewableHandwritingGesture;Landroid/os/CancellationSignal;)Z");
        addInputConnectionSink(sinks, "setImeConsumesInput", "(Z)Z");
        addInputConnectionSink(
                sinks,
                "replaceText",
                "(IILjava/lang/CharSequence;ILandroid/view/inputmethod/TextAttribute;)Z");
        addInputConnectionSink(
                sinks,
                "commitContent",
                "(Landroid/view/inputmethod/InputContentInfo;ILandroid/os/Bundle;)Z");

        addProjectionSink(sinks, "beginBatchEdit", "()Z");
        addProjectionSink(sinks, "endBatchEdit", "()Z");
        addProjectionSink(sinks, "setComposingText", "(Ljava/lang/String;)Z");
        addProjectionSink(sinks, "finishComposingText", "()Z");
        addProjectionSink(sinks, "deleteSurroundingTextInCodePoints", "(II)Z");
        return Set.copyOf(sinks);
    }

    private static Set<String> buildEditorTransactionWriteSinks() {
        return Set.of(
                member(INPUT_CONNECTION, "beginBatchEdit", "()Z"),
                member(INPUT_CONNECTION, "commitText", "(Ljava/lang/CharSequence;I)Z"),
                member(INPUT_CONNECTION, "deleteSurroundingTextInCodePoints", "(II)Z"),
                member(INPUT_CONNECTION, "endBatchEdit", "()Z"),
                member(INPUT_CONNECTION, "finishComposingText", "()Z"),
                member(INPUT_CONNECTION, "performEditorAction", "(I)Z"),
                member(INPUT_CONNECTION, "setComposingText", "(Ljava/lang/CharSequence;I)Z"));
    }

